import { Book } from "@/lib/types";

export const _1samuel: Book = {
  id: "1samuel",
  name: "1. Samuel",
  shortName: "1.Sam",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Es war ein Mann von Ramatajim-Zofim*, vom Gebirge Ephraim*, und sein Name war Elkana*, ein Sohn des Jeroham, des Sohnes Elihus, des Sohnes Tohus*, des Sohnes Zufs, ein Ephraimiter*.", heading: "Samuels Eltern, Geburt und Weihe", footnotes: ["℘ V. 19", "℘ Kap. 9,4; Ri 4,5", "℘ 1Chr 6,12.19.20", "℘ 5Mo 25,7; 1Kö 21,8", "Im Hebr. steht eine Kurzform: Ephratiter\n℘ Kap. 17,12; Ri 12,5"] },
      { number: 2, text: "Und er hatte zwei Frauen: Der Name der einen war Hanna und der Name der anderen Peninna; Peninna hatte Kinder, aber Hanna hatte keine Kinder*.", footnotes: ["℘ 1Mo 11,30"] },
      { number: 3, text: "Und dieser Mann ging Jahr für Jahr aus seiner Stadt hinauf, um den HERRN der Heerscharen anzubeten und ihm in Silo* zu opfern*. Dort aber waren die beiden Söhne Elis, Hofni und Pinhas, Priester des HERRN.", footnotes: ["℘ Jos 18,1", "o. schlachten\n℘ Kap. 2,19"] },
      { number: 4, text: "Und es geschah immer an dem Tag, wenn Elkana opferte*, dann gab er seiner Frau Peninna und all ihren Söhnen und Töchtern die ihnen zukommenden Anteile*;", footnotes: ["o. schlachtete", "d. i. Opferfleisch"] },
      { number: 5, text: "aber Hanna gab er einen besonders großen Anteil*. Denn Hanna hatte er lieb; aber der HERR hatte ihren Mutterleib verschlossen*.", footnotes: ["w. einen Anteil des Angesichts; andere üs.: einen doppelten Anteil\n℘ 1Mo 43,34", "℘ 1Mo 11,30"] },
      { number: 6, text: "Und ihre Gegnerin reizte* sie mit vielen Kränkungen*, um sie zu demütigen, weil* der HERR ihren Mutterleib verschlossen hatte.", footnotes: ["w. kränkte", "℘ Kap. 2,1", "o. weil sie sich bedrückt zeigte, dass"] },
      { number: 7, text: "So geschah es Jahr für Jahr, immer, wenn sie zum Haus des HERRN hinaufzog, reizte* jene sie*. Dann weinte sie und aß nicht*.", footnotes: ["w. kränkte", "℘ Kap. 2,1", "℘ Ps 102,5"] },
      { number: 8, text: "Aber Elkana, ihr Mann, sagte zu ihr: Hanna, warum weinst du? Und warum isst du nicht? Und warum ist dein Herz betrübt? Bin ich dir nicht mehr wert als zehn Söhne*?", footnotes: ["℘ Rt 4,15"] },
      { number: 9, text: "Da stand Hanna auf, nachdem sie in Silo gegessen und getrunken hatten. Der Priester Eli aber saß auf einem Stuhl am Türpfosten des Tempels des HERRN." },
      { number: 10, text: "Und sie war in ihrer Seele verbittert*, und sie betete zum HERRN und weinte sehr*.", footnotes: ["℘ 1Mo 30,1; Hi 7,11", "℘ Jak 5,13"] },
      { number: 11, text: "Und sie legte ein Gelübde ab* und sprach: HERR der Heerscharen! Wenn du das Elend deiner Magd ansehen* und meiner gedenken und deine Magd nicht vergessen wirst und deiner Magd einen männlichen Nachkommen* geben wirst, so will ich ihn dem HERRN alle Tage seines Lebens geben. Und kein Schermesser soll auf sein Haupt kommen.", footnotes: ["w. gelobte ein Gelübde\n℘ 1Mo 28,20; 4Mo 30,7-9; Spr 31,2", "℘ 1Mo 29,32; Ri 13,5", "w. männlichen Samen"] },
      { number: 12, text: "Und es geschah, als sie lange vor dem HERRN betete*, achtete Eli auf ihren Mund.", footnotes: ["℘ Röm 12,12"] },
      { number: 13, text: "Hanna aber redete in ihrem Herzen*. Nur ihre Lippen bewegten sich, aber ihre Stimme hörte man nicht. Da meinte Eli, sie sei betrunken,", footnotes: ["℘ 1Mo 24,45"] },
      { number: 14, text: "und Eli sagte zu ihr: Wie lange willst du dich wie eine Betrunkene benehmen? Mach, dass du deinen Rausch los wirst*!", footnotes: ["w. Gib deinen Wein von dir"] },
      { number: 15, text: "Aber Hanna antwortete und sagte: Nein, mein Herr! Ich bin nichts anderes als eine betrübte Frau*. Wein und Rauschtrank habe ich nicht getrunken, sondern ich habe mein Herz* vor dem HERRN ausgeschüttet*.", footnotes: ["w. Frau mit beschwertem Geist\n℘ Spr 14,10", "w. meine Seele", "℘ Ps 62,9; Phil 4,6"] },
      { number: 16, text: "Halte deine Magd nicht für eine verkommene Frau*! Denn aus meinem großen Kummer* und Herzeleid habe ich so lange geredet.", footnotes: ["w. Tochter der Bosheit\n℘ 5Mo 13,14", "w. aus der Fülle meines Kummers"] },
      { number: 17, text: "Eli antwortete und sagte: Geh hin in Frieden!* Der Gott Israels wird dir deine Bitte erfüllen, die du von ihm erbeten hast*.", footnotes: ["℘ Kap. 20,42; 25,35; 29,7; 2Sam 15,9; Mk 5,34", "℘ Ps 20,5"] },
      { number: 18, text: "Sie sagte: Lass deine Magd Gunst finden vor deinen Augen*! Und die Frau ging ihres Weges und aß und hatte nicht mehr ein so trauriges Gesicht*.", footnotes: ["℘ 1Mo 32,6; Rt 2,13", "w. und ihr Gesicht war nicht mehr so traurig\n℘ Ps 34,6"] },
      { number: 19, text: "Und sie machten sich am nächsten Morgen früh auf und beteten an vor dem HERRN. Und sie kehrten zurück und kamen in ihr Haus nach Rama*. Und Elkana erkannte Hanna, seine Frau; und der HERR dachte an sie*.", footnotes: ["℘ V. 1; Kap. 2,11.20; 7,17; 8,4; 15,34; 16,13; 19,18; 25,1; Jos 18,25", "℘ 1Mo 30,22"] },
      { number: 20, text: "Und Hanna wurde schwanger. Und als die Tage um waren*, gebar sie einen Sohn. Und sie gab ihm den Namen Samuel*: Denn vom HERRN habe ich ihn erbeten*.", footnotes: ["w. Und es geschah nach Umlauf der Tage; d. h. viell.: als ein Jahr um war", "hebr. schemuel; d. h. von Gott erhört\n℘ Hebr 11,32", "℘ 1Chr 4,10; Ps 120,1; Mt 7,7"] },
      { number: 21, text: "Und der Mann Elkana zog mit seinem ganzen Haus wieder hinauf, um dem HERRN das jährliche Schlachtopfer zu opfern und sein Gelübde zu erfüllen*.", footnotes: ["℘ 5Mo 12,6"] },
      { number: 22, text: "Aber Hanna ging nicht mit hinauf; sondern sie sagte zu ihrem Mann: Wenn der Junge entwöhnt ist, will ich ihn bringen, dass er vor dem HERRN erscheint und dort für immer* bleibt.", footnotes: ["w. auf ewig"] },
      { number: 23, text: "Und ihr Mann Elkana sagte zu ihr: Tu, was gut ist in deinen Augen*! Bleibe, bis du ihn entwöhnt hast! Nur möge der HERR sein Wort aufrechthalten*! So blieb die Frau und stillte ihren Sohn, bis sie ihn entwöhnt hatte.", footnotes: ["℘ Kap. 14,36.40; 4Mo 30,8", "℘ 2Sam 7,25"] },
      { number: 24, text: "Und als sie ihn entwöhnt hatte*, nahm sie ihn mit sich hinauf nach Silo — dazu drei Stiere* und ein Efa Mehl und einen Schlauch Wein — und brachte ihn in das Haus des HERRN. Der Junge aber war noch jung.", footnotes: ["℘ 1Mo 21,8", "LXX: einen dreijährigen Stier"] },
      { number: 25, text: "Und sie schlachteten den Stier und brachten den Jungen zu Eli." },
      { number: 26, text: "Und sie sprach: Bitte, mein Herr! So wahr du lebst*, mein Herr, ich bin die Frau, die hier bei dir stand, um zum HERRN zu beten.", footnotes: ["w. So wahr deine Seele lebt\n℘ Kap. 17,55; 20,3; 25,26; 2Sam 11,11; 2Kö 2,2.4.6"] },
      { number: 27, text: "Um diesen Jungen habe ich gebetet, *und der HERR hat mir meine Bitte erfüllt, die ich von ihm erbeten habe*.", footnotes: ["w. und der HERR hat mir meine Bitte gewährt, die ich von ihm erbeten habe. 28 Und auch ich habe ihn dem HERRN zurückgewährt. Alle Tage, die er lebt, sei er ein dem HERRN Gewährter. — Die kursiv gedruckten Wörter sind im Hebr. verschiedene Formen desselben Wortstammes.", "℘ 1Chr 4,10; Ps 120,1; Mt 7,7"] },
      { number: 28, text: "So habe auch ich ihn dem HERRN wiedergegeben. All die Tage, die er lebt, soll er dem HERRN gehören*.* Und sie beteten dort den HERRN an*.", footnotes: ["℘ Kap. 2,20; 4Mo 6,8", "w. und der HERR hat mir meine Bitte gewährt, die ich von ihm erbeten habe. 28 Und auch ich habe ihn dem HERRN zurückgewährt. Alle Tage, die er lebt, sei er ein dem HERRN Gewährter. — Die kursiv gedruckten Wörter sind im Hebr. verschiedene Formen desselben Wortstammes.", "℘ Ri 7,15"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Und Hanna betete und sprach: Mein Herz jauchzt in dem HERRN, mein Horn* ist erhöht in dem HERRN. Mein Mund hat sich weit aufgetan gegen meine Feinde*, denn ich freue mich über deine Hilfe*.", heading: "Lobpreis der Hanna", footnotes: ["℘ V. 1-10: vgl. Lk 1,46-55", "℘ Ps 89,18", "℘ Kap. 1,6.7", "℘ 2Chr 20,27; Ps 21,2; 35,9"] },
      { number: 2, text: "Keiner ist so heilig wie der HERR*, denn außer dir ist keiner*. Und kein Fels ist wie unser Gott*.", footnotes: ["℘ 2Mo 15,11; 3Mo 11,45", "℘ 5Mo 4,35", "℘ 5Mo 32,4; 2Sam 22,32; Jes 44,8"] },
      { number: 3, text: "Häuft nicht Worte des Stolzes, noch gehe Freches aus eurem Mund hervor*! Denn der HERR ist ein Gott des Wissens*, und von ihm werden die Taten gewogen.", footnotes: ["℘ Ri 9,38; Ps 94,4", "℘ Jos 22,22"] },
      { number: 4, text: "Der Bogen der Helden ist zerbrochen*, und die Stürzenden haben sich mit Kraft umgürtet*.", footnotes: ["℘ Ps 46,10; Jer 51,56", "℘ Jes 40,29"] },
      { number: 5, text: "Die satt waren, müssen um Brot dienen, und die Hunger litten, brauchen es nicht mehr*. Sogar die Unfruchtbare hat sieben geboren*, und die viele Kinder hatte, welkt dahin*.", footnotes: ["d. h. um Brot zu dienen", "℘ Ps 113,9", "℘ Jes 54,1; Jer 15,9"] },
      { number: 6, text: "Der HERR tötet und macht lebendig*; er führt in den Scheol hinab und wieder herauf*.", footnotes: ["℘ 1Kö 17,22; 2Kö 5,7; Joh 5,21", "℘ 5Mo 32,39; Ps 30,4; 71,20"] },
      { number: 7, text: "Der HERR macht arm und macht reich*; er erniedrigt und erhöht*.", footnotes: ["℘ 1Chr 29,12; 2Chr 32,27.29; Hi 1,21", "℘ Ps 75,8; Spr 22,2; Hes 17,24"] },
      { number: 8, text: "Er hebt den Geringen aus dem Staub empor, aus dem Schmutz erhöht er den Armen, um ihn unter die Edlen zu setzen*; und den Thron der Ehre lässt er sie erben. Denn dem HERRN gehören die Säulen der Erde, und auf sie hat er den Erdkreis gestellt*.", footnotes: ["℘ Hi 36,7; Ps 107,41; 113,7.8; Pred 4,14; 1Kor 1,28; Jak 2,5", "℘ Hi 38,5.6; Ps 75,4; 104,5"] },
      { number: 9, text: "Die Füße seiner Frommen behütet er*, aber die Gottlosen kommen um in Finsternis*; denn niemand ist stark durch eigene Kraft*.", footnotes: ["℘ Kap. 25,26; Ps 105,37; 121,3; Spr 2,8", "℘ Ps 1,6; 145,20; Hi 18,18; 40,13; Jes 47,5; Nah 1,8", "℘ Ps 33,16"] },
      { number: 10, text: "Die mit dem HERRN rechten, werden niedergeschlagen werden, im Himmel wird er über ihnen donnern*. Der HERR wird richten die Enden der Erde. Er wird seinem König Macht verleihen und erhöhen das Horn seines Gesalbten*.", footnotes: ["℘ Kap. 7,10; 12,17; Ps 18,14", "℘ Ps 20,7; 132,17; Lk 1,69"] },
      { number: 11, text: "Und Elkana ging nach Rama* in sein Haus. Der Junge aber diente dem HERRN vor dem Priester Eli*.", footnotes: ["℘ Kap. 1,19", "℘ V. 18; Kap. 3,1"] },
      { number: 12, text: "Und die Söhne Elis waren ruchlose Männer*, sie hatten den HERRN nicht erkannt*.", heading: "Elis Söhne — Gerichtwort gegen Eli und seine Familie", footnotes: ["w. Söhne der Bosheit\n℘ 5Mo 13,14", "℘ Jer 2,8; Mal 2,6-8; Tit 1,16"] },
      { number: 13, text: "Und die Priester hatten dem Volk gegenüber die Gewohnheit: Wenn jemand ein Schlachtopfer darbrachte*, kam der Diener des Priesters, während das Fleisch noch kochte*, und hatte eine Gabel mit drei Zinken in seiner Hand", footnotes: ["w. schlachtete", "℘ Hes 46,20"] },
      { number: 14, text: "und stieß in den Tiegel oder in den Kessel oder in die Pfanne oder in den Topf. Alles, was er mit der Gabel herauszog*, nahm der Priester damit weg. So taten sie in Silo allen Israeliten, die dorthin kamen.", footnotes: ["LXX, die aram., syr. und lat. Üs.: für sich herauszog"] },
      { number: 15, text: "Sogar ehe man das Fett als Rauch aufsteigen ließ*, kam der Diener des Priesters und sagte zu dem Mann, der opferte: Gib Fleisch her zum Braten für den Priester! Denn er will von dir kein gekochtes Fleisch annehmen, sondern rohes.", footnotes: ["℘ 3Mo 3,3-5"] },
      { number: 16, text: "Wenn dann der Mann zu ihm sagte: Lass zuerst das Fett als Rauch aufsteigen, dann nimm dir, ganz wie es deine Seele begehrt! — so antwortete er: Nein, sondern jetzt sollst du es mir geben! Wenn nicht, so nehme ich es mit Gewalt!" },
      { number: 17, text: "Und die Sünde der jungen Männer war sehr groß vor dem HERRN*; denn die Männer verachteten die Opfergabe des HERRN*.", footnotes: ["℘ 1Mo 13,13", "℘ 1Kor 11,27.29"] },
      { number: 18, text: "Und Samuel diente vor dem HERRN, ein junger Mann, umgürtet mit einem leinenen Efod*.", footnotes: ["d. i. ein Priesterschurz\n℘ Kap. 14,3; 2Sam 6,14; 1Chr 15,27"] },
      { number: 19, text: "Und seine Mutter machte ihm ein kleines Oberkleid und brachte es ihm Jahr für Jahr hinauf, wenn sie mit ihrem Mann hinaufging, um das jährliche Schlachtopfer darzubringen*.", footnotes: ["w. zu schlachten\n℘ Kap. 1,3"] },
      { number: 20, text: "Und Eli segnete Elkana und seine Frau und sagte: Der HERR gebe dir Nachkommen* von dieser Frau anstelle des Erbetenen, das sie vom HERRN erbeten hat*! Und sie gingen nach Hause zurück.", footnotes: ["w. Samen", "w. des vom HERRN Gewährten, den sie (Hanna) dem HERRN zurückgewährt hat; vgl. Anm. zu Kap. 1,28\n℘ Kap. 1,28"] },
      { number: 21, text: "Und der HERR suchte Hanna heim*, und sie wurde schwanger; und sie gebar noch drei Söhne und zwei Töchter*. Und der Junge Samuel wuchs auf beim HERRN*.", footnotes: ["℘ 1Mo 21,1", "℘ Ps 127,3", "℘ Kap. 3,19; Ri 13,24; Spr 3,4; Lk 2,52"] },
      { number: 22, text: "Und Eli war sehr alt geworden. Und er hörte alles, was seine Söhne ganz Israel antaten und dass sie bei den Frauen lagen, die am Eingang des Zeltes der Begegnung Dienst taten*.", footnotes: ["Andere üs.: sich zusammenfanden\n℘ 2Mo 38,8"] },
      { number: 23, text: "Und er sprach zu ihnen: Warum tut ihr dergleichen Dinge? Denn ich höre diese eure bösen Taten von dem ganzen Volk." },
      { number: 24, text: "Nicht doch, meine Söhne! Denn das ist kein gutes Gerücht, von dem ich im Volk des HERRN reden höre*.", footnotes: ["o. Gerücht — von dem ich höre — dass ihr das Volk des HERRN zum Abweichen bringt; so auch die lat. Üs.\n℘ Mal 2,8"] },
      { number: 25, text: "Wenn jemand gegen einen Menschen sündigt, so entscheidet Gott über ihn*; wenn aber jemand gegen den HERRN sündigt, wer wird dann für ihn eintreten*? Aber sie hörten nicht auf die Stimme ihres Vaters, denn der HERR war entschlossen, sie zu töten*.", footnotes: ["℘ 5Mo 1,17; 1Kö 8,31.32", "℘ Hi 9,33", "w. wollte sie töten\n℘ 1Mo 38,7.10; Jos 11,20; 2Chr 10,15; Spr 13,1"] },
      { number: 26, text: "Der Junge Samuel aber nahm immer mehr zu an Alter und Gunst* bei dem HERRN und bei den Menschen*.", footnotes: ["o. wurde fortgehend größer und wohlgefälliger", "℘ Kap. 3,19; Ri 13,24; Spr 3,4; Lk 2,52"] },
      { number: 27, text: "Und es kam ein Mann Gottes* zu Eli und sagte zu ihm: So spricht der HERR: Habe ich mich nicht dem Hause deines Vaters deutlich offenbart, als sie in Ägypten im Haus des Pharao waren?", footnotes: ["℘ Kap. 9,6; 5Mo 33,1; Ri 13,6; 1Kö 13,1"] },
      { number: 28, text: "Und ich habe ihn aus allen Stämmen Israels mir zum Priester erwählt*, auf meinem Altar zu opfern, um Räucherwerk als Rauch aufsteigen zu lassen*, um das Efod* vor mir zu tragen. Und ich gab dem Haus deines Vaters alle Feueropfer der Söhne Israel*.", footnotes: ["℘ 2Mo 28,1", "℘ 2Mo 30,7", "d. i. ein Priesterschurz", "℘ 3Mo 2,3.10"] },
      { number: 29, text: "Warum tretet ihr mit Füßen mein Schlachtopfer und mein Speisopfer, die ich für meine Wohnung geboten habe? Und du ehrst deine Söhne mehr als mich, dass ihr euch mästet von den Erstlingen aller Opfergaben meines Volkes Israel." },
      { number: 30, text: "Darum spricht der HERR*, der Gott Israels: Ich habe allerdings gesagt: Dein Haus und das Haus deines Vaters sollen ewig vor mir einhergehen*! — aber nun spricht der HERR*: Das sei fern von mir*! Denn die mich ehren, werde auch ich ehren*, und die mich verachten, sollen wieder verachtet werden*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 2Mo 29,9", "w. ist der Ausspruch des HERRN", "w. Etwas Entweihtes sei es mir", "℘ Mt 26,13", "℘ 2Chr 26,18; Ps 18,26.27; Spr 12,8; Mal 2,3"] },
      { number: 31, text: "Siehe, Tage kommen, da werde ich deinen Arm und den Arm des Hauses deines Vaters abhauen*, dass es keinen Greis mehr in deinem Haus geben wird.", footnotes: ["℘ Kap. 3,12.13; 1Kö 2,27; Ps 37,17"] },
      { number: 32, text: "Und du wirst deinen Feind im Heiligtum* sehen, bei allem, was der HERR Gutes tun wird an Israel. Und es wird keinen Greis mehr in deinem Haus geben alle Tage.", footnotes: ["w. in der Wohnung; d. i. der Tempel in Silo"] },
      { number: 33, text: "Doch nicht jeden werde ich dir von meinem Altar ausrotten, um deine Augen erlöschen und deine Seele verschmachten zu lassen; aber aller Nachwuchs deines Hauses soll im besten Mannesalter sterben*.", footnotes: ["℘ Kap. 22,18-20"] },
      { number: 34, text: "Und das soll dir das Zeichen sein, das über deine beiden Söhne Hofni und Pinhas kommen wird: An einem Tag sollen beide sterben*.", footnotes: ["℘ Kap. 4,11"] },
      { number: 35, text: "Ich aber werde mir einen Priester erwecken, der beständig* ist; der wird tun, wie es meinem Herzen und meiner Seele gefällt*. Und ich werde ihm ein Haus bauen, das beständig ist, und er wird vor meinem Gesalbten alle Tage einhergehen*.", footnotes: ["d. h. treu", "w. in meinem Herzen und in meiner Seele ist", "℘ 1Kö 2,35; Hes 44,15.16"] },
      { number: 36, text: "Und es soll geschehen, dass jeder, der von deinem Haus noch übrig bleibt, kommen wird, um sich vor ihm niederzuwerfen für eine kleine Silbermünze und ein Stück Brot*, und wird sagen: Gib mir doch Anteil an einem der Priesterdienste, dass ich einen Bissen Brot zu essen habe*!", footnotes: ["w. einen Fladen Brot", "℘ Ri 17,10; 2Kö 23,9"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und der Junge Samuel diente dem HERRN vor Eli*. Und das Wort des HERRN war selten in jenen Tagen; Visionen gab es* nicht häufig*.", heading: "Samuels Berufung zum Propheten", footnotes: ["℘ Kap. 2,11.18", "w. eine Vision war", "℘ Ps 74,9"] },
      { number: 2, text: "Und es geschah in jener Zeit, dass Eli an seinem Ort lag — seine Augen aber hatten angefangen, schwach zu werden, so dass er nicht mehr sehen konnte* —,", footnotes: ["℘ Kap. 4,15; 1Mo 27,1"] },
      { number: 3, text: "und die Lampe Gottes war noch nicht erloschen*, und Samuel lag im Tempel des HERRN, wo die Lade Gottes war,", footnotes: ["℘ 2Mo 27,20"] },
      { number: 4, text: "da rief der HERR den Samuel. Und er antwortete: Hier bin ich!*", footnotes: ["℘ 1Mo 22,1"] },
      { number: 5, text: "Und er lief zu Eli und sagte: Hier bin ich! Du hast mich gerufen. Er aber sagte: Ich habe nicht gerufen. Leg dich wieder schlafen! Und er ging hin und legte sich schlafen." },
      { number: 6, text: "Und der HERR rief noch einmal: Samuel! Und Samuel stand auf und ging zu Eli und sagte: Hier bin ich, denn du hast mich gerufen. Und er antwortete: Ich habe nicht gerufen, mein Sohn. Leg dich wieder hin!" },
      { number: 7, text: "Samuel aber hatte den HERRN noch nicht erkannt*, und das Wort des HERRN war ihm noch nicht offenbart worden.", footnotes: ["℘ Joh 1,31.33"] },
      { number: 8, text: "Und der HERR rief wieder, zum dritten Mal: Samuel! Und er stand auf, ging zu Eli und sagte: Hier bin ich! Denn du hast mich gerufen. Da merkte Eli, dass der HERR den Jungen rief." },
      { number: 9, text: "Und Eli sagte zu Samuel: Geh hin, leg dich schlafen! Und so soll es sein, wenn er dich ruft, antworte: Rede, HERR, denn dein Knecht hört*! Und Samuel ging hin und legte sich an seinen Ort.", footnotes: ["℘ Ps 85,9"] },
      { number: 10, text: "Und der HERR kam und trat herzu und rief wie vorher*: Samuel, Samuel! Und Samuel antwortete: Rede, denn dein Knecht hört*!", footnotes: ["w. das eine Mal wie das andere Mal", "℘ Jos 5,14"] },
      { number: 11, text: "Da sprach der HERR zu Samuel: Siehe, ich will etwas tun in Israel, dass jedem, der es hört, beide Ohren gellen sollen*.", footnotes: ["℘ Kap. 4,10.11; 2Kö 21,12; Jer 19,3"] },
      { number: 12, text: "An jenem Tage werde ich über Eli alles kommen lassen, was ich gegen sein Haus geredet habe*: Ich will es anfangen und vollenden*.", footnotes: ["℘ Kap. 2,31-34; 4,11", "℘ 4Mo 23,19"] },
      { number: 13, text: "Denn ich habe ihm mitgeteilt, dass ich sein Haus für ewig richten will um der Schuld willen, denn er hat erkannt, dass seine Söhne sich den Fluch zuzogen*, aber er hat ihnen nicht gewehrt*.", footnotes: ["LXX: Gott verachteten", "℘ 1Kö 1,6; 1Tim 3,4.5"] },
      { number: 14, text: "Und darum habe ich dem Haus Elis geschworen: Wenn jemals die Schuld des Hauses Elis gesühnt werden soll durch Schlachtopfer oder durch Speisopfer, ewig*!", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ 4Mo 15,30.31"] },
      { number: 15, text: "Und Samuel lag bis zum Morgen. Dann machte er die Türen des Hauses des HERRN auf. Und Samuel fürchtete sich, Eli die Erscheinung mitzuteilen." },
      { number: 16, text: "Da rief Eli Samuel und sagte: Samuel, mein Sohn! Er antwortete: Hier bin ich!" },
      { number: 17, text: "Und er fragte: Was ist das für ein Wort, das er dir gesagt hat*? Verschweige mir ja nichts*! So tue dir Gott und so füge er hinzu*, wenn du mir etwas verschweigst von allen Worten, die er dir gesagt hat!", footnotes: ["℘ 4Mo 23,17", "℘ Jer 38,14", "d. i. eine Schwurformel; gemeint ist: Gottes Zorn komme über dich!\n℘ Kap. 14,44; 20,13; 25,22; Rt 1,17; 2Kö 6,31; 2Sam 3,9.35"] },
      { number: 18, text: "Da teilte ihm Samuel all die Worte mit und verschwieg ihm nichts. Und Eli sagte: Er ist der HERR; er tue, was in seinen Augen gut ist!*", footnotes: ["℘ Ri 10,15; 2Sam 10,12; 1Chr 19,13"] },
      { number: 19, text: "Und Samuel wuchs heran*. Und der HERR war mit ihm* und ließ keins von allen seinen Worten auf die Erde fallen*.", footnotes: ["w. wurde groß\n℘ Kap. 2,26", "℘ Kap. 10,7; 16,18; 18,12.14; 1Mo 39,2.3.21.23", "℘ Kap. 9,6; Jos 21,45; 2Kö 10,10; 15,12; 22,16; Jes 55,11"] },
      { number: 20, text: "Und ganz Israel, von Dan bis Beerscheba*, erkannte, dass Samuel zum Propheten des HERRN bestellt worden war*.", footnotes: ["℘ Ri 20,1", "w. bestätigt worden war; o. eine Vertrauensstelle erhalten hatte\n℘ 5Mo 18,21.22; Hes 33,33; Am 2,11; Apg 13,20"] },
      { number: 21, text: "Und der HERR fuhr fort, in Silo zu erscheinen*; denn der HERR offenbarte sich dem Samuel in Silo durch das Wort des HERRN*.", footnotes: ["℘ 4Mo 12,6", "℘ Kap. 9,15; Hebr 1,1"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und das Wort Samuels erging an ganz Israel*.*Und Israel zog aus, den Philistern entgegen zum Kampf: Und sie lagerten sich bei Eben-Eser*, und die Philister lagerten zu Afek*.", heading: "Gericht über Eli und seine Söhne — Verlust der Bundeslade", footnotes: ["℘ Kap. 10,19; 5Mo 29,10.11", "LXX fügt an dieser Stelle hinzu: In jenen Tagen geschah es, dass die Philister sich zum Kampf gegen Israel sammelten.", "d. h. Stein der Hilfe\n℘ Kap. 5,1; 7,12", "℘ Kap. 29,1; Jos 15,53; 1Kö 20,26"] },
      { number: 2, text: "Und die Philister stellten sich Israel gegenüber auf. Und der Kampf breitete sich aus, und Israel wurde von den Philistern geschlagen*; und sie erschlugen in den Schlachtreihen auf dem Feld etwa viertausend Mann.", footnotes: ["℘ 3Mo 26,37; 4Mo 14,45"] },
      { number: 3, text: "Und als das Volk ins Lager zurückkam, sagten die Ältesten von Israel: Warum hat uns der HERR heute vor den Philistern geschlagen*? Lasst uns von Silo die Lade des Bundes des HERRN zu uns holen, dass er in unsere Mitte komme und uns aus der Hand unserer Feinde rette*!", footnotes: ["℘ Ps 74,11; Jes 59,1.2", "℘ 4Mo 10,35"] },
      { number: 4, text: "Da sandte das Volk nach Silo. Und man brachte von dort die Lade des Bundes des HERRN der Heerscharen, der über den Cherubim thront*. Und die beiden Söhne Elis, Hofni und Pinhas*, waren dort bei der Bundeslade Gottes.", footnotes: ["℘ 2Mo 25,22", "℘ Kap. 14,3"] },
      { number: 5, text: "Und es geschah, als die Lade des Bundes des HERRN ins Lager kam, da jauchzte ganz Israel mit gewaltigem Jauchzen, dass die Erde erdröhnte*.", footnotes: ["℘ 1Kö 1,40"] },
      { number: 6, text: "Und die Philister hörten das laute Jauchzen* und riefen: Was ist das für ein gewaltiges* Jauchzen im Lager der Hebräer*? Und sie erkannten, dass die Lade des HERRN ins Lager gekommen war.", footnotes: ["w. die Stimme des Jauchzens", "w. der Schall dieses großen", "℘ Kap. 29,3"] },
      { number: 7, text: "Da fürchteten sich die Philister und sagten: Gott ist ins Lager gekommen! Und sie sagten: Wehe uns! Denn solches ist bisher noch nie geschehen." },
      { number: 8, text: "Wehe uns! Wer wird uns aus der Hand dieses mächtigen Gottes retten? Das sind die Götter, die die Ägypter mit allerlei Plagen in der Wüste schlugen*.", footnotes: ["℘ Kap. 5,7; 2Mo 9,14; 15,14; Offb 11,6"] },
      { number: 9, text: "Seid tapfer und seid Männer*, ihr Philister, damit ihr nicht den Hebräern dienen müsst, wie sie euch gedient haben*! Seid Männer und kämpft!", footnotes: ["℘ 2Sam 10,12", "℘ Ri 13,1"] },
      { number: 10, text: "Da kämpften die Philister, und Israel wurde geschlagen, so dass sie flohen, jeder in sein Zelt*. Und die Niederlage* war sehr groß, und es fielen von Israel 30 000 Mann zu Fuß*.", footnotes: ["w. in seine Zelte", "w. der Schlag", "℘ 3Mo 26,17; Ps 78,62"] },
      { number: 11, text: "Und die Lade Gottes wurde weggenommen*, und die beiden Söhne Elis, Hofni und Pinhas, kamen um.", footnotes: ["℘ Kap. 2,34; 3,12; Ps 78,64"] },
      { number: 12, text: "Da lief ein Mann von Benjamin vom Schlachtfeld und kam noch an demselben Tag nach Silo. Seine Kleider waren zerrissen, und Erde war auf seinem Kopf*.", footnotes: ["℘ Jos 7,6"] },
      { number: 13, text: "Und als er ankam, siehe, da saß Eli auf einem Stuhl und gab acht nach der Straße hin*. Denn sein Herz bangte um die Lade Gottes. Und als der Mann ankam, um es in der Stadt zu berichten, da schrie die ganze Stadt um Hilfe.", footnotes: ["o. saß Eli auf einem Stuhl an der Seite des Weges, Ausschau haltend"] },
      { number: 14, text: "Als aber Eli das laute Schreien* hörte, sagte er: Was ist das für ein großer Lärm*? Und der Mann kam eilends und berichtete es Eli.", footnotes: ["w. die Stimme des Schreiens", "w. Was ist die Stimme dieses Lärms"] },
      { number: 15, text: "Eli aber war 98 Jahre alt, und seine Augen waren starr geworden, so dass er nicht mehr sehen konnte*.", footnotes: ["℘ Kap. 3,2"] },
      { number: 16, text: "Da sagte der Mann zu Eli: Ich bin der, der von dem Schlachtfeld gekommen ist, und bin heute vom Schlachtfeld geflohen. Und Eli sagte: Wie ist es gegangen*, mein Sohn?", footnotes: ["w. Wie war die Sache"] },
      { number: 17, text: "Und der Bote antwortete und sagte: Israel ist vor den Philistern geflohen. Auch hat es eine große Niederlage im Volk gegeben*, und auch deine beiden Söhne, Hofni und Pinhas, sind tot, und die Lade Gottes ist weggenommen worden*.", footnotes: ["w. und es hat sich eine große Niederlage unter dem Volk ereignet", "℘ Kap. 2,34; 3,12; Ps 78,64"] },
      { number: 18, text: "Und es geschah, als er die Lade Gottes erwähnte, fiel Eli rücklings vom Stuhl an der Tür* und brach das Genick und starb; denn alt war der Mann und schwer. Er hatte Israel vierzig Jahre gerichtet*.", footnotes: ["w. zur Seite der Tür", "℘ Ri 15,20"] },
      { number: 19, text: "Und seine Schwiegertochter, die Frau des Pinhas, war schwanger und sollte bald gebären. Und als sie die Nachricht hörte, dass die Lade Gottes weggenommen worden war und dass ihr Schwiegervater und ihr Mann tot waren, kauerte sie sich nieder und gebar, denn ihre Wehen überfielen sie." },
      { number: 20, text: "Und als sie im Sterben lag*, sagten die Frauen, die um sie her standen: Fürchte dich nicht, denn du hast einen Sohn geboren!* Aber sie antwortete nicht und nahm es nicht mehr zu Herzen.", footnotes: ["w. zur Zeit ihres Sterbens", "℘ 1Mo 35,17"] },
      { number: 21, text: "Und sie nannte den Jungen Ikabod*, um damit auszudrücken: Die Herrlichkeit ist von Israel gewichen*! — weil die Lade Gottes weggenommen war* und wegen ihres Schwiegervaters und ihres Mannes.", footnotes: ["d. h. Nicht-Herrlichkeit\n℘ Kap. 14,3", "℘ Kla 2,1", "℘ Kap. 2,34; 3,12; Ps 78,64"] },
      { number: 22, text: "Darum sagte sie: Die Herrlichkeit ist von Israel gewichen*, denn die Lade Gottes ist weggenommen*!", footnotes: ["℘ Kap. 2,34; 3,12; Ps 78,64", "℘ Kap. 2,34; 3,12; Ps 78,64"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Als die Philister die Lade Gottes weggenommen hatten, brachten sie sie von Eben-Eser* nach Aschdod*.", heading: "Die Bundeslade bei den Philistern", footnotes: ["d. h. Stein der Hilfe\n℘ Kap. 4,1", "℘ Jos 11,22; Jes 20,1"] },
      { number: 2, text: "Und die Philister nahmen die Lade Gottes und brachten sie in das Haus Dagons* und stellten sie neben Dagon auf.", footnotes: ["d. i. eine Fischgottheit mit Kopf und Händen eines Menschen und Rumpf eines Fisches\n℘ Ri 16,23; 1Chr 10,10"] },
      { number: 3, text: "Und als die Aschdoditer am nächsten Tag früh aufstanden und in das Haus Dagons kamen*, siehe, da lag Dagon auf seinem Gesicht auf der Erde vor der Lade des HERRN*. Und sie nahmen Dagon und stellten ihn wieder an seinen Ort*.", footnotes: ["so mit LXX", "℘ Ps 97,7; 1Kö 18,26.29", "℘ Jes 46,7; Ps 115,7"] },
      { number: 4, text: "Und als sie sich am Morgen des nächsten Tages früh aufmachten, siehe, da lag Dagon wieder auf seinem Gesicht auf der Erde vor der Lade des HERRN; und zwar lagen der Kopf Dagons und seine beiden Hände abgehauen auf der Schwelle, nur der Rumpf Dagons war von ihm übrig geblieben*.", footnotes: ["℘ Jer 10,14.15"] },
      { number: 5, text: "Darum treten die Priester Dagons und alle, die in das Haus Dagons gehen, nicht auf die Schwelle Dagons in Aschdod bis auf den heutigen Tag." },
      { number: 6, text: "Und die Hand des HERRN lag schwer auf den Aschdoditern. Und er brachte Verderben über sie, und er schlug sie mit bösen Beulen, Aschdod und sein Gebiet*.", footnotes: ["℘ 5Mo 28,27"] },
      { number: 7, text: "Und als die Leute von Aschdod sahen, dass es so zuging, sagten sie: Die Lade des Gottes Israels soll nicht bei uns bleiben! Denn seine Hand liegt hart auf uns und auf unserem Gott Dagon*.", footnotes: ["℘ Kap. 4,8; 6,20"] },
      { number: 8, text: "Und sie sandten hin und versammelten alle Fürsten der Philister zu sich und sagten: Was sollen wir mit der Lade des Gottes Israels machen*? Und sie antworteten: Lasst die Lade des Gottes Israels nach Gat* bringen! Und sie brachten die Lade des Gottes Israels dorthin.", footnotes: ["℘ Kap. 6,2", "℘ Kap. 17,52; Jos 13,3; 15,11; 1Chr 7,21; Am 6,2"] },
      { number: 9, text: "Und es geschah, nachdem sie sie dorthin gebracht hatten, da kam die Hand des HERRN über die Stadt, und es entstand eine sehr große Bestürzung*. Denn er schlug die Leute in der Stadt, klein und groß, so dass Beulen an ihnen ausbrachen.", footnotes: ["o. Verwirrung; o. Panik"] },
      { number: 10, text: "Da sandten sie die Lade Gottes nach Ekron*. Und es geschah, als die Lade Gottes nach Ekron kam, schrien die Ekroniter um Hilfe und sagten: Sie haben die Lade des Gottes Israels zu mir hergebracht, um mich und mein Volk zu töten!", footnotes: ["℘ Kap. 17,52; Jos 13,3; 15,11; 1Chr 7,21; Am 6,2"] },
      { number: 11, text: "Da sandten sie hin und versammelten alle Fürsten der Philister und sagten: Sendet die Lade des Gottes Israels fort, damit sie an ihren Ort zurückkehrt und mich und mein Volk nicht tötet*! Denn es war ein tödlicher Schrecken über die ganze Stadt gekommen. Die Hand Gottes lag sehr schwer auf ihr*.", footnotes: ["℘ 2Mo 10,7", "w. dort"] },
      { number: 12, text: "Und die Leute, die nicht starben, wurden mit Beulen geschlagen. Und das Geschrei der Stadt stieg zum Himmel empor." },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und die Lade des HERRN war sieben Monate im Gebiet der Philister.", heading: "Rückkehr der Bundeslade" },
      { number: 2, text: "Und die Philister beriefen die Priester und Wahrsager* und sagten: Was sollen wir mit der Lade des HERRN machen*? Lasst uns erkennen, wie wir sie an ihren Ort senden sollen!", footnotes: ["℘ 1Mo 41,8; Jes 2,6; Dan 2,2", "℘ Kap. 5,8; Mt 27,22"] },
      { number: 3, text: "Und sie antworteten: Wenn ihr die Lade des Gottes Israels zurückschicken wollt, so sollt ihr sie nicht leer zurückschicken, sondern ihr müsst ihm auf jeden Fall eine Sühnegabe entrichten*. Dann werdet ihr genesen, und ihr werdet erkennen, warum seine Hand nicht von euch weicht.", footnotes: ["℘ 3Mo 5,16"] },
      { number: 4, text: "Und sie sagten: Was ist die Sühnegabe, die wir ihm entrichten sollen? Und sie antworteten: Nach der Zahl der Fürsten der Philister* fünf goldene Beulen und fünf goldene Springmäuse! Denn es ist ein und dieselbe Plage über euch allen und euren Fürsten gewesen.", footnotes: ["℘ V. 17; Jos 13,3; Ri 14,19"] },
      { number: 5, text: "Und macht Abbilder von euren Beulen und Abbilder von euren Springmäusen, die das Land zugrunde gerichtet haben, und gebt dem Gott Israels die Ehre*! Vielleicht lässt er seine Hand leichter werden über euch und über eurem Gott und über eurem Land*.", footnotes: ["℘ Jos 7,19", "℘ Jon 3,9"] },
      { number: 6, text: "Warum wollt ihr euer Herz verstocken, wie die Ägypter und der Pharao ihr Herz verstockt haben*? Ließen sie sie nicht ziehen, als der HERR* ihnen übel mitgespielt hatte, und sie zogen weg*?", footnotes: ["℘ 2Mo 7,13.14; Hebr 3,7", "w. er", "℘ 2Mo 12,31"] },
      { number: 7, text: "So macht einen neuen Wagen* und nehmt zwei säugende Kühe, auf die noch kein Joch gekommen ist! Und spannt die Kühe an den Wagen und bringt ihre Kälber von ihnen weg nach Hause zurück!", footnotes: ["℘ 2Sam 6,3"] },
      { number: 8, text: "Und nehmt die Lade des HERRN und stellt sie auf den Wagen! Und die goldenen Gegenstände, die ihr ihm als Sühnegabe entrichtet, tut in ein Kästchen an ihre Seite und sendet sie hin und lasst sie gehen!" },
      { number: 9, text: "Und seht zu! Wenn sie den Weg hinauf in ihr Gebiet, nach Bet-Schemesch* zu geht, so hat er uns dieses große Übel getan; wenn aber nicht, so erkennen wir, dass nicht seine Hand uns geschlagen hat: Ein Zufall ist es für uns gewesen*.", footnotes: ["℘ Jos 15,10; 1Kö 4,9; 2Mo 8,15", "℘ Kap. 17,52; Jos 13,3; 15,11; 1Chr 7,21; Am 6,2"] },
      { number: 10, text: "Und die Männer machten es so und nahmen zwei säugende Kühe und spannten sie an einen Wagen, und ihre Kälber sperrten sie zu Hause ein." },
      { number: 11, text: "Und sie stellten die Lade des HERRN auf den Wagen und das Kästchen mit den goldenen Springmäusen und den Abbildern ihrer Beulen." },
      { number: 12, text: "Und die Kühe gingen geradeaus auf dem Weg nach Bet-Schemesch*. Sie gingen immer auf derselben Straße und brüllten immerfort und wichen weder zur Rechten noch zur Linken. Und die Fürsten der Philister gingen hinter ihnen her bis zum Gebiet von Bet-Schemesch.", footnotes: ["℘ Jos 15,10; 1Kö 4,9; 2Mo 8,15"] },
      { number: 13, text: "Und die von Bet-Schemesch ernteten gerade den Weizen* in der Niederung. Und als sie ihre Augen erhoben und die Lade sahen, freuten sie sich, sie zu sehen.", footnotes: ["w. die Weizenernte"] },
      { number: 14, text: "Und der Wagen kam auf das Feld Joschuas, des Bet-Schemeschiters, und stand dort still. Und dort lag ein großer Stein. Und sie spalteten das Holz des Wagens und opferten die Kühe dem HERRN zum Brandopfer*.", footnotes: ["℘ Ri 6,26"] },
      { number: 15, text: "Und die Leviten nahmen die Lade des HERRN herab und das Kästchen, das daneben stand, in dem die goldenen Gegenstände waren, und stellten sie auf den großen Stein. Und die Männer von Bet-Schemesch opferten dem HERRN am selben Tag Brandopfer und schlachteten Schlachtopfer." },
      { number: 16, text: "Und die fünf Fürsten der Philister sahen zu und kehrten an demselben Tag nach Ekron zurück." },
      { number: 17, text: "Dies sind die goldenen Beulen, die die Philister dem HERRN als Sühnegabe entrichteten: Für Aschdod eine, für Gaza eine, für Aschkelon* eine, für Gat* eine und für Ekron eine;", footnotes: ["℘ Ri 14,19; 2Sam 1,20; Am 1,8", "℘ Jos 15,10; 1Kö 4,9; 2Mo 8,15"] },
      { number: 18, text: "und die goldenen Springmäuse nach der Zahl aller Städte der Philister unter den fünf Fürsten, von der befestigten Stadt bis zum offenen Dorf. Und Zeuge ist der große Stein Abel*, auf den sie die Lade des HERRN stellten, der bis zum heutigen Tag im Feld Joschuas, des Bet-Schemeschiters liegt.", footnotes: ["T.; Mas. T.: bis zum offenen Dorf und bis zum großen Abel; andere üs.: Noch ist der große Stein da; andere üs.: Und sie kamen zu dem großen Abel; dann wäre »Abel« mundartlicher Gebrauch für »Stein«"] },
      { number: 19, text: "Und *er schlug die Leute von Bet-Schemesch, weil sie sich die Lade des HERRN angeschaut hatten, und* schlug im Volk siebzig Mann*. Da trauerte das Volk*, *weil der HERR das Volk so schwer geschlagen hatte*.", footnotes: ["LXX ändert in: die Söhne Jechonjas freuten sich nicht mit den Leuten von Bet-Schemesch, dass sie die Lade des HERRN geschaut hatten, und er", "LXX ändert in: die Söhne Jechonjas freuten sich nicht mit den Leuten von Bet-Schemesch, dass sie die Lade des HERRN geschaut hatten, und er", "Im Mas. T. steht außerdem noch: 50 000 Mann; d. i. vielleicht eine aus Versehen in den Text aufgenommene Randbemerkung.\n℘ 4Mo 1,51", "℘ 2Mo 33,4", "w. weil der HERR das Volk geschlagen hatte, einen großen Schlag", "w. weil der HERR das Volk geschlagen hatte, einen großen Schlag\n℘ 2Mo 19,21; 2Sam 6,7"] },
      { number: 20, text: "Und die Leute von Bet-Schemesch sagten: Wer vermag vor dem HERRN, diesem heiligen Gott, zu bestehen*? Und zu wem soll er von uns hinaufziehen*?", footnotes: ["℘ Kap. 5,7; Offb 6,17", "℘ 2Sam 6,9; Mal 3,2"] },
      { number: 21, text: "Und sie sandten Boten zu den Bewohnern von Kirjat-Jearim* und sagten: Die Philister haben die Lade des HERRN zurückgebracht. Kommt herab, holt sie zu euch hinauf*!", footnotes: ["℘ Jos 15,9; Jer 26,20", "℘ 2Sam 6,2"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und die Männer von Kirjat-Jearim kamen und holten die Lade des HERRN hinauf*, und sie brachten sie in das Haus Abinadabs auf dem Hügel*. Und sie heiligten seinen Sohn Eleasar, über der Lade des HERRN zu wachen.", footnotes: ["℘ Ps 132,6", "℘ 2Sam 6,3.4"] },
      { number: 2, text: "Und es geschah, dass von dem Tag an, da die Lade in Kirjat-Jearim blieb*, eine lange Zeit verging*; es wurden zwanzig Jahre. Und das ganze Haus Israel wehklagte hinter dem HERRN her*.", heading: "Israels Buße und Sieg über die Philister — Samuel als Richter", footnotes: ["℘ 1Chr 13,5", "w. und es wurden sehr viele Tage", "o. hielt sich zum HERRN\n℘ Sach 12,10"] },
      { number: 3, text: "Da sprach Samuel zu dem ganzen Haus Israel: Wenn ihr mit eurem ganzen Herzen zu dem HERRN umkehren wollt*, dann tut die fremden Götter und die Astarot* aus eurer Mitte weg*! Und richtet euer Herz auf den HERRN* und dient ihm allein*! So wird er euch aus der Hand der Philister retten*.", footnotes: ["℘ 5Mo 4,29; 1Kö 8,48", "℘ Ri 2,13", "℘ 1Mo 35,2; Jer 4,1", "℘ 2Chr 20,33; Hi 11,13.14", "℘ 5Mo 6,13", "℘ 2Kö 17,39"] },
      { number: 4, text: "Und die Söhne Israel taten die Baalim und die Astarot weg und dienten dem HERRN allein*.", footnotes: ["℘ Ri 10,16; 2Kö 23,15"] },
      { number: 5, text: "Und Samuel sagte: Versammelt ganz Israel in Mizpa*! Und ich will den HERRN für euch bitten.", footnotes: ["℘ Kap. 10,17; Jos 18,26; Hos 5,1"] },
      { number: 6, text: "Und sie versammelten sich in Mizpa*, schöpften Wasser und gossen es aus vor dem HERRN*. Sie fasteten* an demselben Tag und sagten dort: Wir haben gegen den HERRN gesündigt*! Und Samuel richtete die Söhne Israel in Mizpa. —", footnotes: ["℘ Kap. 10,17; Jos 18,26; Hos 5,1", "℘ Hi 3,24; Kla 2,19", "℘ Ri 20,26; 2Chr 20,3", "℘ Kap. 12,10; Ri 10,10.15; 1Kö 8,47; Kla 5,16; Joe 2,12"] },
      { number: 7, text: "Als aber die Philister hörten, dass die Söhne Israel sich in Mizpa versammelt hatten, zogen die Fürsten der Philister gegen Israel hinauf. Und die Söhne Israel hörten es und fürchteten sich vor den Philistern." },
      { number: 8, text: "Und die Söhne Israel sagten zu Samuel: Lass nicht ab, für uns zu dem HERRN, unserm Gott, um Hilfe zu schreien*, dass er uns aus der Hand der Philister rettet!", footnotes: ["℘ Jer 42,2"] },
      { number: 9, text: "Und Samuel nahm ein Milchlamm und opferte es ganz als Brandopfer für den HERRN. Und Samuel schrie zu dem HERRN um Hilfe für Israel, und der HERR erhörte ihn*.", footnotes: ["℘ Ps 99,6"] },
      { number: 10, text: "Es geschah nämlich, während Samuel noch das Brandopfer opferte, rückten die Philister heran zum Kampf gegen Israel. Aber der HERR donnerte mit starkem Donner an demselben Tag über den Philistern und schreckte sie*, und sie wurden vor Israel geschlagen*.", footnotes: ["℘ Ri 4,15; 2Sam 22,14", "℘ Kap. 2,10; 5Mo 28,7; Ps 78,66"] },
      { number: 11, text: "Und die Männer von Israel zogen von Mizpa aus und jagten den Philistern nach und schlugen sie bis unterhalb Bet-Kar*.", footnotes: ["℘ Jos 10,10"] },
      { number: 12, text: "Und Samuel nahm einen Stein* und stellte ihn auf zwischen Mizpa und Schen, und er gab ihm den Namen Eben-Eser* und sagte: Bis hierher hat uns der HERR geholfen.", footnotes: ["℘ 1Mo 28,18", "d. h. Stein der Hilfe\n℘ Kap. 4,1"] },
      { number: 13, text: "So wurden die Philister gedemütigt und kamen nicht mehr in das Gebiet Israels*. Und die Hand des HERRN war gegen die Philister alle Tage Samuels*.", footnotes: ["w. fuhren nicht mehr fort, . . . zu kommen", "℘ Kap. 12,11; Ri 8,28; 2Sam 8,1"] },
      { number: 14, text: "Und die Städte, die die Philister Israel abgenommen hatten, kamen wieder an Israel, von Ekron* bis Gat*. Auch ihr Gebiet rettete Israel aus der Hand der Philister. Und es wurde Friede zwischen Israel und den Amoritern.", footnotes: ["℘ Jos 15,11", "℘ 1Chr 18,1"] },
      { number: 15, text: "Und Samuel richtete Israel alle Tage seines Lebens.*", footnotes: ["℘ Apg 13,20"] },
      { number: 16, text: "Und er zog Jahr für Jahr umher und kam nach Bethel*, Gilgal* und Mizpa* und richtete Israel an all diesen Orten.", footnotes: ["℘ 1Mo 28,19", "℘ Jos 5,9.10", "℘ Kap. 10,17; Jos 18,26; Hos 5,1"] },
      { number: 17, text: "Dann kehrte er nach Rama zurück, denn dort war sein Haus*, und dort richtete er Israel*. Auch baute er dort dem HERRN einen Altar.*", footnotes: ["℘ Kap. 1,19", "℘ Apg 13,20", "℘ Kap. 14,35; 1Mo 12,7.8"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und es geschah, als Samuel alt geworden war, da setzte er seine Söhne als Richter über Israel ein*.", heading: "Israel begehrt einen König", footnotes: ["℘ Kap. 12,2; 5Mo 16,18"] },
      { number: 2, text: "Der Name seines erstgeborenen Sohnes war Joel und der Name seines zweiten Abija*; sie waren Richter in Beerscheba*.", footnotes: ["℘ 1Chr 6,13", "℘ 1Mo 46,1"] },
      { number: 3, text: "Aber seine Söhne wandelten nicht in seinen Wegen und sie suchten ihren Vorteil* und nahmen Bestechungsgeschenke und beugten das Recht*.", footnotes: ["o. waren dem Gewinn ergeben; w. neigten sich hinter dem Vorteil her. — Die hebr. Wendung »sich hinter etwas herneigen« bedeutet »einem Irrweg folgen«; vgl. 2Mo 23,2; Ri 9,3; 1Kö 2,28.", "℘ 2Mo 23,6-8; Jes 1,23; Jer 22,17; Mi 3,11"] },
      { number: 4, text: "Da versammelten sich alle Ältesten von Israel und kamen zu Samuel nach Rama*.", footnotes: ["℘ Kap. 1,19"] },
      { number: 5, text: "Und sie sagten zu ihm: Siehe, du bist alt geworden, und deine Söhne wandeln nicht in deinen Wegen. Nun setze doch einen König über uns, damit er über uns Richter sei, wie es bei allen Nationen ist*!", footnotes: ["℘ V. 20; Kap. 10,19; 5Mo 17,14; Ri 8,22; Apg 13,21"] },
      { number: 6, text: "Und das Wort war übel in den Augen Samuels, dass sie sagten: Gib uns einen König, damit er Richter über uns sei! Und Samuel betete zum HERRN*.", footnotes: ["℘ Kap. 12,23; 15,11"] },
      { number: 7, text: "Der HERR aber sprach zu Samuel: Höre auf die Stimme des Volkes in allem, was sie dir sagen*! Denn nicht dich haben sie verworfen, sondern mich haben sie verworfen*, dass ich nicht König über sie sein soll*.", footnotes: ["℘ V. 22; Kap. 12,1; Hos 13,10.11", "℘ 2Mo 16,8", "℘ Kap. 10,19; 12,12.17"] },
      { number: 8, text: "Entsprechend all den Taten, die sie immer getan haben von dem Tage an, da ich sie aus Ägypten geführt habe bis zum heutigen Tag*, dass sie mich verlassen und andern Göttern gedient haben, so machen sie es auch mit dir.", footnotes: ["℘ Ps 78,8"] },
      { number: 9, text: "Und nun höre auf ihre Stimme! Doch warne sie mit allem Ernst* und mach ihnen das Recht des Königs bekannt, der über sie herrschen wird*!", footnotes: ["w. tritt warnend als Zeuge auf gegen sie", "℘ Kap. 10,25"] },
      { number: 10, text: "Und Samuel sagte dem Volk, das einen König von ihm begehrte, alle Worte des HERRN." },
      { number: 11, text: "Und er sagte: Dies wird das Recht des Königs sein, der über euch regieren wird*: Eure Söhne wird er nehmen, um sie für seinen Wagen und seine Gespanne einzusetzen, damit sie vor seinem Wagen herlaufen*,", footnotes: ["℘ Mt 20,25", "℘ Kap. 14,52; 2Sam 15,1"] },
      { number: 12, text: "und um sie sich zu Obersten über Tausend und zu Obersten über Fünfzig zu bestellen, damit sie seine Äcker pflügen und seine Ernte einbringen und damit sie seine Kriegsgeräte und seine Wagengeräte anfertigen*.", footnotes: ["℘ 1Chr 27,1"] },
      { number: 13, text: "Und eure Töchter wird er zum Salbenmischen, zum Kochen und Backen nehmen." },
      { number: 14, text: "Und eure besten Felder, Weinberge und Olivengärten, die wird er nehmen und sie seinen Knechten geben*.", footnotes: ["℘ Kap. 22,7"] },
      { number: 15, text: "Und von euren Kornfeldern* und euren Weinbergen wird er den Zehnten nehmen und ihn seinen Kämmerern* und Beamten* geben.", footnotes: ["w. Saaten", "w. Eunuchen", "w. Knechten"] },
      { number: 16, text: "Und eure Knechte und eure Mägde und eure besten jungen Männer* und eure Esel wird er nehmen und sie in seinen Dienst stellen.", footnotes: ["LXX ändert in »Rinder«"] },
      { number: 17, text: "Von euren Schafen wird er den Zehnten nehmen, und ihr, ihr müsst seine Knechte sein*.", footnotes: ["℘ Kap. 17,8; 1Kö 12,4"] },
      { number: 18, text: "Wenn ihr an jenem Tage wegen eures Königs um Hilfe schreien werdet, den ihr euch erwählt habt, dann wird euch der HERR an jenem Tag nicht antworten*.", footnotes: ["℘ Hi 27,8.9; Spr 1,25-28; Jes 59,1-3; Hes 8,18; Mi 3,4"] },
      { number: 19, text: "Aber das Volk weigerte sich, auf die Stimme Samuels zu hören*. Und sie sagten: Nein, sondern ein König soll über uns sein,", footnotes: ["℘ 2Kö 21,9; Ps 81,12; Jer 44,16"] },
      { number: 20, text: "damit auch wir sind wie alle Nationen, und dass unser König uns richtet und vor uns her auszieht und unsere Kriege führt*.", footnotes: ["℘ V. 5; Kap. 12,12"] },
      { number: 21, text: "Und Samuel hörte all die Worte des Volkes und sagte sie vor den Ohren des HERRN*.", footnotes: ["℘ 2Kö 19,14"] },
      { number: 22, text: "Und der HERR sprach zu Samuel: Höre auf ihre Stimme* und setze einen König über sie ein! Da sagte Samuel zu den Männern von Israel: Geht hin, jeder in seine Stadt!", footnotes: ["℘ V. 7"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und es war ein Mann von Benjamin, sein Name war Kisch*, ein Sohn Abiels*, des Sohnes Zerors, des Sohnes Bechorats, des Sohnes des Afiach, des Sohnes eines Benjaminiters, ein angesehener* Mann.", heading: "Saul wird zum König gesalbt", footnotes: ["℘ Est 2,5", "℘ Kap. 14,51", "o. vermögender"] },
      { number: 2, text: "Und er hatte einen Sohn, sein Name war Saul*, jung und stattlich, und niemand von den Söhnen Israel war schöner als er*. Er war einen Kopf größer* als alles Volk*.", footnotes: ["℘ 1Chr 8,33", "℘ 2Sam 14,25", "w. von seiner Schulter an aufwärts war er größer", "℘ Kap. 10,21.23"] },
      { number: 3, text: "Und die Eselinnen des Kisch, des Vaters Sauls, waren verloren gegangen. Und Kisch sagte zu seinem Sohn Saul: Nimm doch einen von den Knechten mit dir und mach dich auf, geh hin und suche die Eselinnen!" },
      { number: 4, text: "Und er zog durch* das Gebirge Ephraim* und zog durch das Land Schalischa, und sie fanden sie nicht. Und sie durchzogen das Land Schaalim*, aber sie waren nicht da. Und er zog durch das Land Benjamin, und sie fanden sie nicht.", footnotes: ["LXX und die lat. Üs.: sie durchzogen", "℘ Kap. 1,1", "℘ 2Kö 4,42"] },
      { number: 5, text: "Als sie aber in das Land Zuf kamen, sagte Saul zu seinem Knecht, der bei ihm war: Komm, lass uns wieder umkehren, damit nicht etwa mein Vater von den Eselinnen ablässt und sich um uns Sorgen macht!" },
      { number: 6, text: "Der aber sagte zu ihm: Siehe doch, ein Mann Gottes* ist in dieser Stadt. Der Mann ist sehr angesehen. Alles, was er sagt, trifft sicher ein*. Lass uns dahin gehen*, vielleicht gibt er uns Auskunft über unsern Weg, den wir gehen sollten!", footnotes: ["℘ Kap. 2,27", "℘ Kap. 3,19.20", "℘ Ps 25,12"] },
      { number: 7, text: "Saul aber sagte zu seinem Knecht: Siehe, wenn wir hingehen, was wollen wir dem Mann bringen? Denn das Brot in unsern Beuteln ist verbraucht, und wir haben kein Geschenk, um es dem Mann Gottes zu bringen*. Was haben wir?", footnotes: ["℘ 1Kö 13,7; 14,3; 2Kö 8,8"] },
      { number: 8, text: "Und der Knecht antwortete Saul noch einmal und sagte: Siehe, ich habe noch einen silbernen Viertel-Schekel bei mir*; den will ich dem Mann Gottes geben, damit er uns über unsern Weg Auskunft gibt.", footnotes: ["w. es findet sich in meiner Hand ein Viertel-Schekel Silber"] },
      { number: 9, text: "Vorzeiten sagte man in Israel, wenn man ging, Gott zu befragen*: Kommt und lasst uns zum Seher gehen! Denn den man heute Prophet nennt, nannte man früher Seher*.", footnotes: ["℘ 1Mo 25,22; Ri 18,5", "℘ 2Sam 24,11; 2Kö 17,13; 1Chr 9,22; Am 7,12"] },
      { number: 10, text: "Da sagte Saul zu seinem Knecht: Dein Wort ist gut. Komm, lass uns gehen! Und sie gingen in die Stadt, wo der Mann Gottes war*.", footnotes: ["℘ Kap. 10,14"] },
      { number: 11, text: "Als sie eben die Anhöhe* zu der Stadt hinaufstiegen, trafen sie Mädchen, die herauskamen, um Wasser zu schöpfen*. Und sie sagten zu ihnen: Ist der Seher hier?", footnotes: ["w. den Aufgang", "℘ 1Mo 24,11"] },
      { number: 12, text: "Sie antworteten ihnen und sagten: Ja, siehe, er ist schon vor dir da. Eile jetzt, denn er ist heute in die Stadt gekommen, weil das Volk heute ein Opferfest* auf der Höhe begeht!", footnotes: ["w. Schlachtopfer\n℘ Kap. 16,2.5; 20,6; 1Mo 31,54; 1Kö 3,2.3"] },
      { number: 13, text: "Sowie ihr in die Stadt kommt, werdet ihr ihn finden, bevor er zur Höhe hinaufgeht, um zu essen. Denn das Volk wird nicht essen, bis er gekommen ist; denn er segnet das Schlachtopfer, danach essen die Geladenen*. So geht hinauf, denn gerade heute werdet ihr ihn finden!", footnotes: ["℘ Lk 9,16"] },
      { number: 14, text: "Da gingen sie zur Stadt hinauf. Als sie in die Stadt eintraten, siehe, da kam Samuel heraus, ihnen entgegen, um zur Höhe hinaufzugehen." },
      { number: 15, text: "Der HERR aber hatte dem Samuel das Ohr geöffnet*, einen Tag bevor Saul kam, und gesagt:", footnotes: ["℘ Kap. 3,21; Am 3,7; Apg 9,10.11"] },
      { number: 16, text: "Morgen um diese Zeit werde ich einen Mann aus dem Land Benjamin zu dir senden*, den sollst du zum Fürsten über mein Volk Israel salben*! Der wird mein Volk aus der Hand der Philister retten*. Denn ich habe die Not meines Volkes* angesehen, und sein Geschrei ist vor mich gekommen*.", footnotes: ["℘ Spr 16,9", "℘ Kap. 10,1", "℘ Kap. 14,20-23", "so mit LXX; Mas. T.: mein Volk", "℘ 2Mo 2,23-25; Ps 106,44"] },
      { number: 17, text: "Als nun Samuel Saul sah, teilte ihm der HERR mit: Siehe, da ist der Mann, von dem ich dir gesagt habe, dass er über mein Volk herrschen soll." },
      { number: 18, text: "Da trat Saul im Tor auf Samuel zu und sagte: Zeig mir doch, wo hier das Haus des Sehers ist." },
      { number: 19, text: "Samuel antwortete Saul und sagte: Ich bin der Seher. Geh vor mir auf die Höhe hinauf, denn ihr sollt heute mit mir essen, und morgen früh werde ich dich ziehen lassen! Und alles, was du auf dem Herzen hast, werde ich dir kundtun." },
      { number: 20, text: "Und was die Eselinnen betrifft, die dir heute vor drei Tagen verloren gegangen sind, so brauchst du dir um sie keine Sorgen zu machen*, denn sie sind gefunden*. Und wem gehört alles Kostbare Israels? Nicht dir und dem ganzen Haus deines Vaters?*", footnotes: ["w. richte dein Herz nicht auf sie", "℘ Kap. 10,16", "o. auf wen richtet sich alles Begehren Israels? Nicht auf dich und das ganze Haus . . .? — Die Sätze sind im Hebr. wahrscheinlich absichtlich so doppelsinnig formuliert."] },
      { number: 21, text: "Da antwortete Saul und sprach: Bin ich nicht ein Benjaminiter und aus einem der kleinsten Stämme Israels, und ist meine Sippe nicht die geringste unter allen Sippen des Stammes Benjamin*? Warum sprichst du solche Worte zu mir?", footnotes: ["℘ Kap. 18,18.23; Ri 6,15; Ps 68,28"] },
      { number: 22, text: "Und Samuel nahm Saul und seinen Knecht und führte sie in die Halle. Und er gab ihnen einen Platz obenan unter den Geladenen; und das waren etwa dreißig Mann." },
      { number: 23, text: "Und Samuel sagte zu dem Koch: Gib den Anteil her, den ich dir gegeben habe und von dem ich dir gesagt habe: Lege ihn bei dir zurück!" },
      { number: 24, text: "Da trug der Koch die Keule auf und was daran war* und legte es Saul vor. Und er sagte: Siehe, hier ist das Übriggebliebene! Leg dir vor und iss! Denn für diese Stunde* ist es für dich aufbewahrt worden, als ich sagte: Ich habe das Volk geladen. So aß Saul mit Samuel an diesem Tag.", footnotes: ["aram. Üs.: den Fettschwanz", "w. für diese vereinbarte Begegnung"] },
      { number: 25, text: "Und sie gingen von der Höhe in die Stadt hinab; *und er redete mit Saul auf dem Dach.", footnotes: ["LXX ändert in: Und sie machten ein Lager für Saul auf dem Dach, 26 und er legte sich schlafen"] },
      { number: 26, text: "Und sie standen früh auf*. Und es geschah, als die Morgenröte aufging, rief Samuel dem Saul auf dem Dach zu: Steh auf, dass ich dich geleite! Und Saul stand auf, und die beiden, er und Samuel, gingen auf die Gasse hinaus.", footnotes: ["LXX ändert in: Und sie machten ein Lager für Saul auf dem Dach, 26 und er legte sich schlafen"] },
      { number: 27, text: "Als sie an das Ende der Stadt hinabkamen, sagte Samuel zu Saul: Sag dem Knecht, dass er uns vorausgehe! Und er ging voraus. Du aber steh jetzt still! Ich will dich das Wort Gottes hören lassen*.", footnotes: ["℘ Kap. 15,16; 2Kö 20,16"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und Samuel nahm den Krug mit Öl und goss es auf sein Haupt*, und er küsste ihn und sagte: So hat der HERR dich nun zum Fürsten über sein Erbteil gesalbt*!", footnotes: ["℘ Kap. 9,16; 16,13; 1Kö 1,34.39; 2Kö 9,3.6", "℘ Kap. 15,1.17; 5Mo 32,9"] },
      { number: 2, text: "Wenn du heute von mir weggehst, wirst du zwei Männer treffen beim Grab Rahels*, an der Grenze von Benjamin, bei Zelzach; die werden zu dir sagen: Die Eselinnen sind gefunden, die du zu suchen ausgezogen bist. Und siehe, dein Vater hat die Sache mit den Eselinnen aufgegeben. Er macht sich um euch Sorgen und sagt: Was soll ich wegen meines Sohnes tun?", heading: "Zeichen des göttlichen Auftrags für Saul", footnotes: ["℘ 1Mo 35,19.20"] },
      { number: 3, text: "Und wenn du von dort weitergehst und du zur Terebinthe Tabor kommst, werden dich dort drei Männer treffen, die zu Gott nach Bethel hinaufgehen*. Einer trägt drei Böckchen und einer drei Brote*, und einer trägt einen Schlauch mit Wein.", footnotes: ["℘ Ri 20,18", "w. drei Fladen Brot"] },
      { number: 4, text: "Und sie werden dich nach deinem Wohlergehen fragen und dir zwei Brote geben, und du sollst sie von ihrer Hand annehmen." },
      { number: 5, text: "Danach wirst du zu dem Hügel Gottes kommen, wo Wachtposten der Philister sind*. Und wenn du dort in die Stadt kommst, wirst du einer Schar von Propheten* begegnen, die von der Höhe herabkommen, und vor ihnen her Harfe und Tamburin und Flöte und Zither, und sie werden weissagen*.", footnotes: ["℘ Kap. 13,3", "℘ Kap. 19,20; 2Kö 2,3.5", "d. i. hier: prophetische Ergriffenheit o. prophetische Begeisterung\n℘ 1Kö 18,29; 2Kö 3,15; 1Chr 25,3"] },
      { number: 6, text: "Und der Geist des HERRN wird über dich kommen*, und du wirst mit ihnen weissagen* und wirst in einen anderen Menschen umgewandelt werden.", footnotes: ["℘ Kap. 11,6; 16,13; 19,20-23; Ri 3,10; 15,14", "d. i. hier: prophetische Ergriffenheit o. prophetische Begeisterung"] },
      { number: 7, text: "Und es soll geschehen, wenn bei dir diese Zeichen eintreffen, so tu, was deine Hand finden wird*! Denn Gott ist mit dir*.", footnotes: ["d. h. wozu du in der Lage bist; vgl. Kap. 25,8\n℘ Pred 9,10", "℘ Kap. 3,19; 20,13; Jos 1,5.9; 2Sam 7,3"] },
      { number: 8, text: "Und geh vor mir nach Gilgal* hinab! Und siehe, ich werde zu dir hinabkommen, um Brandopfer zu opfern und Heilsopfer* zu schlachten. Sieben Tage sollst du warten, bis ich zu dir komme* und dir zu erkennen gebe, was du tun sollst*.", footnotes: ["℘ Kap. 11,14.15; 15,33; Jos 4,19; 2Sam 19,16", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 13,4.8", "℘ Apg 22,10"] },
      { number: 9, text: "Und es geschah, als er sich umwandte*, um von Samuel wegzugehen, da gab ihm Gott ein anderes Herz*. Und alle diese Zeichen trafen an demselben Tag ein.", footnotes: ["w. seinen Rücken wandte", "w. da wandelte Gott ihm das Herz in ein anderes um\n℘ Hes 36,26"] },
      { number: 10, text: "Als sie dorthin an den Hügel kamen, siehe, da kam ihm eine Schar von Propheten entgegen. Und der Geist Gottes kam über ihn*, dass er in ihrer Mitte weissagte*.", footnotes: ["℘ Kap. 11,6; 16,13; 19,20-23; Ri 3,10; 15,14", "d. i. hier: prophetische Ergriffenheit o. prophetische Begeisterung"] },
      { number: 11, text: "Und es geschah, als alle, die ihn von früher her kannten, sahen, und siehe, er weissagte* mit den Propheten, da sagten die Leute zueinander: Was ist denn mit dem Sohn des Kisch geschehen? Ist Saul auch unter den Propheten*?*", footnotes: ["d. i. hier: prophetische Ergriffenheit o. prophetische Begeisterung", "o. unter den prophetisch Ergriffenen", "℘ Kap. 19,24"] },
      { number: 12, text: "Und einer von dort antwortete und sagte: Wer ist denn ihr Vater? Daher ist es zum Sprichwort geworden: Ist Saul auch unter den Propheten*?", footnotes: ["o. unter den prophetisch Ergriffenen"] },
      { number: 13, text: "Und als er aufgehört hatte zu weissagen*, kam er auf die Höhe.", footnotes: ["d. i. hier: prophetische Ergriffenheit o. prophetische Begeisterung"] },
      { number: 14, text: "Und Sauls Onkel sagte zu ihm und zu seinem Knecht: Wo seid ihr hingegangen? Er antwortete: Die Eselinnen zu suchen; und als wir sahen, dass sie nirgends waren, gingen wir zu Samuel*.", footnotes: ["℘ Kap. 9,3.10"] },
      { number: 15, text: "Da sagte der Onkel Sauls: Teile mir doch mit, was Samuel zu euch gesagt hat!" },
      { number: 16, text: "Saul antwortete seinem Onkel: Er teilte uns als ganz gewiss mit, dass die Eselinnen gefunden seien*. Aber die Sache mit dem Königtum, wovon Samuel geredet hatte, teilte er ihm nicht mit*.", footnotes: ["℘ Kap. 9,20", "℘ Ri 14,6.9; Spr 12,23; Pred 3,7"] },
      { number: 17, text: "Und Samuel rief das Volk zusammen zum HERRN nach Mizpa*.", heading: "Sauls Wahl zum König", footnotes: ["℘ Kap. 7,5"] },
      { number: 18, text: "Und er sprach zu den Söhnen Israel: So spricht der HERR, der Gott Israels: Ich habe Israel aus Ägypten heraufgeführt* und euch aus der Hand Ägyptens gerettet und aus der Hand aller Königreiche, die euch bedrängten*.", footnotes: ["℘ 2Mo 29,46", "℘ Ri 6,8.9"] },
      { number: 19, text: "Ihr aber habt heute euren Gott verworfen*, der euch aus allen euren Nöten und euren Bedrängnissen gerettet hat, und habt zu ihm gesagt: Einen König* sollst du über uns setzen!* Nun denn, stellt euch auf vor dem HERRN nach euren Stämmen und nach euren Tausendschaften*!", footnotes: ["℘ Kap. 8,7", "viele hebr. Handschr., LXX und die lat. Üs.: Nein, sondern einen König (wie Kap. 8,19)", "℘ Kap. 8,5.19", "℘ Kap. 3,21; Jos 7,14; 24,1"] },
      { number: 20, text: "Und Samuel ließ alle Stämme Israels herantreten. Da wurde der Stamm Benjamin durchs Los getroffen*.", footnotes: ["℘ 5Mo 33,12"] },
      { number: 21, text: "Und er ließ den Stamm Benjamin nach seinen Sippen herantreten. Da wurde die Sippe Matri getroffen;* da wurde Saul, der Sohn des Kisch, getroffen. Und sie suchten ihn, aber er wurde nicht gefunden*.", footnotes: ["LXX fügt hinzu: Und er ließ die Sippe Matri herantreten, Mann für Mann.", "℘ Apg 13,21"] },
      { number: 22, text: "Und sie befragten noch einmal den HERRN*: Ist der Mann schon hierhergekommen? Aber der HERR antwortete: Siehe, er hat sich bei dem Tross versteckt*.", footnotes: ["℘ Kap. 23,2.4.9; 30,7.8; Ri 1,1; 2Sam 2,1; 21,1", "℘ Kap. 15,17"] },
      { number: 23, text: "Da liefen sie hin und holten ihn von dort. Und als er sich mitten unter das Volk stellte, da war er einen Kopf größer* als alles Volk*.", footnotes: ["w. da war er größer als alles Volk, von seiner Schulter an aufwärts", "℘ Kap. 9,1.2"] },
      { number: 24, text: "Und Samuel sagte zu dem ganzen Volk: Habt ihr gesehen, wen der HERR erwählt hat*? Denn keiner ist ihm gleich* im ganzen Volk. Da jauchzte das ganze Volk, und sie riefen: Es lebe der König!*", footnotes: ["℘ 5Mo 17,15; 2Sam 21,6", "w. wie er", "℘ Kap. 11,15; 12,1; 1Kö 1,25.39"] },
      { number: 25, text: "Und Samuel sagte dem Volk das Recht des Königtums* und schrieb es in ein Buch und legte es vor den HERRN nieder. Und Samuel entließ das ganze Volk, jeden in sein Haus.*", footnotes: ["℘ Kap. 8,9; 5Mo 17,14-20", "℘ Jos 22,6"] },
      { number: 26, text: "Auch Saul ging in sein Haus nach Gibea*. Und mit ihm zogen die vom Heer, deren Herz Gott gerührt hatte.", footnotes: ["℘ Kap. 11,4; 13,2; 15,34; Jos 18,28; 2Sam 21,6"] },
      { number: 27, text: "Aber einige ruchlose Leute* sagten: Wie soll der uns retten*? Und sie verachteten ihn und brachten ihm kein Geschenk*. Aber er tat, als hörte er es nicht*.", footnotes: ["w. Söhne der Bosheit", "℘ Mt 13,55-57", "℘ 1Kö 5,1; 2Chr 17,5", "w. war wie taub\n℘ Kap. 11,12; Pred 7,21"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und Nahasch, der Ammoniter*, zog herauf* und belagerte Jabesch in Gilead*. Und alle Männer von Jabesch sagten zu Nahasch: Schließe einen Bund mit uns, so wollen wir dir dienstbar sein!", heading: "Sauls Sieg über die Ammoniter", footnotes: ["℘ Kap. 12,12; 2Sam 10,1.2", "℘ Ri 11,4", "℘ Kap. 31,11; Ri 21,8; 2Sam 2,5.6; 1Chr 10,12"] },
      { number: 2, text: "Aber Nahasch, der Ammoniter, antwortete ihnen: Unter der Bedingung will ich einen Bund mit euch schließen, dass ich euch allen das rechte Auge aussteche und damit Schmach über ganz Israel bringe." },
      { number: 3, text: "Da sagten die Ältesten von Jabesch zu ihm: Lass uns sieben Tage Zeit, damit wir Boten in das ganze Gebiet Israels senden! Und wenn dann niemand da ist, der uns rettet, so wollen wir zu dir hinausgehen." },
      { number: 4, text: "Da kamen die Boten nach Gibea-Saul* und sagten diese Worte vor den Ohren des Volkes. Und das ganze Volk erhob seine Stimme und weinte*.", footnotes: ["℘ Kap. 10,26", "℘ Kap. 30,4; Ri 2,4"] },
      { number: 5, text: "Und siehe, da kam Saul vom Feld hinter den Rindern her. Und Saul fragte: Was ist mit dem Volk, dass sie weinen? Und sie berichteten ihm die Worte der Männer von Jabesch." },
      { number: 6, text: "Da geriet der Geist Gottes über Saul*, als er diese Worte hörte, und sein Zorn entbrannte sehr.", footnotes: ["℘ Kap. 10,6.10"] },
      { number: 7, text: "Und er nahm ein Gespann Rinder und zerstückelte sie und sandte davon durch Boten in das ganze Gebiet Israels* und ließ sagen: Wer nicht hinter Saul und hinter Samuel auszieht, dessen Rindern wird es ebenso ergehen*! Da fiel der Schrecken des HERRN auf das Volk*, und sie zogen aus wie ein Mann*.", footnotes: ["℘ Ri 19,29", "℘ Ri 21,5", "℘ 2Chr 19,7; Jes 8,13", "℘ Ri 20,1"] },
      { number: 8, text: "Und er musterte sie bei Besek; und die von den Söhnen Israel waren 300 000 und die Männer von Juda 30 000." },
      { number: 9, text: "Und er sagte* zu den Boten, die gekommen waren: So sollt ihr zu den Männern von Jabesch in Gilead* sagen: Morgen, wenn die Sonne beginnt, heiß zu scheinen*, soll euch Hilfe* zuteil werden. Und die Boten kamen zurück und berichteten das den Männern von Jabesch, und sie freuten sich.", footnotes: ["so mit LXX; Mas. T.: sie sagten", "℘ Kap. 31,11; Ri 21,8; 2Sam 2,5.6; 1Chr 10,12", "w. beim Heißwerden der Sonne", "o. Heil"] },
      { number: 10, text: "Und die Männer von Jabesch sagten: Morgen wollen wir zu euch hinausgehen, dann könnt ihr uns alles tun, was gut ist in euren Augen*.", footnotes: ["℘ 1Kö 20,4"] },
      { number: 11, text: "Und es geschah am nächsten Tag, da stellte Saul das Volk in drei Heerhaufen auf*. Und sie kamen mitten in das Lager um die Zeit der Morgenwache und schlugen Ammon bis der Tag heiß wurde. Und was übrig blieb, wurde zerstreut, so dass von ihnen nicht zwei beieinander blieben*.", footnotes: ["℘ Ri 7,16", "℘ Kap. 14,47"] },
      { number: 12, text: "Da sprach das Volk zu Samuel: Wer ist es, der gesagt hat: Sollte Saul König über uns sein?* Gebt die Männer her, dass wir sie töten!", footnotes: ["℘ Kap. 10,27"] },
      { number: 13, text: "Aber Saul sagte: Niemand soll an diesem Tag getötet werden*, denn heute hat der HERR Rettung gegeben in Israel*!", footnotes: ["℘ 2Sam 19,23", "℘ Kap. 14,45; 19,5"] },
      { number: 14, text: "Und Samuel sagte zum Volk: Kommt und lasst uns nach Gilgal* gehen und dort das Königtum erneuern!", footnotes: ["℘ Kap. 10,8"] },
      { number: 15, text: "Und das ganze Volk zog nach Gilgal, und sie machten dort Saul zum König, vor dem HERRN in Gilgal. Und sie schlachteten dort Heilsopfer* vor dem HERRN. Und Saul und alle Männer von Israel freuten sich dort sehr*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ Kap. 10,24"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und Samuel sprach zu ganz Israel: Siehe, ich habe auf eure Stimme gehört in allem, was ihr zu mir gesagt habt,* und habe einen König über euch gesetzt.*", heading: "Samuels Abschiedspredigt", footnotes: ["℘ Kap. 8,7.19-22", "℘ Kap. 10,24; Hos 13,11"] },
      { number: 2, text: "Und nun siehe, der König zieht vor euch her. Ich aber bin alt und grau geworden*, und meine Söhne*, siehe, sie sind bei euch. Und ich bin vor euch hergegangen* von meiner Jugend an bis auf diesen Tag.", footnotes: ["℘ Jos 23,2", "℘ Kap. 8,1", "w. gewandelt"] },
      { number: 3, text: "Hier bin ich, zeugt gegen mich vor dem HERRN und vor seinem Gesalbten*! Wessen Rind habe ich genommen, oder wessen Esel habe ich genommen*? Wen habe ich übervorteilt? Wem habe ich Gewalt angetan? Aus wessen Hand habe ich Bestechungsgeld* genommen, um damit meine Augen zu verhüllen*? So will ich es euch zurückgeben*.", footnotes: ["℘ Kap. 24,7; 26,9", "℘ 4Mo 16,15; Ps 15,5; Apg 20,33", "o. Schweigegeld", "℘ 5Mo 16,19", "℘ 3Mo 5,24"] },
      { number: 4, text: "Sie aber antworteten: Du hast uns nicht übervorteilt und uns keine Gewalt angetan und hast von niemandem irgendetwas angenommen*.", footnotes: ["w. hast nicht genommen aus der Hand eines Menschen\n℘ 1Thes 2,5.10"] },
      { number: 5, text: "Und er sagte zu ihnen: Der HERR ist Zeuge euch gegenüber*, und ebenso ist sein Gesalbter heute Zeuge, dass ihr nichts in meiner Hand gefunden habt! Und sie sagten*: Er ist Zeuge!", footnotes: ["℘ 1Mo 31,50; Hi 16,19; 2Kor 1,23", "so mit LXX; Mas. T.: er sagte"] },
      { number: 6, text: "Und Samuel sprach zu dem Volk: Der HERR ist es, der Mose und Aaron eingesetzt und eure Väter aus dem Land Ägypten heraufgeführt hat!*", footnotes: ["℘ 2Mo 6,26.27"] },
      { number: 7, text: "Und nun tretet her, dass ich vor dem HERRN mit euch vor Gericht trete über alle Wohltaten* des HERRN, die er an euch und an euren Vätern erwiesen hat*!", footnotes: ["w. alle Gerechtigkeiten; d. h. das treue Verhalten Gottes, das dem Volk Gemeinschaft mit Gott ermöglicht und sie aufrechterhält", "℘ Mi 6,5"] },
      { number: 8, text: "Als Jakob nach Ägypten gekommen war, schrien eure Väter zu dem HERRN um Hilfe*. Und der HERR sandte Mose und Aaron, und sie führten eure Väter aus Ägypten heraus* und ließen sie in dieser Gegend* wohnen*.", footnotes: ["℘ 2Mo 2,23", "℘ 2Mo 6,26.27", "w. an diesem Ort", "℘ Jos 21,43"] },
      { number: 9, text: "Aber sie vergaßen den HERRN, ihren Gott*. Und er verkaufte sie in die Hand Siseras, des Heerobersten von Hazor*, und in die Hand der Philister* und in die Hand des Königs von Moab*, und sie kämpften gegen sie.", footnotes: ["℘ Ri 3,7", "℘ Ri 4,2", "℘ Ri 10,7", "℘ Ri 3,12"] },
      { number: 10, text: "Da schrien sie um Hilfe zu dem HERRN und sagten: Wir haben gesündigt*, dass wir den HERRN verlassen und den Baalim und Astarot gedient haben*. Nun aber rette uns aus der Hand unserer Feinde, dann wollen wir dir dienen*!", footnotes: ["℘ Kap. 7,6", "℘ Ri 2,11-13", "℘ Ri 10,15.16"] },
      { number: 11, text: "Da sandte der HERR Jerubbaal*, Bedan*, Jeftah* und Samuel* und rettete euch aus der Hand eurer Feinde ringsum*, so dass ihr sicher wohnen konntet.", footnotes: ["℘ Ri 6,14.32", "LXX und die syr. Üs.: Barak\n℘ Ri 4,6", "℘ Ri 11,1", "℘ Kap. 7,13", "℘ 2Kö 13,5"] },
      { number: 12, text: "Als ihr aber saht, dass Nahasch, der König der Söhne Ammon, gegen euch zog*, sagtet ihr zu mir: Nein, sondern ein König soll über uns herrschen!* — obwohl doch der HERR, euer Gott, euer König ist*.", footnotes: ["℘ Kap. 11,1", "℘ Kap. 8,19.20", "℘ Ri 8,23; Jes 33,22"] },
      { number: 13, text: "Und nun siehe, da ist der König, den ihr erwählt und den ihr erbeten habt; denn siehe, der HERR hat einen König über euch gesetzt." },
      { number: 14, text: "Wenn ihr den HERRN fürchtet und ihm dient, auf seine Stimme hört und dem Mund des HERRN nicht widerspenstig seid und wenn ihr und der König, der über euch regiert, dem HERRN, eurem Gott, nachfolgt*, so wird der Herr mit euch sein!", footnotes: ["℘ 5Mo 13,5; Ps 105,28"] },
      { number: 15, text: "Wenn ihr aber nicht auf die Stimme des HERRN hört und dem Mund des HERRN widerspenstig seid, so wird die Hand des HERRN gegen euch sein* wie gegen eure Väter*.", footnotes: ["℘ 3Mo 26,17", "℘ 5Mo 31,27; Ri 2,15; 2Chr 15,2"] },
      { number: 16, text: "So tretet jetzt herzu und seht, was der HERR Großes* vor euren Augen tun wird!", footnotes: ["w. seht diese große Sache, die der HERR"] },
      { number: 17, text: "Ist jetzt nicht die Weizenernte? Ich will den HERRN anrufen, dass er Donner* und Regen sendet*. Und ihr sollt erkennen und sehen, dass das Böse, das ihr darin begangen* habt, euch einen König zu erbitten, groß ist in den Augen des HERRN*.", footnotes: ["℘ Kap. 2,10", "℘ Spr 26,1", "w. hinzugefügt", "℘ Kap. 8,6.7; 2Mo 32,30"] },
      { number: 18, text: "Und Samuel rief zu dem HERRN*, und der HERR sandte an jenem Tag Donner und Regen. Da fürchtete das ganze Volk den HERRN und Samuel sehr*.", footnotes: ["℘ Jos 10,12; 1Kö 18,42", "℘ 2Mo 14,31; Jos 4,14"] },
      { number: 19, text: "Und das ganze Volk sagte zu Samuel: Bitte den HERRN, deinen Gott, für deine Knechte, dass wir nicht sterben!* Denn zu all unsern Sünden haben wir das Böse begangen*, einen König für uns zu erbitten*.", footnotes: ["℘ 4Mo 21,7; Jer 37,3", "w. hinzugefügt", "℘ Kap. 8,6.7; 2Mo 32,30"] },
      { number: 20, text: "Samuel aber sagte zum Volk: Fürchtet euch nicht!* Ihr habt zwar all dieses Böse begangen, doch hört nicht auf, dem HERRN nachzufolgen*, und dient dem HERRN mit eurem ganzen Herzen*!", footnotes: ["℘ Hag 2,5", "w. weicht nicht ab von der Nachfolge dem HERRN nach", "℘ 5Mo 10,12.13; 1Chr 28,9"] },
      { number: 21, text: "Und weicht nicht ab* und folgt nicht den nichtigen Götzen* nach*, die nichts nützen und nicht retten können, weil sie nichtig sind*!", footnotes: ["℘ 5Mo 11,16", "o. nichts; o. Öde; d. i. eine Bezeichnung für Götzen, besonders bei Jesaja. Dasselbe Wort wird in 1Mo 1,2 von der Erde gebraucht vor dem ordnenden Schaffen Gottes: wüst", "℘ 5Mo 30,17; 2Kö 17,15", "℘ Jes 41,29; Jer 2,5.8; Jon 2,9; Apg 14,15"] },
      { number: 22, text: "Denn der HERR wird sein Volk um seines großen Namens willen* nicht verlassen*. Denn es hat dem HERRN gefallen, euch zu seinem Volk zu machen*.", footnotes: ["℘ Ps 106,8; Hes 20,9.14", "℘ 5Mo 31,6; 2Kö 14,27; Neh 9,17.31; Ps 94,14; Jes 49,15; Jer 14,9; Röm 11,1.2", "℘ 5Mo 7,6-8; Jes 43,7; 63,8"] },
      { number: 23, text: "Auch was mich betrifft — fern sei es von mir*, dass ich mich an dem HERRN versündigen und aufhören sollte, für euch zu bitten*; sondern ich will euch den guten und richtigen Weg lehren*.", footnotes: ["w. etwas Entweihtes sei es mir", "℘ Kap. 8,6; Ps 122,6-8; Jer 15,1; 42,4", "℘ Ps 34,12; Jes 30,21"] },
      { number: 24, text: "Fürchtet nur den HERRN und dient ihm in Wahrheit* mit eurem ganzen Herzen! Denn seht, wie große Dinge er an euch getan hat!*", footnotes: ["o. in Treue\n℘ Jos 24,14; 2Kö 17,39", "℘ 5Mo 29,1.2"] },
      { number: 25, text: "Wenn ihr aber dennoch böse handelt, so werdet ihr und euer König weggerafft werden.*", footnotes: ["℘ 5Mo 8,19; 28,36.64; Jos 23,16; 24,20; Jes 1,20"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Saul war . . . Jahre* alt, als er König wurde; und er regierte zwei Jahre über Israel.*", heading: "Krieg gegen die Philister — Sauls voreiliges Opfern — Waffenmangel in Israel", footnotes: ["Eine Altersangabe fehlt hier im Mas. T.; »30 Jahre« (so einige griech. Handschr.) ist eine Vermutung.", "℘ Apg 13,21"] },
      { number: 2, text: "Und Saul erwählte sich aus Israel dreitausend Mann*: Zweitausend waren bei Saul zu Michmas* und auf dem Gebirge von Bethel, und tausend waren bei Jonatan in Gibea in Benjamin*. Den Rest des Volkes aber entließ er, einen jeden in sein Zelt*.", footnotes: ["℘ Kap. 24,3", "℘ Kap. 14,5.31; Esr 2,27; Neh 11,31; Jes 10,28", "℘ Kap. 10,26; 2Sam 23,29", "w. in ihre Zelte\n℘ Jos 22,6"] },
      { number: 3, text: "Und Jonatan schlug den Wachtposten der Philister, der in Gibea* war, und die Philister hörten es*. Und Saul ließ im ganzen Land ins Horn stoßen* und sprach: Die Hebräer sollen es hören!", footnotes: ["so mit LXX; hebr. Geba\n℘ Kap. 10,5; Jos 18,24", "LXX: hörten, dass die Hebräer abgefallen seien", "℘ Ri 3,27"] },
      { number: 4, text: "Und ganz Israel hörte es und sagte: Saul hat den Wachtposten der Philister geschlagen, und auch Israel hat sich bei den Philistern stinkend gemacht*. Da wurde das Volk hinter Saul her nach Gilgal zusammengerufen*.", footnotes: ["℘ Kap. 27,12; 1Mo 34,30; 2Sam 10,6", "℘ Kap. 10,8"] },
      { number: 5, text: "Auch die Philister sammelten sich zum Kampf* mit Israel: 30 000* Wagen und sechstausend Gespanne und Fußvolk so viel wie der Sand am Ufer des Meeres*. Und sie zogen herauf und lagerten sich bei Michmas, östlich von Bet-Awen*.", footnotes: ["℘ Kap. 14,52; 17,1", "LXX: 3 000", "℘ Jos 11,4; Ri 7,12", "℘ Kap. 14,23; Jos 7,2"] },
      { number: 6, text: "Als aber die Männer von Israel sahen, dass sie in Not waren, weil das Kriegsvolk bedrängt wurde*, da versteckte sich das Volk in Höhlen und Dornsträuchern, in Felsen, in Gewölben und in Zisternen*.", footnotes: ["℘ Ri 10,9", "℘ Kap. 14,11.22; Ri 6,2"] },
      { number: 7, text: "Auch gingen Hebräer über den Jordan ins Land Gad und Gilead*. Saul aber war noch in Gilgal, und das ganze Volk, das ihm folgte, war voll Angst*.", footnotes: ["℘ Kap. 31,7; Jos 13,8.11", "w. zitterte hinter ihm her\n℘ Kap. 17,11"] },
      { number: 8, text: "Und er wartete sieben Tage bis zu der von Samuel bestimmten Zeit*; aber Samuel kam nicht nach Gilgal. Und das Volk fing an, von ihm auseinanderzulaufen.", footnotes: ["℘ Kap. 10,8"] },
      { number: 9, text: "Da sagte Saul: Bringt mir das Brandopfer und die Heilsopfer* her! Und er opferte das Brandopfer.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 10, text: "Und es geschah, als er eben fertig war, das Brandopfer zu opfern, siehe, da kam Samuel. Und Saul ging hinaus, ihm entgegen, um ihm den Segensgruß zu entbieten*.", footnotes: ["w. um ihn zu segnen"] },
      { number: 11, text: "Und Samuel sprach: Was hast du getan!* Saul antwortete: Weil ich sah, dass das Volk von mir auseinanderlief, und du kamst nicht zur bestimmten Zeit, während die Philister sich schon bei Michmas versammelt hatten,", footnotes: ["℘ 1Mo 4,10"] },
      { number: 12, text: "da dachte ich: Jetzt werden die Philister zu mir nach Gilgal herabkommen, und ich habe das Angesicht des HERRN noch nicht gesucht. Da wagte ich es* und opferte das Brandopfer*.", footnotes: ["o. fasste ich mir ein Herz; w. machte ich mich stark", "℘ Kap. 15,22"] },
      { number: 13, text: "Und Samuel sprach zu Saul: Du hast töricht gehandelt!* Du hast das Gebot des HERRN, deines Gottes, nicht gehalten, das er dir geboten hat*. Denn gerade jetzt hätte der HERR dein Königtum über Israel für immer* bestätigt;", footnotes: ["℘ Kap. 26,21; 1Mo 31,28; 2Sam 24,10", "℘ 1Chr 10,13", "w. für ewig, o. auf Dauer"] },
      { number: 14, text: "nun aber wird dein Königtum nicht bestehen*. Der HERR hat sich einen Mann gesucht nach seinem Herzen, und der HERR hat ihn zum Fürsten über sein Volk bestellt*; denn du hast nicht gehalten, was der HERR dir geboten hatte.", footnotes: ["℘ Kap. 15,23.26.28; 16,1; Spr 27,24; Apg 13,22", "℘ 2Sam 5,2"] },
      { number: 15, text: "Und Samuel machte sich auf und ging von Gilgal hinauf* nach Gibea in Benjamin. Und Saul musterte das Volk, das sich bei ihm befand, etwa sechshundert Mann*.", footnotes: ["LXX: und zog seines Weges; die Übrigen vom Volk aber zogen hinter Saul her, dem Kriegsvolk entgegen, von Gilgal hinauf", "℘ Kap. 14,2"] },
      { number: 16, text: "Und Saul und sein Sohn Jonatan und das Volk, das sich bei ihm befand, lagen bei Gibea in Benjamin; die Philister aber hatten sich bei Michmas gelagert." },
      { number: 17, text: "Da zog der Vernichtungstrupp* aus dem Lager der Philister in drei Abteilungen aus: eine Abteilung wandte sich in Richtung auf Ofra*, nach dem Land Schual hin,", footnotes: ["w. der Verderber", "℘ Jos 18,23"] },
      { number: 18, text: "und eine Abteilung wandte sich in Richtung auf Bet-Horon*, und eine Abteilung wandte sich in Richtung auf das Gebiet, das auf das Tal Zeboïm* nach der Wüste hin hinausschaut.", footnotes: ["℘ Jos 10,10", "℘ 1Mo 10,19; Neh 11,34"] },
      { number: 19, text: "Und es war kein Schmied im ganzen Land Israel zu finden. Denn die Philister dachten: Wir wollen nicht, dass die Hebräer sich Schwert oder Speer machen*!", footnotes: ["℘ Ri 5,8"] },
      { number: 20, text: "Und ganz Israel musste zu den Philistern hinabziehen, jeder um seine Pflugschar oder seinen Spaten, sein Beil oder seine Sichel* zu schärfen. —", footnotes: ["T.; Mas. T.: Pflugschar"] },
      { number: 21, text: "Das Schärfen geschah für einen Zweidrittelschekel bei den Pflugscharen und bei den Spaten, bei der Gabel und bei den Beilen und um die Rinderstacheln geradezurichten*. —", footnotes: ["o. einzusetzen"] },
      { number: 22, text: "Und es geschah am Tag des Kampfes, dass weder Schwert noch Speer in der Hand des ganzen Volkes gefunden wurde, das mit Saul und mit Jonatan war; nur bei Saul und seinem Sohn Jonatan fanden sie sich vor." },
      { number: 23, text: "Und ein Posten der Philister zog aus, auf den Pass von Michmas* zu.", footnotes: ["℘ Jes 10,28"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und es geschah eines Tages, dass Jonatan, der Sohn Sauls, zu dem Waffenträger* sagte: Komm, lass uns hinübergehen zu dem Posten der Philister, der dort drüben ist! Seinem Vater aber teilte er es nicht mit.*", heading: "Glaubenstat des Jonatan", footnotes: ["w. dem jungen Mann, der seine Waffen trug", "℘ Kap. 25,19; Ri 14,6.9"] },
      { number: 2, text: "Und Saul saß am Rand von Gibea* unter dem Granatapfelbaum, der in Migron* steht; und das Kriegsvolk bei ihm war etwa sechshundert Mann*.", footnotes: ["℘ Kap. 22,6; Jes 10,29", "℘ Jes 10,28", "℘ Kap. 13,15"] },
      { number: 3, text: "Und Ahija, der Sohn Ahitubs*, des Bruders Ikabods*, des Sohnes des Pinhas, des Sohnes Elis*, des Priesters des HERRN in Silo, trug das Efod*. Und das Volk hatte nicht erkannt, dass Jonatan weggegangen war.", footnotes: ["℘ Kap. 22,9", "℘ Kap. 4,21", "℘ Kap. 4,4", "d. i. ein Priesterschurz\n℘ Kap. 2,18"] },
      { number: 4, text: "Es waren aber zwischen den Pässen, durch die Jonatan zu dem Posten der Philister hinüberzugehen suchte, eine Felszacke auf der einen Seite und eine Felszacke auf der anderen Seite: Der Name der einen war Bozez und der Name der anderen Senne." },
      { number: 5, text: "Die eine Zacke bildete eine Säule im Norden gegenüber Michmas und die andere im Süden gegenüber Geba*.", footnotes: ["℘ Kap. 13,3; Jes 10,29"] },
      { number: 6, text: "Und Jonatan sprach zu dem Waffenträger*: Komm, lass uns hinübergehen zu dem Posten dieser Unbeschnittenen*! Vielleicht wird der HERR etwas für uns tun, denn für den HERRN gibt es kein Hindernis, durch viel oder durch wenig zu helfen*.", footnotes: ["w. dem jungen Mann, der seine Waffen trug", "℘ Kap. 17,26.36", "℘ Ri 7,4.7; 2Chr 14,10"] },
      { number: 7, text: "Und sein Waffenträger antwortete ihm: Tu alles, was du vorhast*! Geh nur hin! Siehe, ich bin mit dir in allem, was du vorhast*.", footnotes: ["w. was in deinem Herzen ist\n℘ 2Sam 7,3", "w. nach deinem Herzen\n℘ 2Sam 15,15"] },
      { number: 8, text: "Und Jonatan sagte: Siehe, wir wollen zu den Männern hinübergehen und uns ihnen zeigen." },
      { number: 9, text: "Wenn sie dann zu uns sagen: Halt, bis wir zu euch gelangt sind! — so wollen wir stehen bleiben, wo wir sind, und nicht zu ihnen hinaufgehen." },
      { number: 10, text: "Wenn sie aber so sprechen: Kommt zu uns herauf! — so wollen wir hinaufsteigen, denn der HERR hat sie in unsere Hand gegeben. Das soll uns zum Zeichen* sein.", footnotes: ["℘ 1Mo 24,14; 2Mo 3,12; 2Kö 20,9; Lk 1,18; 2,12"] },
      { number: 11, text: "Und beide zeigten sich dem Posten der Philister. Da sprachen die Philister: Sieh an, Hebräer* kommen aus den Löchern hervor, in denen sie sich versteckt haben*!", footnotes: ["℘ Kap. 29,3", "℘ Kap. 13,6"] },
      { number: 12, text: "Und die Männer der Wache riefen Jonatan und seinem Waffenträger zu und sagten: Kommt zu uns herauf, so wollen wir es euch schon lehren*! Da sagte Jonatan zu seinem Waffenträger: Steig hinauf, mir nach! Denn der HERR hat sie in die Hand Israels gegeben*.", footnotes: ["w. so werden wir euch etwas erkennen lassen", "℘ Ri 7,15"] },
      { number: 13, text: "Und Jonatan stieg auf Händen und Füßen* hinauf und sein Waffenträger ihm nach. Und sie fielen vor Jonatan zu Boden, und sein Waffenträger hinter ihm tötete sie*.", footnotes: ["w. auf seinen Händen und auf seinen Füßen", "℘ 3Mo 26,8; Hebr 11,34"] },
      { number: 14, text: "So traf der erste Schlag, den Jonatan und sein Waffenträger taten, an die zwanzig Mann, sie fielen etwa auf einer halben Furchenlänge eines Joches Acker*.", footnotes: ["Ein Joch Acker ist eine Fläche, die ein Gespann Rinder an einem Tag pflügen kann."] },
      { number: 15, text: "Und es entstand ein Schrecken im Lager, auf dem Feld und unter dem ganzen Kriegsvolk*. Auch der Posten und *die Schar, die das Land verwüsten sollte*, erschraken. Und die Erde erbebte, und so entstand ein Schrecken Gottes*.", footnotes: ["℘ 2Kö 7,6.7; Ps 14,5", "w. der Verderber", "w. der Verderber", "℘ 1Mo 35,5"] },
      { number: 16, text: "Und die Wächter Sauls zu Gibea-Benjamin sahen, und siehe, ein lärmendes Getümmel, das immer hin und her wogte.", heading: "Sauls Sieg über die Philister" },
      { number: 17, text: "Und Saul sagte zu dem Volk, das bei ihm war: Lasst doch antreten und seht, wer von uns weggegangen ist! Und sie ließen antreten, siehe, da fehlten Jonatan und sein Waffenträger." },
      { number: 18, text: "Da sagte Saul zu Ahija: Bring die Lade Gottes* herbei! Denn die Lade Gottes war an jenem Tag unter* den Söhnen Israel.", footnotes: ["LXX: das Efod", "LXX: Denn er trug in jener Zeit das Efod vor"] },
      { number: 19, text: "Und es geschah, während Saul noch zu dem Priester redete*, nahm das Getümmel im Lager der Philister immer mehr zu; und Saul sagte zu dem Priester: Zieh deine Hand zurück!", footnotes: ["℘ Kap. 30,7.8; 4Mo 27,21"] },
      { number: 20, text: "Und Saul und alles Volk, das bei ihm war, versammelten sich und kamen zum Kampf. Und siehe, da war das Schwert des einen gegen den andern — eine sehr große Verwirrung*.", footnotes: ["o. Bestürzung\n℘ Ri 7,22"] },
      { number: 21, text: "Und die Hebräer waren bei den Philistern wie schon früher; die nun, die* mit ihnen ins Feldlager hinaufgezogen waren, auch sie wandten sich*, um mit Israel zu sein, das bei Saul und Jonatan war*.", footnotes: ["Andere üs. mit Textänderung: Und die Hebräer, die bei den Philistern waren wie schon früher, und die", "so mit LXX, Vulg. und der syr. Üs.; Mas. T.: die mit ihnen ins Feldlager hinaufgezogen waren ringsum, auch sie waren da", "℘ Kap. 29,4"] },
      { number: 22, text: "Als aber alle Männer von Israel, die sich im Gebirge Ephraim versteckt hatten, hörten, dass die Philister flohen, setzten auch sie ihnen nach im Kampf*.", footnotes: ["℘ Ri 7,23"] },
      { number: 23, text: "So rettete der HERR Israel an demselben Tag*. Und der Kampf zog sich bis über Bet-Awen* hinaus.", footnotes: ["℘ Kap. 9,16; 2Mo 14,30; 5Mo 20,4", "℘ Kap. 13,5"] },
      { number: 24, text: "Als die Männer von Israel an jenem Tag ins Gedränge kamen, beschwor Saul das Volk und sagte: Verflucht sei jeder*, der vor dem Abend etwas* isst, bis ich mich an meinen Feinden gerächt habe*! Und das ganze Volk kostete keine Speise*.", heading: "Sauls unbesonnener Schwur und dessen Folgen", footnotes: ["w. der Mann", "w. Brot, o. Speise", "℘ Kap. 18,25; Ri 21,5", "d. h. nahm keine Speise zu sich"] },
      { number: 25, text: "Und das ganze Land war in die Zeit der Honigernte* gekommen, und es gab Honig auf der Fläche des Feldes*.", footnotes: ["w. in die Honigwaben. — Andere üs.: das ganze Volk kam in den Wald. Für »Wald« und »Honigwabe« steht im Hebr. dasselbe Wort.", "℘ Mt 3,4"] },
      { number: 26, text: "Und als das Volk zu den Waben* kam, siehe, da floss der* Honig; aber niemand brachte etwas davon mit seiner Hand in seinen Mund, denn das Volk fürchtete den Schwur*.", footnotes: ["o. in den Wald", "w. ein Daherfließen von", "℘ Pred 8,2"] },
      { number: 27, text: "Jonatan aber hatte nicht gehört, dass sein Vater das Volk mit einem Schwur belegt hatte. Und er streckte die Spitze seines Stabes aus, den er in seiner Hand hatte, und tauchte sie in die Honigwabe und führte seine Hand wieder zu seinem Mund, und seine Augen wurden wieder hell*.", footnotes: ["℘ Spr 24,13"] },
      { number: 28, text: "Einer von dem Volk aber fing an und sagte: Dein Vater hat das Volk feierlich beschworen und gesagt: Verflucht sei jeder*, der heute etwas* essen wird! Und so ist das Volk matt geworden.", footnotes: ["w. der Mann", "w. Brot, o. Speise"] },
      { number: 29, text: "Da antwortete Jonatan: Mein Vater bringt das Land ins Unglück. Seht doch, wie meine Augen hell geworden sind, weil ich ein wenig von diesem Honig gekostet habe." },
      { number: 30, text: "Wie viel mehr, wenn das Volk heute tüchtig von der Beute seiner Feinde gegessen hätte, die es gefunden hat! Denn jetzt ist die Niederlage unter den Philistern nicht groß!" },
      { number: 31, text: "Und sie schlugen die Philister an jenem Tag von Michmas bis nach Ajalon*. Und das Volk war sehr matt geworden.", footnotes: ["℘ Jos 10,12"] },
      { number: 32, text: "Und das Volk fiel über die Beute her, und sie nahmen Schafe, Rinder und Kälber und schlachteten sie einfach auf der Erde; und das Volk aß das Fleisch über dem Blut." },
      { number: 33, text: "Und man berichtete es Saul und sagte: Siehe, das Volk versündigt sich an dem HERRN, denn es isst das Fleisch über dem Blut. Und er rief: Ihr habt treulos gehandelt! Wälzt sofort einen großen Stein her zu mir!" },
      { number: 34, text: "Und Saul sagte weiter: Zerstreut euch unter das Volk und sagt ihnen: Jeder soll sein Rind und sein Schaf zu mir bringen und es hier schlachten und essen, damit ihr euch nicht am HERRN versündigt, indem ihr über dem Blut esst*! Und in jener Nacht brachte das ganze Volk jeder eigenhändig sein Rind*; und sie schlachteten es dort.", footnotes: ["℘ 1Mo 9,4", "w. jeder sein Rind mit seiner Hand"] },
      { number: 35, text: "Und Saul baute dem HERRN einen Altar*. Das war der erste Altar, den er dem HERRN baute*.", footnotes: ["℘ Kap. 7,17; Ri 6,24", "w. Mit diesem fing er an, dem HERRN einen Altar zu bauen"] },
      { number: 36, text: "Und Saul sagte: Lasst uns noch in der Nacht hinabziehen, den Philistern nach, und unter ihnen plündern, bis der Morgen hell wird, und niemand von ihnen übrig lassen! Sie antworteten: Tu alles, was in deinen Augen gut ist!* Und der Priester sagte: Erst lasst uns hier Gott nahen*!", footnotes: ["℘ Kap. 1,23", "℘ Ps 73,28"] },
      { number: 37, text: "Und Saul fragte Gott: Soll ich hinabziehen, den Philistern nach? Willst du sie in die Hand Israels geben*? Aber er antwortete ihm nicht an diesem Tag*.", footnotes: ["℘ Kap. 23,2; 30,8", "℘ Kap. 28,6"] },
      { number: 38, text: "Da sagte Saul: Tretet hierher, alle Anführer* des Volkes, und erkennt und seht, wodurch heute diese Verschuldung geschehen ist!", footnotes: ["w. Ecksteine, o. Ecktürme"] },
      { number: 39, text: "Denn so wahr der HERR lebt, der Israel gerettet hat, selbst wenn sie bei meinem Sohn Jonatan wäre, soll er bestimmt sterben*! Aber niemand aus dem ganzen Volk antwortete ihm.", footnotes: ["℘ 2Sam 12,5"] },
      { number: 40, text: "Und er sprach zu ganz Israel: Ihr sollt auf der einen Seite stehen, und ich und mein Sohn Jonatan wollen auf der anderen Seite sein. Und das Volk antwortete Saul: Tu, was in deinen Augen gut ist!*", footnotes: ["℘ Kap. 1,23"] },
      { number: 41, text: "Und Saul sprach zu dem HERRN, dem Gott Israels: Gib rechten Entscheid!* Da wurden Jonatan und Saul getroffen, aber das Volk ging frei aus.", footnotes: ["LXX, Vulg. und die alte lat. Üs. überliefern anstelle von: »Gib rechten Entscheid!«: Warum hast du heute deinem Knecht nicht geantwortet? Liegt die Schuld bei mir oder bei meinem Sohn Jonatan, HERR, Gott Israels, so gib das Los »Licht«! Liegt die Schuld aber bei deinem Volk Israel, so gib das Los »Recht«!"] },
      { number: 42, text: "Und Saul sagte: Werft das Los über mich und meinen Sohn Jonatan! Da wurde Jonatan getroffen*.", footnotes: ["℘ Jos 7,18; Spr 16,33; Apg 1,26"] },
      { number: 43, text: "Da sprach Saul zu Jonatan: Bekenne mir, was du getan hast*! Und Jonatan bekannte ihm und sagte: Mit der Spitze des Stabes, den ich in meiner Hand hatte, habe ich nur ein wenig Honig gekostet. Siehe, ich muss sterben!", footnotes: ["℘ Jos 7,19"] },
      { number: 44, text: "Und Saul sprach: So tue mir Gott und so füge er hinzu*, ja, du musst sterben, Jonatan*!", footnotes: ["d. i. Gottes Zorn komme über mich!\n℘ Kap. 3,17", "℘ Ri 11,35"] },
      { number: 45, text: "Aber das Volk sagte zu Saul: Sollte Jonatan sterben, der diese große Rettungstat in Israel vollbracht hat?* Das sei ferne*! So wahr der HERR lebt! Wenn von den Haaren seines Hauptes eins auf die Erde fällt*! Hat er es doch nur mit Gott schaffen können an diesem Tage. So löste das Volk Jonatan aus, so dass er nicht sterben musste.", footnotes: ["℘ Kap. 11,13", "w. Das sei etwas Entweihtes", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ 2Sam 14,11; Apg 27,34"] },
      { number: 46, text: "Und Saul ließ von der Verfolgung der Philister ab und zog hinauf*, und die Philister kehrten an ihren Wohnort zurück.", footnotes: ["w. und Saul zog hinauf von den Philistern weg"] },
      { number: 47, text: "Als Saul das Königtum über Israel erlangt hatte*, kämpfte er ringsum gegen all seine Feinde, gegen Moab, gegen die Söhne Ammon* und gegen Edom*, gegen die Könige von Zoba* und gegen die Philister; und überall, wohin er sich wandte, war er siegreich*.", footnotes: ["℘ 2Sam 8,15", "℘ Kap. 11,11; 1Mo 19,37.38", "℘ 1Mo 36,8.9", "℘ 2Sam 8,3", "so mit LXX; Mas. T.: erklärte er für schuldig"] },
      { number: 48, text: "Und er vollbrachte tapfere Taten und schlug Amalek* und rettete Israel aus der Hand seines Plünderers*.", footnotes: ["℘ Kap. 15,3.7; 2Mo 17,8", "℘ 2Sam 1,22; Ri 2,16"] },
      { number: 49, text: "Die Söhne Sauls waren: Jonatan, Jischwi und Malkischua*. Und die Namen seiner beiden Töchter waren: der Name der erstgeborenen war Merab und der Name der jüngeren Michal*.", footnotes: ["℘ Kap. 31,2; 1Chr 8,33", "℘ Kap. 18,17.20"] },
      { number: 50, text: "Der Name der Frau Sauls war Ahinoam, eine Tochter des Ahimaaz. Der Name seines Heerobersten war Abner, ein Sohn Ners*, des Onkels Sauls;", footnotes: ["℘ Kap. 17,55; 26,5; 2Sam 2,8; 3,6"] },
      { number: 51, text: "denn Kisch, der Vater Sauls, und Ner, der Vater Abners, waren Söhne Abiels*.", footnotes: ["℘ Kap. 9,1"] },
      { number: 52, text: "Und der Krieg gegen die Philister* war schwer alle Tage Sauls. Wenn Saul irgendeinen tapferen und kampffähigen Mann sah, stellte er ihn in seinen Dienst*.", footnotes: ["℘ Kap. 13,5", "w. Und sah Saul irgendeinen tapferen Mann und irgendeinen Sohn der kriegerischen Stärke, so scharte er ihn um sich\n℘ Kap. 8,11"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Samuel sagte zu Saul: Der HERR hat mich gesandt, um dich zum König über sein Volk, über Israel*, zu salben. So höre nun auf die Stimme der Worte des HERRN!", heading: "Sauls Sieg über Amalek, seine Missachtung des Banngebotes und Verlust der Königswürde", footnotes: ["℘ Kap. 10,1; 2Kö 7,1"] },
      { number: 2, text: "So spricht der HERR der Heerscharen: Ich habe bedacht, was Amalek Israel angetan, wie es sich ihm in den Weg gestellt hat, als Israel aus Ägypten heraufzog*.", footnotes: ["℘ 2Mo 17,14"] },
      { number: 3, text: "Nun zieh hin und schlage Amalek! Und vollstreckt den Bann an ihnen, an allem, was es hat, und verschone ihn nicht, sondern töte Mann und Frau, Kind und Säugling, Rind und Schaf, Kamel und Esel*!", footnotes: ["w. vom Mann bis zur Frau, vom Kind usw.\n℘ Kap. 22,19; 3Mo 27,29; Jos 10,39"] },
      { number: 4, text: "Da rief Saul das Volk auf und musterte sie in Telem*, 200 000 Mann zu Fuß und 10 000 Männer aus Juda.", footnotes: ["℘ Jos 15,24"] },
      { number: 5, text: "Und Saul kam bis zur Stadt der Amalekiter und legte einen Hinterhalt in das Tal*.", footnotes: ["℘ Jos 8,12"] },
      { number: 6, text: "Und Saul ließ den Kenitern* sagen: Geht, weicht, zieht weg von den Amalekitern*, dass ich dich nicht mit ihnen wegraffe! Denn du, du hast allen Söhnen Israel Gnade erwiesen, als sie aus Ägypten heraufzogen*. Da zogen die Keniter fort von Amalek*.", footnotes: ["℘ Kap. 27,10; 1Mo 15,19; Ri 1,16", "w. zieht weg aus der Mitte der Amalekiter", "℘ 4Mo 10,29-32", "w. wichen die Keniter aus der Mitte Amaleks"] },
      { number: 7, text: "Und Saul schlug die Amalekiter* von Hawila bis nach Schur*, das vor Ägypten liegt.", footnotes: ["℘ Kap. 14,48", "℘ Kap. 27,8; 1Mo 16,7"] },
      { number: 8, text: "Und er ergriff Agag*, den König der Amalekiter, lebend. Und an dem ganzen Volk vollstreckte er den Bann mit der Schärfe des Schwertes*.", footnotes: ["℘ 4Mo 24,7.20", "℘ Kap. 22,19; 3Mo 27,29; Jos 10,39"] },
      { number: 9, text: "Aber Saul und das Volk verschonten Agag* und die besten Schafe und Rinder und die Tiere vom zweiten Wurf* und die Lämmer und alles, was wertvoll war, daran wollten sie nicht den Bann vollstrecken. Alles Vieh aber, das verachtet* und schwächlich war, daran vollstreckten sie den Bann*.", footnotes: ["℘ 1Kö 20,34", "aram. Üs.: das Mastvieh", "so nach der griech., aram., syr. und lat. Üs. Der Mas. T. ist unverständlich.", "℘ Kap. 28,18; Jos 6,18"] },
      { number: 10, text: "Da geschah das Wort des HERRN zu Samuel:" },
      { number: 11, text: "Es reut mich, dass ich Saul zum König gemacht habe*; denn er hat sich von mir* abgewandt* und hat meine Worte nicht ausgeführt*. Da entbrannte dem Samuel der Zorn*, und er schrie zu dem HERRN die ganze Nacht*.", footnotes: ["℘ V. 35; 1Mo 6,6", "w. von der Nachfolge hinter mir her", "℘ 1Kö 11,9", "℘ 1Chr 10,13; Jer 18,10", "lat. Üs.: Das tat Samuel bitter weh", "℘ Kap. 8,6"] },
      { number: 12, text: "Und am frühen Morgen machte Samuel sich auf*, um Saul zu begegnen*. Da wurde Samuel berichtet: Saul ist nach Karmel* gekommen*. Und siehe, er hat sich ein Siegeszeichen errichtet*, und er hat sich gewandt und ist weitergegangen und nach Gilgal hinabgekommen.", footnotes: ["℘ Kap. 17,20; 1Mo 21,14", "w. Saul entgegen", "d. i. Karmel in Juda", "℘ Kap. 25,2; Jos 15,55; 2Sam 23,35; 2Chr 26,10", "℘ 2Sam 18,18"] },
      { number: 13, text: "Als Samuel zu Saul kam, sagte Saul zu ihm: Gesegnet seist du von dem HERRN!* Ich habe das Wort des HERRN erfüllt*.", footnotes: ["℘ Kap. 23,21; Ri 17,2; Rt 3,10", "℘ Spr 28,13"] },
      { number: 14, text: "Und Samuel antwortete: Was ist denn das für ein Blöken von Schafen, das zu meinen Ohren kommt*, und ein Brüllen von Rindern, das ich höre?", footnotes: ["w. diese Stimme von Schafen in meinen Ohren"] },
      { number: 15, text: "Saul sagte: Von den Amalekitern hat man sie gebracht, denn das Volk* verschonte die besten Schafe und Rinder, um sie dem HERRN, deinem Gott, zu opfern; an den übrigen haben wir den Bann vollstreckt.", footnotes: ["℘ 1Mo 3,12"] },
      { number: 16, text: "Da sprach Samuel zu Saul: Halt ein, damit ich dir verkünde, was der HERR diese Nacht zu mir geredet hat*! Und er sagte zu ihm: Rede!", footnotes: ["℘ Kap. 9,27; 1Kö 14,6"] },
      { number: 17, text: "Und Samuel sprach: Wurdest du nicht, als du gering in deinen Augen warst, das Oberhaupt der Stämme Israels*? Und der HERR salbte dich zum König über Israel.", footnotes: ["℘ Kap. 9,21; 10,1.22; Mt 23,12"] },
      { number: 18, text: "Und der HERR sandte dich auf den Weg und sagte: Zieh hin und vollstrecke den Bann an den Sündern, an Amalek und kämpfe mit ihnen, bis du sie vernichtet hast!" },
      { number: 19, text: "Warum hast du denn der Stimme des HERRN nicht gehorcht* und bist über die Beute hergefallen und hast getan, was in den Augen des HERRN böse ist?", footnotes: ["℘ 4Mo 14,41; 2Sam 12,9"] },
      { number: 20, text: "Und Saul antwortete Samuel: Ich habe der Stimme des HERRN gehorcht und bin den Weg gezogen, den der HERR mich gesandt hat. Ich habe Agag, den König von Amalek, hergebracht und an Amalek den Bann vollstreckt." },
      { number: 21, text: "Aber das Volk* hat von der Beute genommen: Schafe und Rinder, das Beste vom Gebannten, um es dem HERRN, deinem Gott, in Gilgal zu opfern.", footnotes: ["℘ 1Mo 3,12"] },
      { number: 22, text: "Samuel aber sprach: Hat der HERR so viel Lust an Brandopfern und Schlachtopfern wie daran, dass man der Stimme des HERRN gehorcht? Siehe, Gehorchen ist besser als Schlachtopfer*, Aufmerken besser als das Fett der Widder*.", footnotes: ["℘ Kap. 13,12; Spr 21,3; Pred 4,17; Jes 1,11-17; Jer 7,22.23; Hos 6,6; 8,13; Am 5,22.24; Mk 12,33", "℘ Kap. 13,12; Spr 21,3; Pred 4,17; Jes 1,11-17; Jer 7,22.23; Hos 6,6; 8,13; Am 5,22.24; Mk 12,33"] },
      { number: 23, text: "Denn Widerspenstigkeit ist eine Sünde wie Wahrsagerei, und Widerstreben ist wie Abgötterei und Götzendienst. Weil du das Wort des HERRN verworfen hast, so hat er dich auch verworfen, dass du nicht mehr König sein sollst*.", footnotes: ["℘ Kap. 13,14; 16,1; 2Sam 7,15; Hos 13,11; Apg 13,22"] },
      { number: 24, text: "Saul sagte zu Samuel: Ich habe gesündigt*, dass ich den Befehl des HERRN und deine Worte übertreten habe; denn ich fürchtete das Volk und hörte auf seine Stimme*.", footnotes: ["℘ Kap. 26,21; 2Mo 9,27", "℘ 2Mo 23,2; Spr 29,25; Gal 1,10"] },
      { number: 25, text: "Und nun, vergib mir doch meine Sünde* und kehre mit mir um, dass ich den HERRN anbete*!", footnotes: ["℘ 2Mo 10,17", "℘ 2Sam 12,20"] },
      { number: 26, text: "Aber Samuel sprach zu Saul: Ich kehre nicht mit dir um. Denn du hast das Wort des HERRN verworfen, und der HERR hat dich verworfen, dass du nicht mehr König über Israel sein sollst*.", footnotes: ["℘ Kap. 13,14; 16,1; 2Sam 7,15; Hos 13,11; Apg 13,22"] },
      { number: 27, text: "Als Samuel sich umwandte, um wegzugehen, da ergriff Saul* ihn beim Zipfel seines Oberkleides*, so dass er abriss.", footnotes: ["w. er", "℘ Kap. 28,14"] },
      { number: 28, text: "Da sprach Samuel zu ihm: Der HERR hat heute das Königtum Israels von dir abgerissen* und es einem anderen gegeben, der besser ist als du*.", footnotes: ["℘ 1Kö 11,11.30.31", "℘ Kap. 18,8; 25,30; 28,17; 2Sam 3,10; Hi 34,24; Apg 13,22"] },
      { number: 29, text: "Auch lügt der nicht, der Israels Ruhm ist*, und es gereut ihn nicht. Denn nicht ein Mensch ist er, dass ihn etwas gereuen könnte*.", footnotes: ["℘ Tit 1,2", "℘ 4Mo 23,19; Hes 24,14"] },
      { number: 30, text: "Und er sprach: Ich habe gesündigt!* Aber ehre mich doch vor den Ältesten meines Volkes und vor Israel* und kehre mit mir um, dass ich den HERRN, deinen Gott, anbete!", footnotes: ["℘ Kap. 26,21; 2Mo 9,27", "℘ Joh 12,43"] },
      { number: 31, text: "Und Samuel kehrte um und folgte Saul nach, und Saul betete den HERRN an*.", footnotes: ["℘ 2Sam 12,20"] },
      { number: 32, text: "Und Samuel sprach: Bringt Agag, den König von Amalek, zu mir her*! Und Agag kam widerstrebend* zu ihm. Und Agag sagte: Fürwahr, die Bitterkeit des Todes ist gewichen*!", footnotes: ["℘ Jos 10,22", "Die Bedeutung des hebr. Wortes ist unklar; vielleicht: in Fesseln (wie Hi 38,31); o. heiter", "Andere üs.: bitter ist der Tod"] },
      { number: 33, text: "Aber Samuel sagte: Wie dein Schwert Frauen kinderlos gemacht hat, so sei auch deine Mutter kinderlos unter den Frauen*! Und Samuel hieb Agag in Stücke vor dem HERRN in Gilgal*.", footnotes: ["℘ Ri 1,7", "℘ Kap. 10,8"] },
      { number: 34, text: "Und Samuel ging nach Rama*. Saul aber zog in sein Haus hinauf nach Gibea-Saul*.", footnotes: ["℘ Kap. 1,19", "℘ Kap. 10,26"] },
      { number: 35, text: "Und Samuel sah Saul nicht mehr bis zum Tag seines Todes. Denn Samuel trauerte um Saul*, da es den HERRN reute, dass er Saul zum König über Israel gemacht hatte.*", footnotes: ["℘ Kap. 16,1", "℘ V. 11"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und der HERR sprach zu Samuel: Wie lange willst du um Saul trauern*, den ich doch verworfen habe, dass er nicht mehr König über Israel sei*? Fülle dein Horn mit Öl und geh hin! Ich will dich zu dem Bethlehemiter Isai* senden; denn ich habe mir unter seinen Söhnen einen zum König ausersehen*.", heading: "David wird zum König gesalbt", footnotes: ["℘ Kap. 15,35", "℘ Kap. 13,14; 15,11.23", "℘ Lk 3,32", "℘ Kap. 17,12.58"] },
      { number: 2, text: "Und Samuel antwortete: Wie kann ich hingehen? Wenn Saul es hört, so wird er mich umbringen*. Der HERR sprach: Nimm eine junge Kuh mit dir und sage: Ich bin gekommen, um dem HERRN zu opfern*!", footnotes: ["℘ 1Kö 18,12", "℘ Kap. 9,12; 20,29"] },
      { number: 3, text: "Und lade Isai zum Schlachtopfer, und ich werde dir zu erkennen geben, was du tun sollst*! Und du sollst mir den salben, den ich dir nennen werde*.", footnotes: ["℘ Apg 9,6", "℘ 5Mo 17,15"] },
      { number: 4, text: "Und Samuel tat, was der HERR geredet hatte, und kam nach Bethlehem*. Da kamen die Ältesten der Stadt ihm aufgeregt entgegen und sagten: Bedeutet dein Kommen Friede*?", footnotes: ["℘ 1Mo 35,19", "℘ 1Kö 2,13; 1Chr 12,18"] },
      { number: 5, text: "Und er sprach: Ja, Friede*! Ich bin gekommen, um dem HERRN ein Opfer zu bringen. Heiligt euch und kommt mit mir zum Schlachtopfer! Und er heiligte Isai und seine Söhne* und lud sie zum Schlachtopfer.", footnotes: ["℘ 1Kö 2,13; 1Chr 12,18", "℘ Jos 3,5; Hi 1,5"] },
      { number: 6, text: "Und es geschah, als sie kamen, sah er den Eliab* und meinte: Gewiss, da steht sein Gesalbter vor dem HERRN!", footnotes: ["℘ Kap. 17,13; 1Kö 4,11; 1Chr 2,13"] },
      { number: 7, text: "Aber der HERR sprach zu Samuel: Sieh nicht auf sein Aussehen und auf seinen hohen Wuchs! Denn ich habe ihn verworfen. Denn der HERR sieht nicht auf das, worauf der Mensch sieht*. Denn der Mensch sieht auf das, was vor Augen ist*, aber der HERR sieht auf das Herz*.", footnotes: ["℘ Hi 10,4; 35,5; Jes 55,8.9", "w. der Mensch sieht auf die Augen", "℘ 1Kö 8,39; Spr 15,11; 1Petr 3,4"] },
      { number: 8, text: "Da rief Isai den Abinadab* und ließ ihn vor Samuel vorübergehen. Aber er sprach: Auch diesen hat der HERR nicht erwählt.", footnotes: ["℘ Kap. 17,13; 1Kö 4,11; 1Chr 2,13"] },
      { number: 9, text: "Dann ließ Isai Schamma* vorübergehen. Er aber sprach: Auch diesen hat der HERR nicht erwählt.", footnotes: ["℘ Kap. 17,13; 1Kö 4,11; 1Chr 2,13"] },
      { number: 10, text: "Und Isai ließ seine sieben Söhne vor Samuel vorübergehen. Aber Samuel sprach zu Isai: Der HERR hat keinen von ihnen erwählt." },
      { number: 11, text: "Und Samuel fragte Isai: Sind das die jungen Leute alle*? Er antwortete: Der Jüngste ist noch übrig, siehe, er weidet die Schafe*. Und Samuel sagte zu Isai: Sende hin und lass ihn holen! Denn wir werden uns nicht zu Tisch setzen, bis er hierhergekommen ist*.", footnotes: ["℘ Kap. 17,12", "℘ Kap. 17,14.15.34; 2Mo 3,1", "℘ Ps 78,70.71"] },
      { number: 12, text: "Da sandte er hin und ließ ihn holen. Und er war rötlich* und hatte schöne Augen und ein gutes Aussehen*. Und der HERR sprach: Auf, salbe ihn! Denn der ist es!", footnotes: ["o. braun; d. i. wie die rotbraune Erde", "℘ V. 18; Kap. 17,42; 1Mo 39,6"] },
      { number: 13, text: "Da nahm Samuel das Ölhorn und salbte ihn* mitten unter seinen Brüdern*. Und der Geist des HERRN geriet über David* von diesem Tag an und darüber hinaus. Samuel aber machte sich auf und ging nach Rama*.", footnotes: ["℘ Kap. 10,1; 2Sam 12,7; Ps 89,21", "℘ 1Chr 11,3; Apg 13,22", "℘ Kap. 10,10; Lk 3,31; Hebr 11,32", "℘ Kap. 1,19"] },
      { number: 14, text: "Aber der Geist des HERRN wich von Saul*, und ein böser Geist vom HERRN ängstigte ihn*.", heading: "David bei Saul", footnotes: ["℘ Kap. 18,12; 28,15; Ri 16,20", "℘ Kap. 18,10; 19,9; Ri 9,23"] },
      { number: 15, text: "Und die Knechte Sauls sagten zu ihm: Sieh, ein böser Geist von Gott ängstigt dich*.", footnotes: ["℘ Kap. 18,10; 19,9; Ri 9,23"] },
      { number: 16, text: "Unser Herr befehle seinen Knechten*, die vor ihm stehen, dass sie einen Mann suchen, der die Zither zu spielen weiß*. Und es wird geschehen, wenn der böse Geist von Gott über dich kommt, so wird er mit seiner Hand spielen, und es wird besser mit dir werden.", footnotes: ["w. deinen Knechten vor dir", "w. der erkannt hat, wie man die Zither spielt"] },
      { number: 17, text: "Und Saul sagte zu seinen Knechten: Seht euch nach einem Mann für mich um, der gut spielen kann, und bringt ihn zu mir!" },
      { number: 18, text: "Und einer von den jungen Männern antwortete: Siehe, ich habe einen Sohn des Bethlehemiters Isai gesehen, der die Zither zu spielen weiß*, ein tapferer Mann*, tüchtig zum Kampf* und des Wortes mächtig*, von guter Gestalt*, und der HERR ist mit ihm*.", footnotes: ["w. der erkannt hat, wie zu spielen ist", "℘ 2Sam 17,8.10", "w. ein Mann des Kampfes", "o. einsichtsvoll im Reden; d. h. der ein verständiges, hilfreiches Wort zu sagen vermag", "℘ V. 12", "℘ Kap. 3,19"] },
      { number: 19, text: "Da sandte Saul Boten zu Isai und ließ ihm sagen: Sende deinen Sohn David zu mir, der bei den Schafen ist*!", footnotes: ["℘ Kap. 17,15"] },
      { number: 20, text: "Da nahm Isai einen Esel und belud ihn mit Brot* und einen Schlauch Wein und ein Ziegenböckchen und sandte es Saul durch seinen Sohn David.", footnotes: ["so mit LXX und der alten lat. Üs.; Mas. T.: einen Esel Brotes; d. h. mit so viel Brot beladen, wie ein Esel tragen kann"] },
      { number: 21, text: "So kam David zu Saul und diente ihm*. Und Saul gewann ihn sehr lieb, und er wurde sein Waffenträger*.", footnotes: ["w. stand vor ihm\n℘ 1Mo 41,46", "℘ Spr 22,29"] },
      { number: 22, text: "Und Saul sandte zu Isai und ließ ihm sagen: Lass doch David in meinen Dienst treten*, denn er hat Gunst gefunden in meinen Augen*!", footnotes: ["w. vor mir stehen", "℘ 1Mo 39,4.21"] },
      { number: 23, text: "Und es geschah, wenn der Geist von Gott über Saul kam, nahm David die Zither und spielte darauf mit seiner Hand*. Und Saul fand Erleichterung, und es ging ihm besser, und der böse Geist wich von ihm.", footnotes: ["℘ Kap. 18,10; 2Kö 3,15"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und die Philister sammelten ihre Heere zum Kampf* und versammelten sich zu Socho in Juda* und lagerten sich bei Efes-Dammim*, zwischen Socho* und Aseka*.", heading: "Davids Sieg über Goliat", footnotes: ["℘ Kap. 13,5", "o. das zu Juda gehörte", "℘ 1Chr 11,13", "℘ Jos 15,35", "℘ Jos 10,10"] },
      { number: 2, text: "Und Saul und die Männer von Israel versammelten und lagerten sich im Terebinthental, und sie stellten sich den Philistern gegenüber in Schlachtordnung auf." },
      { number: 3, text: "Und die Philister standen an einem Berg jenseits, und Israel stand an einem Berg diesseits, so dass das Tal zwischen ihnen war." },
      { number: 4, text: "Und ein Vorkämpfer trat aus den Lagern* der Philister heraus, sein Name war Goliat, aus Gat*; seine Größe war sechs Ellen und eine Spanne*.", footnotes: ["LXX: Reihen", "℘ Jos 11,22", "℘ 5Mo 3,11"] },
      { number: 5, text: "Und er hatte einen bronzenen Helm auf seinem Kopf und war mit einem Schuppenpanzer bekleidet. Das Gewicht des Panzers betrug 5 000 Schekel Bronze." },
      { number: 6, text: "Und er hatte bronzene Schienen an seinen Beinen und ein bronzenes Kurzschwert auf seiner Schulter." },
      { number: 7, text: "Und der Schaft seines Speeres war wie ein Weberbaum*, und die Spitze seines Speeres wog sechshundert Schekel Eisen*. Und der Schildträger ging vor ihm her.", footnotes: ["℘ 1Chr 20,5", "℘ 2Sam 21,16"] },
      { number: 8, text: "Und er stellte sich hin, rief den Schlachtreihen Israels zu und sprach zu ihnen: Wozu zieht ihr aus, um euch in Schlachtordnung aufzustellen? Bin ich nicht der Philister und ihr die Knechte Sauls*? Bestimmt einen Mann von euch, dass er zu mir herabkommt!", footnotes: ["℘ Kap. 8,17"] },
      { number: 9, text: "Wenn er mit mir zu kämpfen vermag und mich erschlägt, dann wollen wir eure Knechte sein. Wenn ich ihn aber überwinde und ihn erschlage, dann sollt ihr unsere Knechte sein und uns dienen." },
      { number: 10, text: "Und der Philister sagte: Ich verhöhne heute die Schlachtreihen Israels*! Gebt mir einen Mann, dass wir miteinander kämpfen!", footnotes: ["℘ V. 26; 2Sam 21,21; 2Kö 19,4"] },
      { number: 11, text: "Und Saul und ganz Israel hörten diese Worte des Philisters, und sie waren niedergeschlagen und fürchteten sich sehr*.", footnotes: ["℘ Kap. 13,7; 21,13; Ps 118,6; Jes 51,12"] },
      { number: 12, text: "David nun war der Sohn jenes Efratiters* von Bethlehem in Juda, mit Namen Isai*, der acht Söhne hatte*. Und der Mann war in den Tagen Sauls schon zu alt, um unter den Männern mitzukommen.", footnotes: ["℘ Kap. 1,1; Rt 1,2", "℘ V. 58; Kap. 16,1.18; Rt 4,17.22; 2Sam 23,1; Joh 7,42", "℘ 1Chr 2,13-16"] },
      { number: 13, text: "Die drei ältesten Söhne Isais aber waren mit Saul in den Krieg gezogen*. Die Namen seiner drei Söhne, die in den Krieg zogen, waren: Eliab, der Erstgeborene, und der zweite Abinadab und der dritte Schamma.*", footnotes: ["w. Und die drei ältesten Söhne Isais waren gegangen, sie waren Saul in den Krieg nachgefolgt", "℘ Kap. 16,6-9"] },
      { number: 14, text: "Und David war der Jüngste*, und die drei Ältesten waren Saul gefolgt.", footnotes: ["℘ Kap. 16,11"] },
      { number: 15, text: "David aber ging ab und zu von Saul weg, um die Schafe seines Vaters in Bethlehem zu weiden*. —", footnotes: ["℘ V. 34; Kap. 16,19"] },
      { number: 16, text: "Und der Philister trat morgens und abends heraus und stellte sich hin, vierzig Tage lang. —" },
      { number: 17, text: "Isai aber sagte zu seinem Sohn David: Nimm doch für deine Brüder dieses Efa geröstete Körner und diese zehn Brote und bring sie schnell in das Lager zu deinen Brüdern!" },
      { number: 18, text: "Und diese zehn Stücke Weichkäse bring dem Obersten über Tausend und erkundige dich, ob es deinen Brüdern gut geht*, und bring ein Pfand von ihnen mit*!", footnotes: ["w. besuche deine Brüder, um nach ihrem Wohlergehen zu fragen", "℘ Kap. 25,5; 30,21; 1Mo 37,14; 2Mo 18,7; Ri 18,15"] },
      { number: 19, text: "Saul und sie und alle Männer von Israel stehen im Terebinthental im Kampf mit den Philistern. —" },
      { number: 20, text: "Da machte sich David des Morgens früh auf* und überließ die Schafe einem Hüter. Er nahm und ging hin, wie Isai ihm geboten hatte, und kam zum Lagerplatz. Als das Heer aber in die Schlachtreihe ausrückte, erhoben sie das Kampfgeschrei.", footnotes: ["℘ Kap. 15,12; Jos 3,1"] },
      { number: 21, text: "Und Israel und die Philister stellten sich auf, Schlachtreihe gegen Schlachtreihe." },
      { number: 22, text: "David ließ sein Gepäck, das er trug, bei der Wache des Trosses* und lief in die Schlachtreihe. Und er kam und fragte seine Brüder nach ihrem Wohlergehen*.", footnotes: ["w. ließ die Geräte bei ihm auf der Hand der Wache der Geräte", "℘ Kap. 25,5; 30,21; 1Mo 37,14; 2Mo 18,7; Ri 18,15"] },
      { number: 23, text: "Während er noch mit ihnen redete, siehe, da kam der Vorkämpfer herauf, mit Namen Goliat, der Philister von Gat, aus den Schlachtreihen der Philister und redete dieselben Worte; und David hörte es." },
      { number: 24, text: "Als aber alle Männer von Israel den Mann sahen, flohen sie vor ihm und fürchteten sich sehr*.", footnotes: ["℘ 4Mo 13,33"] },
      { number: 25, text: "Und die Männer von Israel sagten: Habt ihr diesen Mann gesehen, wie er heraufkommt? Denn er kommt nur herauf, um Israel zu verhöhnen. Und es soll geschehen, wer immer ihn erschlägt, den will der König sehr reich belohnen*. Und er will ihm seine Tochter geben* und will das Haus seines Vaters von Abgaben freimachen in Israel.", footnotes: ["w. mit großem Reichtum reich machen", "℘ Kap. 18,17; Jos 15,16"] },
      { number: 26, text: "Da sagte David zu den Männern, die bei ihm standen: Was soll mit dem Mann geschehen, der diesen Philister da erschlägt und die Schande von Israel abwendet? Wer ist denn dieser unbeschnittene* Philister da, der die Schlachtreihen des lebendigen Gottes* verhöhnt*?", footnotes: ["℘ Kap. 14,6", "℘ Jos 3,10; Dan 6,27", "℘ 2Chr 32,17; Jes 37,23; Dan 5,23"] },
      { number: 27, text: "Und das Volk antwortete ihm wie vorher*: So und so soll dem Mann geschehen, der ihn erschlägt.", footnotes: ["w. nach jenem Wort"] },
      { number: 28, text: "Und Eliab, sein ältester Bruder*, hörte zu, als er mit den Männern redete. Und der Zorn Eliabs entbrannte über David*, und er sagte: Warum bist du überhaupt hergekommen? Und wem hast du jene paar Schafe in der Wüste überlassen? Ich erkenne deine Vermessenheit wohl und die Bosheit deines Herzens; denn du bist ja nur hergekommen, um dem Kampf zuzusehen.", footnotes: ["℘ 2Chr 11,18", "℘ 1Mo 37,4"] },
      { number: 29, text: "Und David antwortete: Was habe ich denn getan? Ist es nicht der Mühe wert?" },
      { number: 30, text: "Und er wandte sich von ihm ab, einem andern zu, und wiederholte die Frage; und das Volk gab ihm dieselbe Antwort wie vorher*.", footnotes: ["w. gab ihm Antwort nach dem ersten Wort"] },
      { number: 31, text: "Und die Worte, die David geredet hatte, wurden bekannt. Und man meldete sie Saul*; und der ließ ihn holen.", footnotes: ["w. vor Saul"] },
      { number: 32, text: "Und David sagte zu Saul: Niemand lasse seinetwegen den Mut sinken*! Dein Knecht will hingehen und mit diesem Philister kämpfen.", footnotes: ["w. Es entfalle keinem das Herz seinetwegen\n℘ 5Mo 20,2.3"] },
      { number: 33, text: "Aber Saul sagte zu David: Du kannst nicht zu diesem Philister gehen, um mit ihm zu kämpfen. Denn du bist ein junger Mann, er aber ist ein Kriegsmann von seiner Jugend auf." },
      { number: 34, text: "Da sagte David zu Saul: Dein Knecht weidete die Schafe für seinen Vater. Wenn dann ein Löwe oder ein Bär kam und ein Schaf von der Herde wegtrug," },
      { number: 35, text: "so lief ich ihm nach und schlug auf ihn ein und entriss es seinem Rachen. Erhob er sich gegen mich, so ergriff ich ihn bei seinem Bart, schlug ihn und tötete ihn*.", footnotes: ["℘ Ri 14,5.6"] },
      { number: 36, text: "So hat dein Knecht den Löwen und den Bären erschlagen. Und diesem unbeschnittenen* Philister soll es genauso ergehen wie einem von ihnen, weil er die Schlachtreihen des lebendigen Gottes verhöhnt hat*!", footnotes: ["℘ 2Chr 32,17; Jes 37,23; Dan 5,23", "℘ 2Chr 32,17; Jes 37,23; Dan 5,23"] },
      { number: 37, text: "Und David fuhr fort: Der HERR, der mich aus den Klauen* des Löwen und aus den Klauen* des Bären gerettet hat, der wird mich auch aus der Hand dieses Philisters retten*. Und Saul sagte zu David: Geh hin, der HERR sei mit dir!*", footnotes: ["w. aus der Hand", "w. aus der Hand", "℘ Ps 118,6; 2Kor 1,10", "℘ Kap. 20,13; Jos 1,17; Rt 2,4"] },
      { number: 38, text: "Und Saul legte David seine Rüstung an und setzte einen bronzenen Helm auf sein Haupt und zog ihm einen Schuppenpanzer an." },
      { number: 39, text: "Und David gürtete Sauls* Schwert über seine Rüstung und wollte damit gehen, denn er hatte es noch nie versucht. Da sagte David zu Saul: Ich kann nicht damit gehen, denn ich habe es nie versucht. Und David legte sie wieder ab*.", footnotes: ["w. sein", "w. von sich"] },
      { number: 40, text: "Und er nahm seinen Stab in seine Hand und wählte fünf glatte Steine aus dem Bach* und tat sie in die Hirtentasche, die ihm als Schleudertasche diente, und nahm seine Schleuder in seine Hand und ging dem Philister entgegen.", footnotes: ["o. Tal; d. i. ein trockenes Bachbett"] },
      { number: 41, text: "Und der Philister ging und kam David immer näher, und der Mann, der den Schild trug, ging vor ihm her." },
      { number: 42, text: "Als aber der Philister hinschaute und David sah, verachtete er ihn*, weil er noch jung war, und er war rötlich* und schön von Aussehen*.", footnotes: ["℘ Ps 123,4", "o. braun; d. i. wie die rotbraune Erde", "℘ Kap. 16,12.18"] },
      { number: 43, text: "Und der Philister sprach zu David: Bin ich denn ein Hund*, dass du mit Stöcken zu mir kommst? Und der Philister fluchte David bei seinen Göttern.", footnotes: ["℘ Kap. 24,15; 2Sam 3,8; 2Kö 8,13"] },
      { number: 44, text: "Der Philister sagte zu David: Komm her zu mir, dass ich dein Fleisch den Vögeln des Himmels und den Tieren des Feldes gebe!" },
      { number: 45, text: "Und David antwortete dem Philister: Du kommst zu mir mit Schwert, Lanze und Kurzschwert. Ich aber komme zu dir mit dem Namen des HERRN der Heerscharen, des Gottes der Schlachtreihen Israels*, den du verhöhnt hast.", footnotes: ["℘ 2Chr 14,10; Ps 20,8; Spr 18,10; Hebr 11,32"] },
      { number: 46, text: "Heute wird der HERR dich in meine Hand ausliefern, und ich werde dich erschlagen und dir den Kopf abhauen. Und die Leichen* des Heeres der Philister werde ich heute noch den Vögeln des Himmels und den wilden Tieren der Erde geben*. Und die ganze Erde soll erkennen, dass Israel einen Gott hat*.", footnotes: ["LXX: Und deine Leichen und die Leichen", "℘ 1Mo 40,19; 5Mo 28,26; Jer 19,7", "℘ Jos 4,24; 1Kö 18,36.37; 2Kö 5,15"] },
      { number: 47, text: "Und diese ganze Versammlung soll erkennen, dass der HERR nicht durch Schwert oder Speer rettet*. Denn des HERRN ist der Kampf*, und er wird euch in unsere Hand geben!*", footnotes: ["℘ Ps 44,7.8", "℘ 2Chr 20,15", "℘ Jos 10,8"] },
      { number: 48, text: "Und es geschah, als der Philister sich aufmachte und näher an David herankam, da lief David eilends von der Schlachtreihe aus dem Philister entgegen." },
      { number: 49, text: "Und David griff mit seiner Hand in die Tasche und nahm einen Stein heraus, und er schleuderte und traf den Philister an seine Stirn. Und der Stein drang ihm in die Stirn ein, und er fiel auf sein Gesicht zur Erde." },
      { number: 50, text: "So überwand David mit der Schleuder und mit dem Stein den Philister, und er traf den Philister und tötete ihn. David aber hatte kein Schwert in der Hand*.", footnotes: ["℘ Ri 3,31"] },
      { number: 51, text: "Und David lief und trat zu dem Philister und nahm dessen Schwert, zog es aus seiner Scheide und tötete ihn vollends und hieb ihm den Kopf damit ab*. Als aber die Philister sahen, dass ihr stärkster Mann* tot war, flohen sie*.", footnotes: ["℘ Kap. 21,10; 31,9; 2Sam 4,7; 23,21", "w. ihr Held, o. ihr Starker", "℘ Hebr 11,34"] },
      { number: 52, text: "Und die Männer von Israel und Juda machten sich auf und erhoben das Kriegsgeschrei und jagten den Philistern nach bis zum Eingang von Gat* und bis an die Tore von Ekron. Und die Erschlagenen der Philister fielen auf dem Weg von Schaarajim* bis Gat und Ekron*.", footnotes: ["so mit LXX; Mas. T.: bis zum Eingang des Tales", "℘ Jos 15,36", "℘ Kap. 5,10"] },
      { number: 53, text: "Und die Söhne Israel kehrten von der Verfolgung der Philister zurück und plünderten deren Lager*.", footnotes: ["℘ Kap. 19,5; 2Sam 23,10; Jer 30,16"] },
      { number: 54, text: "Und David nahm den Kopf des Philisters und brachte ihn nach Jerusalem; seine Waffen aber legte er in sein Zelt." },
      { number: 55, text: "Als aber Saul sah, wie David dem Philister entgegenging, sagte er zu Abner, dem Heerobersten*: Wessen Sohn ist doch dieser junge Mann, Abner? Und Abner antwortete: So wahr du lebst*, König, ich weiß es nicht*!", footnotes: ["℘ Kap. 14,50", "℘ Kap. 1,26", "w. So wahr deine Seele lebt, König, wenn ich es erkannt habe"] },
      { number: 56, text: "Und der König sagte: Frage, wessen Sohn der junge Mann ist!" },
      { number: 57, text: "Als David zurückkehrte, nachdem er den Philister erschlagen hatte, nahm ihn Abner und brachte ihn vor Saul; und er hatte den Kopf des Philisters in seiner Hand." },
      { number: 58, text: "Und Saul sagte zu ihm: Wessen Sohn bist du, junger Mann? David antwortete: Der Sohn deines Knechtes Isai, des Bethlehemiters*.", footnotes: ["℘ V. 12"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und es geschah, als er aufgehört hatte, mit Saul zu reden, verband sich die Seele Jonatans mit der Seele Davids*; und Jonatan gewann ihn lieb wie seine eigene Seele*.", heading: "Davids Freundschaft mit Jonatan — Sauls Eifersucht auf David", footnotes: ["℘ 1Mo 44,30; 2Sam 1,26", "℘ Kap. 19,1; 20,8.16.17; 22,8; 23,18; Spr 18,24"] },
      { number: 2, text: "Und Saul nahm ihn an jenem Tag zu sich und ließ ihn nicht wieder in das Haus seines Vaters zurückkehren." },
      { number: 3, text: "Und Jonatan und David schlossen einen Bund, weil er ihn lieb hatte wie seine eigene Seele*.", footnotes: ["℘ Kap. 19,1; 20,8.16.17; 22,8; 23,18; Spr 18,24"] },
      { number: 4, text: "Und Jonatan zog das Oberkleid aus, das er anhatte, und gab es David, und seinen Waffenrock und sogar sein Schwert, seinen Bogen und seinen Gürtel." },
      { number: 5, text: "Und David zog in den Kampf. Und wohin immer Saul ihn sandte, hatte er Erfolg*. Und Saul setzte ihn über die Kriegsleute. Und er war beliebt bei dem ganzen Volk und auch bei den Knechten Sauls*.", footnotes: ["℘ Kap. 3,19; 2Sam 5,10; Ri 1,19; 2Chr 17,3", "w. er war gut (wohlgefällig) in den Augen des ganzen Volkes und in den Augen der Knechte Sauls"] },
      { number: 6, text: "Und es geschah, als sie heimkamen, als David vom Sieg über den Philister zurückkehrte, zogen die Frauen aus allen Städten Israels zu Gesang und Reigen dem König Saul entgegen mit Tamburinen*, mit Jubel und mit Triangeln*.", footnotes: ["℘ 2Mo 15,20", "o. dreieckigen Harfen"] },
      { number: 7, text: "Und die Frauen tanzten, sangen und riefen: Saul hat seine Tausende erschlagen und David seine Zehntausende.*", footnotes: ["℘ Kap. 21,12; 29,5; 2Sam 23,1"] },
      { number: 8, text: "Da ergrimmte Saul sehr. Und diese Sache war in seinen Augen böse*, und er sagte: Sie haben David Zehntausende gegeben, und mir haben sie nur die Tausende gegeben; es fehlt ihm nur noch das Königtum*.", footnotes: ["℘ 1Mo 37,8.11", "℘ Kap. 15,28"] },
      { number: 9, text: "Und Saul sah neidisch auf David von jenem Tag an und hinfort*.", footnotes: ["℘ 1Mo 31,2; Spr 27,4; Pred 4,4"] },
      { number: 10, text: "Und es geschah am folgenden Tag, dass ein böser Geist von Gott über Saul kam*, und er geriet im Innern des Hauses in Raserei*. David aber spielte die Zither mit seiner Hand, wie er täglich zu tun pflegte*, und Saul hatte einen Speer in seiner Hand.", footnotes: ["℘ Kap. 16,14; Ri 16,20", "o. weissagte im Innern des Hauses; d. i. prophetisch reden. Das hebr. Wort kann eine bis zur Ekstase gesteigerte Begeisterung ausdrücken.", "℘ Kap. 16,23"] },
      { number: 11, text: "Und Saul warf* den Speer und dachte: Ich will David an die Wand spießen! Aber David wich ihm zweimal aus*.", footnotes: ["LXX: zückte", "℘ Kap. 19,9.10; 20,33"] },
      { number: 12, text: "Und Saul fürchtete sich vor David; denn der HERR war mit ihm*. Aber von Saul war er gewichen*.", footnotes: ["℘ Kap. 16,14; Ri 16,20", "℘ Kap. 16,14; Ri 16,20"] },
      { number: 13, text: "Und Saul entfernte David* aus seiner Umgebung und setzte ihn zum Obersten über Tausend; und er zog aus und ein vor dem Kriegsvolk her*.", footnotes: ["w. ihn bzw. er", "℘ 2Sam 5,2"] },
      { number: 14, text: "Und David hatte Erfolg auf allen seinen Wegen*, und der HERR war mit ihm*.", footnotes: ["℘ 2Kö 18,7; 1Chr 18,6.13", "℘ Kap. 3,19; 2Sam 5,10; Ri 1,19; 2Chr 17,3"] },
      { number: 15, text: "Und als Saul sah, dass David* so großen Erfolg hatte, scheute er sich vor ihm.", footnotes: ["w. ihn bzw. er"] },
      { number: 16, text: "Aber ganz Israel und Juda hatten David lieb*, denn er zog aus und ein vor ihnen her*.", footnotes: ["℘ Est 10,3", "℘ 2Sam 5,2"] },
      { number: 17, text: "Und Saul sagte zu David: Siehe, meine älteste Tochter Merab* will ich dir zur Frau geben*. Sei mir nur ein tapferer Mann und führe die Kriege des HERRN*! Saul aber dachte: Meine Hand soll nicht gegen ihn sein, sondern die Hand der Philister soll gegen ihn sein*.", footnotes: ["℘ Kap. 14,49; 2Sam 6,16.20", "℘ Kap. 17,25", "℘ Kap. 25,28", "℘ 2Sam 11,15; Spr 26,24-26"] },
      { number: 18, text: "Und David antwortete Saul: Wer bin ich*, und was ist meine Familie und die Sippe meines Vaters in Israel*, dass ich des Königs Schwiegersohn werden soll?", footnotes: ["℘ 2Sam 7,18", "℘ Kap. 9,21"] },
      { number: 19, text: "Und es geschah zu der Zeit, als Merab, die Tochter Sauls, David gegeben werden sollte, wurde sie Adriël, dem Meholatiter*, zur Frau gegeben*.", footnotes: ["℘ 1Kö 4,12", "℘ Ri 14,20; 2Sam 21,8"] },
      { number: 20, text: "Aber Michal*, die Tochter Sauls, liebte David. Das berichtete man Saul, und es war ihm recht*.", footnotes: ["℘ Kap. 14,49; 2Sam 6,16.20", "w. die Sache war recht in seinen Augen"] },
      { number: 21, text: "Und Saul sagte: Ich will sie ihm geben, damit sie ihm zur Falle* wird und die Hand der Philister gegen ihn ist. Und Saul sagte zu David: Zum zweiten Mal sollst du heute mein Schwiegersohn werden*.", footnotes: ["w. zum Stellholz eines Vogelfängers", "o. Und Saul sprach zu David ein zweites Mal: Du sollst mein Schwiegersohn werden"] },
      { number: 22, text: "Und Saul befahl seinen Knechten: Redet im Geheimen zu David und sagt: Siehe, der König hat Gefallen an dir, und alle seine Knechte haben dich lieb. So werde nun des Königs Schwiegersohn!" },
      { number: 23, text: "Und die Knechte Sauls redeten diese Worte vor den Ohren Davids*. David aber sagte: Ist es ein Geringes in euren Augen, des Königs Schwiegersohn zu werden? Ich bin nur ein armer und geringer Mann*.", footnotes: ["℘ Spr 29,5", "℘ Kap. 9,21"] },
      { number: 24, text: "Und die Knechte Sauls berichteten es ihm und sagten: So* hat David geredet.", footnotes: ["w. Nach diesen Worten"] },
      { number: 25, text: "Da sagte Saul: So sollt ihr zu David sagen: Der König fordert keine andere Heiratsgabe* als hundert Vorhäute der Philister, um an den Feinden des Königs Vergeltung zu üben*. Saul aber gedachte, David durch die Hand der Philister zu Fall zu bringen*.", footnotes: ["℘ 1Mo 34,12", "℘ Kap. 14,24", "℘ Kap. 19,1"] },
      { number: 26, text: "Und seine Knechte berichteten David diese Worte, und es war in den Augen Davids recht, des Königs Schwiegersohn zu werden. Und noch waren die Tage nicht vollendet," },
      { number: 27, text: "da machte sich David auf und zog hin, er und seine Männer, und erschlug zweihundert Mann unter den Philistern. Und David brachte ihre Vorhäute, und man lieferte sie dem König vollzählig ab, damit er des Königs Schwiegersohn werde. Da gab Saul ihm seine Tochter Michal* zur Frau.", footnotes: ["℘ 2Sam 3,13.14"] },
      { number: 28, text: "Und Saul sah und erkannte, dass der HERR mit David war*, dass Michal, die Tochter Sauls, ihn liebte.", footnotes: ["℘ 1Mo 26,28"] },
      { number: 29, text: "Da fürchtete Saul sich noch mehr vor David. Und Saul wurde *für immer* Davids Feind.", footnotes: ["w. alle Tage", "w. alle Tage"] },
      { number: 30, text: "Die Obersten der Philister zogen aus. Und es geschah, sooft sie auszogen, hatte David mehr Erfolg als alle Knechte Sauls. Und sein Name wurde sehr berühmt*.", footnotes: ["℘ Kap. 19,8; 2Sam 7,9"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Saul nun redete mit seinem Sohn Jonatan und mit all seinen Knechten, dass er David töten wolle*. Jonatan aber, der Sohn Sauls, hatte großen Gefallen an David*.", heading: "Sauls Hass auf David — Jonatans Eintreten für David", footnotes: ["℘ Kap. 18,25.29; 20,1; 1Mo 37,18; 2Sam 4,8", "℘ Kap. 18,1"] },
      { number: 2, text: "Und Jonatan berichtete es David und sagte: Mein Vater Saul sucht dich zu töten. Nun hüte dich doch morgen und bleibe im Versteck sitzen und verbirg dich*!", footnotes: ["℘ Kap. 20,5.24"] },
      { number: 3, text: "Ich aber will hinausgehen und mich auf dem Feld neben meinen Vater stellen, wo du bist, und ich will mit meinem Vater über dich reden und sehen, wie es steht, und es dir berichten*.", footnotes: ["℘ Kap. 20,9.13.19; Spr 17,17"] },
      { number: 4, text: "Und Jonatan redete mit seinem Vater Saul Gutes von David und sagte zu ihm: Der König versündige sich nicht an seinem Knecht, an David*! Denn er hat sich nicht an dir versündigt, und seine Taten sind dir sehr nützlich*.", footnotes: ["℘ 1Mo 42,22", "℘ Ps 59,4; Phim 11"] },
      { number: 5, text: "Er hat sein Leben aufs Spiel gesetzt* und den Philister erschlagen, und der HERR hat ganz Israel einen großen Sieg* verschafft*. Du hast es gesehen und dich darüber gefreut. Warum willst du dich an unschuldigem Blut versündigen, dass du David ohne Ursache tötest*?", footnotes: ["℘ Kap. 22,14; Ri 12,3", "o. Rettung", "℘ Kap. 11,13; 17,49-53", "℘ Kap. 20,32; Ps 109,5"] },
      { number: 6, text: "Und Saul hörte auf die Stimme Jonatans*, und Saul schwor: So wahr der HERR lebt, wenn er getötet wird!", footnotes: ["℘ Spr 31,8.9"] },
      { number: 7, text: "Da rief Jonatan David, und Jonatan berichtete ihm alle diese Worte. Und Jonatan brachte David zu Saul, und er diente ihm wie früher*.", footnotes: ["℘ Kap. 18,2"] },
      { number: 8, text: "Und es kam wieder zum Krieg. David zog aus und kämpfte gegen die Philister und brachte ihnen eine große Niederlage bei, so dass sie vor ihm flohen*.", heading: "Erneuter Mordversuch Sauls an David — Davids Flucht zu Samuel", footnotes: ["℘ Kap. 18,14.30; 23,5; 1Kö 20,21"] },
      { number: 9, text: "Und ein böser Geist von dem HERRN kam über Saul*, als er in seinem Haus saß, seinen Speer in seiner Hand*. David aber spielte auf der Zither*.", footnotes: ["℘ Kap. 16,14", "℘ Kap. 22,6", "w. spielte mit der Hand"] },
      { number: 10, text: "Und Saul suchte David mit dem Speer an die Wand zu spießen. Aber er wich aus vor Saul, so dass er den Speer in die Wand stieß*. Und David floh und entrann in jener Nacht*.", footnotes: ["℘ Kap. 18,10.11; Ps 37,32", "℘ Joh 10,33.39"] },
      { number: 11, text: "Da sandte Saul Boten in das Haus Davids, um ihn zu bewachen und ihn dann am Morgen zu töten*. Aber seine Frau Michal teilte es David mit: Wenn du nicht in dieser Nacht dein Leben rettest, dann wirst du morgen umgebracht werden.", footnotes: ["℘ Kap. 20,31; Ri 16,2; Ps 59,1"] },
      { number: 12, text: "Und Michal ließ David durchs Fenster hinab*. Und er eilte fort, floh und entrann.", footnotes: ["℘ Jos 2,15"] },
      { number: 13, text: "Und Michal nahm den Terafim* und legte ihn aufs Bett und legte ein Geflecht von Ziegenhaar* an sein Kopfende und bedeckte ihn mit einem Tuch*.", footnotes: ["d. h. den Hausgötzen\n℘ 1Mo 31,19; Ri 17,5", "d. i. ein Schutz gegen Mücken", "o. mit der Decke"] },
      { number: 14, text: "Und Saul sandte Boten, um David zu holen. Und sie sagte: Er ist krank*.", footnotes: ["℘ Jos 2,5"] },
      { number: 15, text: "Da sandte Saul noch einmal Boten, nach David zu sehen, und sagte: Bringt ihn im Bett zu mir herauf, damit ich ihn töte!" },
      { number: 16, text: "Und die Boten kamen, und siehe, der Terafim* lag im Bett, und das Geflecht von Ziegenhaar an seinem Kopfende.", footnotes: ["d. h. den Hausgötzen"] },
      { number: 17, text: "Da sagte Saul zu Michal: Warum hast du mich so betrogen und meinen Feind entfliehen lassen, dass er entrinnen konnte? Und Michal antwortete Saul: Er sagte zu mir: Lass mich gehen, sonst töte ich dich!*", footnotes: ["w. warum sollte ich dich töten?"] },
      { number: 18, text: "David aber war geflohen und hatte sich gerettet*. Und er kam zu Samuel nach Rama und berichtete ihm alles, was Saul ihm angetan hatte. Dann ging er mit Samuel, und sie wohnten in Najot*.", footnotes: ["℘ Kap. 21,11", "℘ Kap. 1,19; 20,1"] },
      { number: 19, text: "Und es wurde Saul berichtet: Siehe, David ist in Najot* in Rama.", footnotes: ["d. h. Wohnungen; vielleicht die Wohnungen der Prophetenschüler; vgl. V. 20"] },
      { number: 20, text: "Da sandte Saul Boten, um David zu holen. Als sie aber die Schar* der Propheten, die weissagten*, sahen und Samuel dabeistehen, wie er sie leitete, kam der Geist Gottes über die Boten Sauls, und auch sie weissagten*.", footnotes: ["so mit LXX, syr. und aram. Üs. Das hebr. Wort bedeutet so viel wie »ehrwürdige Gesellschaft«.", "d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung", "d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung\n℘ Kap. 10,5.6; 4Mo 11,25"] },
      { number: 21, text: "Und man berichtete es Saul, und er sandte andere Boten, und auch die weissagten*. Und Saul sandte zum dritten Mal Boten, und auch sie weissagten*.", footnotes: ["d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung", "d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung"] },
      { number: 22, text: "Da ging auch er nach Rama und kam an die große Zisterne, die in Sechu ist. Und er fragte: Wo sind Samuel und David? Man antwortete ihm: Siehe, in Najot in Rama." },
      { number: 23, text: "Und er ging von dort* nach Najot in Rama. Und auch über ihn kam der Geist Gottes, und er ging daher und weissagte*, bis er in Najot in Rama ankam.", footnotes: ["so mit LXX", "d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung"] },
      { number: 24, text: "Und auch er zog seine Oberkleider aus, und auch er weissagte* vor Samuel, und er fiel hin und lag nackt da* den ganzen Tag und die ganze Nacht. Daher sagt man: Ist auch Saul unter den Propheten*?*", footnotes: ["d. i. hier prophetische Ergriffenheit o. prophetische Begeisterung", "℘ Jes 20,2", "o. unter den prophetisch Ergriffenen", "℘ Kap. 10,10.11"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und David floh von Najot in Rama*. Und er kam und sagte vor Jonatan: Was habe ich getan? Was ist meine Schuld, und was ist mein Vergehen* gegen deinen Vater, dass er mir nach dem Leben trachtet*?", heading: "David und Jonatan — Sauls bleibende Mordabsichten — Davids endgültige Flucht", footnotes: ["℘ Kap. 19,18", "w. Sünde", "℘ V. 32; Kap. 19,1; 24,12; 26,18"] },
      { number: 2, text: "Und er antwortete ihm: Das sei ferne*! Du sollst nicht sterben. Siehe, mein Vater tut nichts, weder Großes noch Kleines, ohne dass er mir etwas davon sagt*. Warum sollte mein Vater diese Sache vor mir verbergen? Es ist nicht so.", footnotes: ["w. Das sei etwas Entweihtes", "w. weder eine große Sache noch eine kleine Sache, ohne dass er mein Ohr öffnet"] },
      { number: 3, text: "David aber schwor dazu und sprach: Dein Vater hat wohl erkannt, dass ich Gunst in deinen Augen gefunden habe, darum denkt er: Jonatan soll das nicht erkennen, damit er nicht bekümmert ist. Jedoch, so wahr der HERR lebt und so wahr du lebst*: Nur ein Schritt ist zwischen mir und dem Tod*!", footnotes: ["℘ Kap. 1,26; Jer 4,2", "℘ Kap. 27,1; 2Kor 1,9.10"] },
      { number: 4, text: "Und Jonatan sagte zu David: Was du begehrst, das will ich für dich tun*.", footnotes: ["o. Was begehrst du? Das will ich dir tun"] },
      { number: 5, text: "Und David entgegnete Jonatan: Siehe, morgen ist Neumond*, da sollte ich eigentlich mit dem König zu Tisch sitzen. Lass mich gehen, dass ich mich auf dem Feld verberge bis zum Abend des dritten Tages*!", footnotes: ["℘ V. 18.24; 4Mo 10,10; 2Kö 4,23", "w. bis zum dritten Abend. — Andere üs. mit Textänderung: bis zum Abend; o. ein drittes Mal verbergen bis zum Abend\n℘ Kap. 19,2"] },
      { number: 6, text: "Wenn dein Vater mich dann vermissen sollte, so sage: David hat es sich dringend von mir erbeten, nach Bethlehem, seiner Stadt*, laufen zu dürfen; denn dort ist das Jahresopfer* für die ganze Familie*.*", footnotes: ["℘ Lk 2,4", "w. Schlachtopfer der Tage", "o. Sippe", "℘ Kap. 9,12"] },
      { number: 7, text: "Wenn er dann sagt: »Es ist recht«, so steht es gut um deinen Knecht. Ergrimmt er aber, so erkenne, dass Böses bei ihm beschlossen ist." },
      { number: 8, text: "Erweise denn nun Gnade an deinem Knecht, denn du hast mich mit dir in den Bund des HERRN treten lassen*! Wenn aber eine Schuld bei mir vorliegt, so töte du mich*! Denn warum willst du mich zu deinem Vater bringen?", footnotes: ["℘ Kap. 18,3", "℘ 2Sam 14,32"] },
      { number: 9, text: "Jonatan antwortete: Das sei fern von dir*! Denn wenn ich sicher erkannt habe, dass es bei meinem Vater beschlossen ist, Böses über dich zu bringen*, sollte ich es dir dann nicht berichten*?", footnotes: ["w. Das sei dir etwas Entweihtes", "w. Böses (o. Unheil) soll über dich kommen", "℘ Kap. 19,3"] },
      { number: 10, text: "Und David sagte zu Jonatan: Wer soll es mir berichten, wenn dein Vater dir eine harte Antwort gibt?" },
      { number: 11, text: "Jonatan sagte zu David: Komm, lass uns aufs Feld hinausgehen! Und sie gingen beide hinaus aufs Feld." },
      { number: 12, text: "Und Jonatan sagte zu David: Der HERR, der Gott Israels, ist Zeuge, dass ich meinen Vater morgen oder übermorgen um diese Zeit* ausforsche. Und siehe, steht es gut um David, und ich sende dann nicht zu dir und enthülle es deinem Ohr*,", footnotes: ["w. um diese Zeit morgen oder am dritten Tag", "o. Beim HERRN, dem Gott Israels: Wenn ich meinen Vater morgen oder übermorgen um diese Zeit ausforsche: »Sicher steht es gut um David?«, und ich es dann nicht zu dir sende und es deinem Ohr enthülle"] },
      { number: 13, text: "dann tue der HERR dem Jonatan das an und füge so hinzu*! Wenn es aber meinem Vater gefällt, Böses über dich zu bringen, dann werde ich es deinem Ohr enthüllen und dich ziehen lassen, dass du in Frieden weggehen kannst. Und der HERR sei mit dir*, wie er mit meinem Vater gewesen ist*!", footnotes: ["d. i. eine Schwurformel\n℘ Kap. 3,17", "℘ Kap. 17,37; 1Chr 22,11.16", "℘ Kap. 10,7"] },
      { number: 14, text: "Und nicht nur solange ich noch lebe, und nicht nur an mir erweise die Gnade des HERRN, dass ich nicht sterbe," },
      { number: 15, text: "sondern auch meinem Haus entziehe niemals deine Gnade, auch dann nicht, wenn der HERR die Feinde Davids Mann für Mann vom Erdboden vertilgen wird*!", footnotes: ["℘ 1Mo 40,14; 2Sam 9,1-7"] },
      { number: 16, text: "Da schloss Jonatan mit dem Haus Davids einen Bund und sprach: Der HERR fordere es von der Hand der Feinde Davids*!", footnotes: ["℘ Kap. 25,26.29; Jos 22,23"] },
      { number: 17, text: "Und Jonatan ließ nun auch David bei seiner Liebe zu ihm schwören*. Denn er liebte ihn, wie er seine eigene Seele* liebte.*", footnotes: ["℘ Kap. 24,23", "o. sein Leben", "℘ Kap. 18,1.3; Spr 17,17"] },
      { number: 18, text: "Und Jonatan sagte zu ihm: Morgen ist Neumond. Da wird man dich vermissen, wenn dein Platz leer bleibt." },
      { number: 19, text: "Am dritten Tag aber steig schnell herunter! Du aber komm an den Ort, wo du dich am Tag der Tat* verborgen hattest, und setz dich neben den Steinhaufen*!", footnotes: ["℘ Kap. 19,1-3", "o. Stein Asel"] },
      { number: 20, text: "Ich aber werde drei Pfeile nach seiner Seite abschießen, als ob ich nach einem Ziel schießen würde." },
      { number: 21, text: "Und siehe, ich werde den Jungen hinschicken: Geh hin, such die Pfeile! Wenn ich ausdrücklich zu dem Jungen sage: Siehe, die Pfeile sind von dir herwärts, hole sie! — so komm! Denn es steht gut um dich, und es besteht keine Gefahr*, so wahr der HERR lebt.", footnotes: ["w. es liegt nichts vor"] },
      { number: 22, text: "Wenn ich aber so zu dem jungen Mann sage: Siehe, die Pfeile sind von dir hinwärts! — so geh! Denn der HERR schickt dich weg." },
      { number: 23, text: "Das Wort aber, das wir miteinander geredet haben, ich und du, siehe, der HERR ist Zeuge zwischen mir und dir auf ewig.*", footnotes: ["℘ V. 42"] },
      { number: 24, text: "Und David verbarg sich auf dem Feld. Und als es Neumond wurde, setzte sich der König zu Tisch, um zu essen." },
      { number: 25, text: "Und der König setzte sich auf seinen Platz wie vorher*, auf den Platz an der Wand. Als nun Jonatan sich erhob, saß nur noch Abner an der Seite Sauls*. Der Platz Davids blieb leer.", footnotes: ["w. wie das eine Mal so das andere Mal", "LXX: Und Jonatan saß ihm gegenüber, und Abner setzte sich an die Seite Sauls"] },
      { number: 26, text: "Saul aber sagte nichts an diesem Tag, denn er dachte: Es ist ihm etwas widerfahren. Er ist nicht rein, gewiss, er ist nicht rein*.", footnotes: ["℘ 3Mo 7,20"] },
      { number: 27, text: "Und es geschah am anderen Tag des Neumonds, dem zweiten, als der Platz Davids wieder leer blieb, da sagte Saul zu seinem Sohn Jonatan: Warum ist der Sohn Isais gestern und heute nicht zum Essen gekommen?" },
      { number: 28, text: "Jonatan antwortete Saul: David hat es sich dringend von mir erbeten, nach Bethlehem gehen zu dürfen," },
      { number: 29, text: "und sagte: Lass mich doch gehen! Denn wir haben ein Familienopfer* in der Stadt, und mein Bruder selbst hat es mir geboten. Und nun, wenn ich Gunst in deinen Augen gefunden habe, so lass mich doch gehen*, dass ich meine Brüder sehe! Darum ist er nicht an den Tisch des Königs gekommen.", footnotes: ["w. ein Schlachtopfer der Sippe\n℘ Kap. 16,2", "w. entschlüpfen"] },
      { number: 30, text: "Da entbrannte der Zorn Sauls über Jonatan, und er sagte zu ihm: Du Sohn einer entarteten Mutter*! Ich habe wohl erkannt, dass du den Sohn Isais erkoren hast, dir und deiner Mutter, die dich geboren hat, zur Schande*.", footnotes: ["w. Sohn verkehrter Zucht, o. gekrümmter Widerspenstigkeit. — LXX: Sohn widerspenstiger Mädchen", "w. zur Schande der Blöße deiner Mutter"] },
      { number: 31, text: "Denn all die Tage, die der Sohn Isais auf Erden lebt, wirst weder du noch deine Königsherrschaft Bestand haben. Und nun schicke hin und lass ihn zu mir bringen, denn er ist ein Kind des Todes*!", footnotes: ["℘ Kap. 19,11"] },
      { number: 32, text: "Und Jonatan antwortete seinem Vater Saul und sprach zu ihm: Warum soll er sterben? Was hat er getan?*", footnotes: ["℘ V. 1; Kap. 19,5.6; Mt 27,23"] },
      { number: 33, text: "Da schleuderte* Saul den Speer nach ihm, um ihn zu durchbohren*. Und Jonatan erkannte, dass es bei seinem Vater fest beschlossen war, David zu töten*.", footnotes: ["LXX: zückte", "℘ Kap. 18,11", "℘ 1Kö 11,40"] },
      { number: 34, text: "Jonatan stand vom Tisch in glühendem Zorn auf und aß am zweiten Tag des Neumonds keine Speise. Denn er war bekümmert um David, weil sein Vater ihn* beschimpft hatte*.", footnotes: ["d. i. David", "o. Schmach angetan hatte"] },
      { number: 35, text: "Und es geschah am Morgen, da ging Jonatan aufs Feld hinaus, an den Ort, den er mit David verabredet hatte; und ein kleiner Junge* war mit ihm.", footnotes: ["o. ein junger Knecht"] },
      { number: 36, text: "Und er sagte zu seinem Jungen: Lauf und such die Pfeile, die ich abschieße! Während der Junge hinlief, schoss er den Pfeil über ihn hinaus." },
      { number: 37, text: "Und als der Junge an die Stelle kam, wohin Jonatan den Pfeil abgeschossen hatte, rief Jonatan dem Jungen nach und sprach: Liegt der Pfeil nicht noch jenseits von dir?" },
      { number: 38, text: "Und Jonatan rief hinter dem Jungen her: Schnell, eile und bleib nicht stehen! Und der Junge Jonatans hob den Pfeil auf und brachte ihn* zu seinem Herrn.", footnotes: ["so mit LXX, syr. und lat. Üs.; Mas. T.: kam"] },
      { number: 39, text: "Der Junge aber wusste von nichts; nur Jonatan und David wussten um die Sache." },
      { number: 40, text: "Und Jonatan gab dem Jungen, den er bei sich hatte, seine Waffen und sagte zu ihm: Geh, bring sie in die Stadt!" },
      { number: 41, text: "Als der Junge weggegangen war, stand David hinter dem Steinhaufen* auf und fiel auf sein Gesicht zur Erde und beugte sich dreimal nieder*. Und sie küssten einander und weinten miteinander*, David aber am allermeisten*.", footnotes: ["so mit LXX; Mas. T.: von der Südseite", "℘ Kap. 24,9; 1Mo 42,6; 2Sam 1,2; 1Kö 1,16.23", "℘ 1Mo 33,4; Apg 20,37", "w. bis David sein Weinen groß machte. — Der Schluss von V. 41 lässt sich auch mit V. 42 verbinden: Noch weinte David heftig, 42 da sagte Jonatan"] },
      { number: 42, text: "Und Jonatan sagte zu David: Geh hin in Frieden!* Was wir beide im Namen des HERRN geschworen haben, dafür wird der HERR zwischen mir und dir und zwischen meinen Nachkommen und deinen Nachkommen* auf ewig Zeuge sein.*", footnotes: ["℘ Kap. 1,17", "w. zwischen meinem Samen und deinem Samen", "o. geschworen haben: Der HERR sei zwischen dir und mir . . ., das gilt für ewig!\n℘ V. 23; Kap. 24,23"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und David* machte sich auf und ging weg. Jonatan aber ging zurück in die Stadt*.", footnotes: ["w. er", "℘ Kap. 23,18"] },
      { number: 2, text: "Und David kam nach Nob*, zum Priester Ahimelech. Und Ahimelech kam David aufgeregt entgegen und sagte zu ihm: Warum kommst du allein, und niemand ist bei dir?", heading: "Hilfe für David bei den Priestern von Nob", footnotes: ["℘ Kap. 22,9.19; Neh 11,32; Jes 10,32"] },
      { number: 3, text: "Und David antwortete dem Priester Ahimelech: Der König hat mir eine Sache geboten und sagte zu mir: Niemand soll irgendetwas von der Sache wissen, in der ich dich sende und die ich dir geboten habe. Die Leute* aber habe ich an den und den Ort beschieden.", footnotes: ["w. Knechte, o. Knaben"] },
      { number: 4, text: "Und nun, was hast du zur Hand? Gib mir fünf Brote in meine Hand oder was sich sonst vorfindet!" },
      { number: 5, text: "Und der Priester antwortete David und sagte: Ich habe kein gewöhnliches Brot zur Hand, sondern nur heiliges Brot ist da*. Wenn sich nur die Leute* der Frau enthalten haben*!", footnotes: ["℘ 2Mo 25,30", "w. Knechte, o. Knaben", "℘ 2Mo 19,15"] },
      { number: 6, text: "David antwortete dem Priester und sagte zu ihm: *Ja, denn eine Frau ist uns seit gestern und vorgestern, als ich auszog, versagt gewesen. Und die Leiber* der Leute* sind heilig. War das noch ein gewöhnliches Unternehmen, wie viel mehr werden sie heute an ihrem Leib* heilig sein!*", footnotes: ["o. Ja, denn eine Frau ist uns schon seit gestern und vorgestern versagt. Als ich auszog, da waren die Leiber der Leute heilig. Ist dies nun auch ein gewöhnliches Unternehmen, so ist es doch heute durch die Leiber geheiligt.", "o. Kleider; o. Waffen; w. Gefäße", "w. Knechte, o. Knaben", "o. an der Kleidung; o. an der Waffe; w. am Gefäß", "o. an der Kleidung; o. an der Waffe; w. am Gefäß"] },
      { number: 7, text: "Da gab ihm der Priester von dem heiligen Brot*. Denn dort war kein anderes Brot als nur das Schaubrot, das vor dem HERRN nur weggenommen wird*, wenn frisches Brot hingelegt wird an dem Tag, da man es wegnimmt*.", footnotes: ["w. gab ihm der Priester Heiliges\n℘ Kap. 22,10; Mt 12,3.4", "w. die . . . weggenommen werden", "℘ 3Mo 22,10; 24,5-9"] },
      { number: 8, text: "— Es war aber dort an jenem Tag ein Mann von den Knechten Sauls, eingeschlossen vor dem HERRN, mit Namen Doëg*, der Edomiter; er war Aufseher über die Hirten Sauls. —", footnotes: ["℘ Kap. 22,9.22"] },
      { number: 9, text: "Und David sagte zu Ahimelech: Ist nicht hier unter deiner Hand ein Speer oder ein Schwert? Denn ich habe mein Schwert und meine Waffen nicht mit mir genommen*, weil die Sache* des Königs dringend war.", footnotes: ["w. in meine Hand genommen", "o. der Befehl"] },
      { number: 10, text: "Und der Priester sagte: Das Schwert des Philisters Goliat, den du im Terebinthental erschlagen hast*, siehe, es ist in ein Oberkleid gewickelt hinter dem Efod*. Wenn du dir das nehmen willst, so nimm es! Denn außer diesem ist kein anderes da. Und David erwiderte: Seinesgleichen gibt es nicht. Gib es mir*!", footnotes: ["℘ Kap. 17,2.51.54", "d. i. ein Priesterschurz", "℘ Kap. 22,10"] },
      { number: 11, text: "Und David machte sich auf und floh an diesem Tag vor Saul* und kam zu Achisch, dem König von Gat*.", heading: "Davids Flucht nach Gat und nach Juda", footnotes: ["℘ Kap. 19,18", "℘ Kap. 27,1.2; Ps 56,1"] },
      { number: 12, text: "Und die Knechte des Achisch sagten zu ihm: Ist das nicht David, der König des Landes? Haben sie nicht von ihm bei Reigentänzen gesungen: Saul hat seine Tausende erschlagen, David aber seine Zehntausende?*", footnotes: ["℘ Kap. 18,7"] },
      { number: 13, text: "David nahm sich diese Worte zu Herzen und fürchtete sich sehr vor Achisch*, dem König von Gat.", footnotes: ["℘ Spr 29,25; Jes 51,12.13"] },
      { number: 14, text: "Und er stellte sich wahnsinnig vor ihren Augen und tobte* unter ihren Händen, und er kritzelte* an die Flügel des Tores und ließ seinen Speichel in seinen Bart fließen*.", footnotes: ["w. er verstellte seinen Verstand vor ihren Augen und tat unsinnig", "LXX: er trommelte", "℘ Ps 34,1"] },
      { number: 15, text: "Da sagte Achisch zu seinen Knechten: Siehe, ihr seht, dass der Mann wahnsinnig ist. Warum bringt ihr ihn zu mir?" },
      { number: 16, text: "Fehlt es mir an Wahnsinnigen*, dass ihr diesen hergebracht habt, bei mir zu toben? Sollte der in mein Haus kommen*?", footnotes: ["hebr. meschuggaim", "℘ Ps 34,1"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und David ging von dort weg und entkam in die Höhle Adullam*. Und als seine Brüder und das ganze Haus seines Vaters das hörten, kamen sie zu ihm dorthin herab.", footnotes: ["℘ Kap. 24,4; 1Mo 38,1; Jos 15,35; 2Sam 23,13; 1Chr 11,15; Ps 57,1"] },
      { number: 2, text: "Und es sammelten sich um ihn lauter Bedrängte* und solche, die verschuldet waren*, und andere mit erbittertem Gemüt*. Und er wurde ihr Anführer*. Und es waren bei ihm etwa vierhundert Mann*.", footnotes: ["w. jeder Mann der Bedrängnis", "w. jeder, der einen Gläubiger hatte", "o. mit grimmigem Gemüt; w. jeder Mann mit bitterer Seele", "℘ Ps 72,12-14", "℘ Kap. 23,13; 25,13; 30,24"] },
      { number: 3, text: "Und David ging von da nach Mizpe in Moab und sagte zum König von Moab: Lass doch meinen Vater und meine Mutter bei euch wohnen*, bis ich erkannt habe, was Gott mit mir tun wird*!", footnotes: ["so mit syr. und lat. Üs.; Mas. T.: mit euch ausziehen; o. hinausziehen und bei euch bleiben", "℘ 2Mo 20,12; Joh 19,27"] },
      { number: 4, text: "Und er brachte sie vor den König von Moab, und sie wohnten bei ihm, solange* David auf der Bergfeste war*.", footnotes: ["w. alle Tage, die", "℘ Kap. 24,23; 1Chr 11,16"] },
      { number: 5, text: "Und der Prophet Gad* sagte zu David: Bleib nicht auf der Bergfeste! Geh hin und begib dich in das Land Juda! Und David ging weg und kam nach Jaar-Heret*.", footnotes: ["℘ 2Sam 24,11; 1Chr 21,9", "d. h. in den Wald Heret"] },
      { number: 6, text: "Und Saul hörte, dass David und die Männer, die bei ihm waren, entdeckt* worden seien. Saul aber saß in Gibea* unter der Tamariske* auf der Höhe, seinen Speer in der Hand*, und alle seine Knechte standen bei ihm.", heading: "Sauls Rache an den Priestern von Nob", footnotes: ["w. erkannt", "℘ Kap. 14,2", "d. i. ein hoher, weit sichtbarer Baum", "℘ Kap. 19,9"] },
      { number: 7, text: "Da sagte Saul zu seinen Knechten, die um ihn standen: Hört doch, ihr Benjaminiter! Wird der Sohn Isais euch allen auch Felder und Weinberge geben, euch alle zu Anführern über Tausend und zu Anführern über Hundert machen*,", footnotes: ["℘ Kap. 8,11-14"] },
      { number: 8, text: "dass ihr euch alle gegen mich verschworen habt? Und da ist keiner, der es meinem Ohr eröffnet, dass mein Sohn einen Bund mit dem Sohn Isais geschlossen hat*, und keiner ist unter euch, der sich um mich grämt und es meinem Ohr eröffnet hätte, dass mein Sohn meinen Knecht als Verräter* gegen mich aufgewiegelt hat*, wie es heute offenkundig ist!", footnotes: ["℘ Kap. 18,3; 2Kö 6,11", "w. als einen, der im Hinterhalt lauert", "℘ Ps 34,1"] },
      { number: 9, text: "Da antwortete der Edomiter Doëg, der bei den Knechten Sauls stand*, und sagte: Ich sah den Sohn Isais, wie er nach Nob kam zu Ahimelech, dem Sohn Ahitubs*.", footnotes: ["℘ Kap. 21,8", "℘ Kap. 14,3; 21,2; Ps 52,1.2"] },
      { number: 10, text: "Der befragte den HERRN für ihn und gab ihm Verpflegung, und das Schwert des Philisters Goliat gab er ihm auch*.", footnotes: ["℘ Kap. 21,7.10"] },
      { number: 11, text: "Da sandte der König hin und ließ den Priester Ahimelech, den Sohn Ahitubs, rufen sowie das ganze Haus seines Vaters, alle Priester in Nob. Und sie kamen alle zum König." },
      { number: 12, text: "Und Saul sagte: Höre doch, Sohn Ahitubs! Er antwortete: Hier bin ich, mein Herr!" },
      { number: 13, text: "Und Saul sagte zu ihm: Warum habt ihr euch gegen mich verschworen, du und der Sohn Isais, dass du ihm Brot und ein Schwert gegeben und Gott für ihn befragt hast, damit er als Verräter an mir auftreten kann, wie es heute offenkundig ist?" },
      { number: 14, text: "Ahimelech antwortete dem König und sprach: Wer unter all deinen Knechten ist wie David: treu*, Schwiegersohn des Königs, dazu Anführer* deiner Leibwache und geehrt in deinem Haus?", footnotes: ["℘ Kap. 19,4.5", "so mit LXX; Mas. T.: und er hat Zutritt zu, o. kehrt ein bei"] },
      { number: 15, text: "Habe ich erst heute angefangen, Gott für ihn zu befragen? Das sei fern von mir*! Der König lege solches seinem Knecht nicht zur Last, auch nicht dem ganzen Haus meines Vaters! Denn dein Knecht hat von alldem nichts gewusst, weder Kleines noch Großes.", footnotes: ["w. Das sei mir etwas Entweihtes"] },
      { number: 16, text: "Aber der König sagte: Sterben musst du, Ahimelech, du und das ganze Haus deines Vaters*!", footnotes: ["℘ 5Mo 24,16"] },
      { number: 17, text: "Und der König sagte zu den Leibwächtern*, die um ihn standen: Tretet her* und tötet die Priester des HERRN, weil auch ihre Hand mit David ist und weil sie wussten*, dass er auf der Flucht war und es mir nicht zu Ohren gebracht haben. Aber die Knechte des Königs wollten ihre Hand nicht an die Priester des HERRN legen, um sie niederzumachen*.", footnotes: ["w. zu den Läufern", "o. Stellt euch um sie herum", "o. erkannt hatten", "w. um über sie herzufallen\n℘ 2Mo 1,17"] },
      { number: 18, text: "Da sprach der König zu Doëg: Tritt du heran und mache die Priester nieder*! Und Doëg, der Edomiter, trat heran, und er machte die Priester nieder, und er tötete an diesem Tag 85 Mann, die das leinene Efod* trugen*.", footnotes: ["w. und fall über die Priester her", "d. i. ein Priesterschurz", "℘ Kap. 2,33"] },
      { number: 19, text: "Und Nob, die Stadt der Priester, schlug er mit der Schärfe des Schwertes, Mann und Frau, Kind und Säugling, Rind und Esel und Schafe, mit der Schärfe des Schwertes*.", footnotes: ["℘ Kap. 15,3"] },
      { number: 20, text: "Und es entkam ein Sohn Ahimelechs, des Sohnes Ahitubs, mit Namen Abjatar*, und floh zu David*.", footnotes: ["℘ 2Sam 15,24; 1Kö 2,26; 1Chr 18,16", "w. David hinterher\n℘ Kap. 23,6"] },
      { number: 21, text: "Abjatar berichtete David, dass Saul die Priester des HERRN umgebracht habe." },
      { number: 22, text: "Da sagte David zu Abjatar: Ich wusste schon an jenem Tag, weil der Edomiter Doëg dort war, dass er es Saul sicher berichten würde*. Ich bin schuldig am Tod aller aus dem Haus* deines Vaters.", footnotes: ["℘ Kap. 21,8", "w. an allen Seelen des Hauses"] },
      { number: 23, text: "Bleibe bei mir, fürchte dich nicht!* Denn wer nach meinem Leben* trachtet, trachtet auch nach deinem. Bei mir bist du in Sicherheit*.", footnotes: ["℘ Kap. 23,17; 2Sam 9,7", "o. nach meiner Seele", "℘ Joh 17,12"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und man berichtete David: Siehe, die Philister kämpfen gegen Keïla* und plündern die Tennen.", heading: "David rettet Keïla — Seine Flucht in die Wüste Sif — Letzte Begegnung mit Jonatan", footnotes: ["℘ Jos 15,44; Neh 3,17.18"] },
      { number: 2, text: "Da befragte David den HERRN* und sagte: Soll ich hinziehen und diese Philister schlagen*? Und der HERR sprach zu David: Zieh hin und schlage die Philister und rette Keïla!", footnotes: ["℘ Kap. 10,22", "℘ Kap. 14,37"] },
      { number: 3, text: "Aber die Männer Davids sagten zu ihm: Siehe, wir fürchten uns schon hier in Juda, und wie sollten wir gar nach Keïla gegen die Schlachtreihen der Philister ziehen?" },
      { number: 4, text: "Da befragte David wieder den HERRN*, und der HERR antwortete ihm und sprach: Mach dich auf und zieh nach Keïla hinab! Denn ich will die Philister in deine Hand geben*.", footnotes: ["℘ Kap. 10,22", "℘ Kap. 30,8; Ri 7,9; 1Chr 14,10"] },
      { number: 5, text: "Und David zog mit seinen Männern nach Keïla und kämpfte gegen die Philister und trieb ihr Vieh weg und brachte ihnen eine große Niederlage bei*. Und so rettete David die Bewohner von Keïla. —", footnotes: ["℘ Kap. 19,8"] },
      { number: 6, text: "Es geschah aber, als Abjatar, der Sohn Ahimelechs, zu David nach Keïla floh*, kam er hinab mit einem Efod* in seiner Hand*.", footnotes: ["℘ Kap. 22,20", "d. i. ein Priesterschurz", "℘ 2Mo 28,6"] },
      { number: 7, text: "Und es wurde Saul berichtet, dass David nach Keïla gekommen sei. Da dachte Saul: Gott hat ihn verworfen und in meine Hand gegeben. Denn er hat sich selbst eingeschlossen*, indem er in eine Stadt mit Toren und Riegeln gekommen ist*.", footnotes: ["o. Gott hat ihn verworfen, in meine Hand hat er sich sogar eingeschlossen. — LXX u. aram. Üs.: Gott hat ihn in meine Hand verkauft, denn er . . .", "℘ Ps 71,11"] },
      { number: 8, text: "Und Saul rief alles Volk zum Kampf auf, um nach Keïla hinabzuziehen, damit sie David und seine Männer belagerten." },
      { number: 9, text: "Und als David erkannte, dass Saul Böses gegen ihn schmiedete, da sagte er zu dem Priester Abjatar: Bring das Efod* her*!", footnotes: ["d. i. ein Priesterschurz", "℘ Kap. 10,22"] },
      { number: 10, text: "Und David sprach: HERR, Gott Israels! Dein Knecht hat als gewiss gehört, dass Saul danach trachtet, nach Keïla zu kommen, um die Stadt meinetwegen zu verderben." },
      { number: 11, text: "Werden die Bürger von Keïla mich in seine Hand ausliefern? Wird Saul herabziehen, wie dein Knecht gehört hat? HERR, Gott Israels, lass es doch deinen Knecht wissen! Und der HERR sprach: Er wird herabkommen." },
      { number: 12, text: "Und David fragte weiter: Werden die Bürger* von Keïla mich und meine Männer in die Hand Sauls ausliefern*? Der HERR sprach: Sie werden dich ausliefern*.", footnotes: ["w. die Grundbesitzer", "℘ Ps 143,8", "℘ Jer 11,18"] },
      { number: 13, text: "Da machten David und seine Männer sich auf, etwa sechshundert Mann*, und sie zogen aus Keïla fort und streiften umher, von einem Ort zum anderen*. Und es wurde Saul berichtet, dass David aus Keïla entkommen sei. Da ließ er davon ab, gegen ihn auszuziehen*.", footnotes: ["℘ Kap. 22,2", "w. wo sie umherstreifen konnten", "℘ Hi 5,12; Ps 34,5"] },
      { number: 14, text: "Und David blieb in der Wüste auf den Bergfesten, und er blieb im Gebirge in der Wüste Sif*. Und Saul suchte ihn alle Tage, aber Gott gab ihn nicht in seine Hand*.", footnotes: ["℘ Jos 15,55", "℘ Ps 37,32.33"] },
      { number: 15, text: "Und David sah, dass Saul ausgezogen war, um ihm nach dem Leben zu trachten. Und David war in Horescha in der Wüste Sif." },
      { number: 16, text: "Da machte sich Jonatan, der Sohn Sauls, auf und ging zu David nach Horescha und stärkte seine Hand in Gott*.", footnotes: ["℘ Kap. 30,6; Eph 6,10"] },
      { number: 17, text: "Und er sagte zu ihm: Fürchte dich nicht!* Denn die Hand meines Vaters Saul wird dich nicht finden*. Du wirst König über Israel werden, und ich werde der Zweite nach dir sein. Und auch mein Vater Saul hat erkannt, dass es so ist*.", footnotes: ["℘ Kap. 22,23", "℘ Jes 35,3.4", "℘ Kap. 24,21; 25,30"] },
      { number: 18, text: "Und beide schlossen einen Bund vor dem HERRN*. David blieb in Horescha, Jonatan aber kehrte nach Hause zurück*.", footnotes: ["℘ Kap. 18,3; 20,16.42", "℘ Kap. 21,1"] },
      { number: 19, text: "Aber die Sifiter zogen zu Saul nach Gibea hinauf und sagten: Hält David sich nicht bei uns auf den Bergfesten verborgen, in Horescha, auf dem Hügel Hachila, der südlich* von Jeschimon liegt*?", heading: "Erneute Verfolgung Davids durch Saul — Davids Flucht in die Wüste Maon", footnotes: ["w. rechts", "℘ Kap. 26,1.3; Ps 54,1.2"] },
      { number: 20, text: "Und nun, König, wenn du geneigt bist herabzukommen, so komm herab*! Und an uns ist es, ihn in die Hand des Königs auszuliefern.", footnotes: ["w. Und nun gemäß allem Verlangen deiner Seele herabzukommen, o König, komm herab"] },
      { number: 21, text: "Und Saul entgegnete: Gesegnet seid ihr vom HERRN*, dass ihr Mitleid mit mir gehabt habt!", footnotes: ["w. Ihr seid dem HERRN gesegnet; d. i. eine Dankesformel\n℘ Kap. 15,13"] },
      { number: 22, text: "Geht hin, vergewissert euch noch mehr und erkundet* und passt genau auf, an welchem Ort sein Fuß weilt und wer ihn dort gesehen hat*! Denn man hat mir gesagt, dass er sehr listig ist.", footnotes: ["w. erkennt", "℘ 2Sam 17,9"] },
      { number: 23, text: "Und beobachtet und erkundet* alle Schlupfwinkel, in denen er sich versteckt hält, und kommt mit sicherer Kunde wieder zu mir zurück! So werde ich mit euch gehen. Und es soll geschehen, wenn er im Land ist, dann will ich ihn aufspüren unter allen Tausendschaften Judas*!", footnotes: ["w. erkennt", "℘ 1Kö 18,10; 2Kö 6,13"] },
      { number: 24, text: "Und sie machten sich auf und gingen vor Saul her nach Sif. David aber und seine Männer waren in der Wüste Maon*, in der Steppe, südlich* von Jeschimon.", footnotes: ["℘ Kap. 25,2; Jos 15,55", "w. rechts"] },
      { number: 25, text: "Saul und seine Männer zogen hin, um ihn zu suchen. Und man berichtete es David, und er ging zum Felsen* hinab und blieb in der Wüste Maon. Als Saul das hörte, jagte er David nach in die Wüste Maon.", footnotes: ["d. h. vielleicht: er ging zu seinem Versteck"] },
      { number: 26, text: "Saul ging auf der einen Seite des Berges, David aber und seine Männer auf der anderen Seite des Berges. Und es geschah, als David sich beeilte*, Saul zu entkommen, während Saul und seine Männer gerade David und seine Männer umringen wollten, um sie zu fangen*,", footnotes: ["o. ängstlich bemüht war", "℘ Ps 17,9.11"] },
      { number: 27, text: "kam ein Bote zu Saul und sagte: Eile und komm! Denn die Philister sind ins Land eingefallen." },
      { number: 28, text: "Da kehrte Saul um von der Verfolgung Davids und zog den Philistern entgegen*. Daher nennt man jenen Ort: Sela-Machlekot*.", footnotes: ["℘ Kap. 24,2", "d. h. Fels der Trennung\n℘ Ps 124,7"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und David zog von dort hinauf und blieb auf den Bergfesten von En-Gedi*.", heading: "Davids Bundestreue gegenüber Saul in der Höhle bei En-Gedi", footnotes: ["℘ Jos 15,62"] },
      { number: 2, text: "Und es geschah, als Saul von der Verfolgung der Philister zurückgekehrt war*, berichtete man ihm: Siehe, David ist in der Wüste En-Gedi.", footnotes: ["℘ Kap. 23,28"] },
      { number: 3, text: "Und Saul nahm dreitausend auserlesene Männer aus ganz Israel und zog hin, um David und seine Männer* in Richtung auf die Steinbockfelsen zu suchen*.", footnotes: ["℘ Kap. 13,2", "℘ Kap. 26,2"] },
      { number: 4, text: "Und er kam zu den Schafhürden am Weg, wo eine Höhle war, und Saul ging hinein, um seine Füße zu bedecken*. David aber und seine Männer saßen hinten in der Höhle*.", footnotes: ["d. i. seine Notdurft zu verrichten", "℘ Kap. 22,1"] },
      { number: 5, text: "Da sagten die Männer Davids zu ihm: Siehe, das ist der Tag, von dem der HERR zu dir gesagt hat: Siehe, ich werde deinen Feind in deine Hand geben*, damit du mit ihm tun kannst*, wie es gut ist in deinen Augen.* Und David stand auf und schnitt heimlich einen Zipfel von dem Oberkleid Sauls ab.", footnotes: ["℘ Ps 59,11", "w. tust", "℘ Kap. 26,8"] },
      { number: 6, text: "Aber danach geschah es, da schlug dem David das Herz*, weil er den Zipfel vom Oberkleid Sauls abgeschnitten hatte.", footnotes: ["℘ 2Sam 24,10"] },
      { number: 7, text: "Und er sagte zu seinen Männern: Das sei vor dem HERRN fern von mir*, dass ich so etwas an meinem Herrn, dem Gesalbten des HERRN, tun sollte, meine Hand an ihn zu legen, denn er ist der Gesalbte des HERRN*!", footnotes: ["w. Etwas Entweihtes sei es mir vor dem HERRN", "℘ Kap. 12,3; 26,23; 2Sam 1,14"] },
      { number: 8, text: "Und David wehrte seinen Männern* mit diesen Worten und erlaubte ihnen nicht, sich an Saul zu vergreifen*. Und Saul stand auf, trat aus der Höhle heraus und zog seines Weges.", footnotes: ["o. trennte seine Männer voneinander; o. riss seine Männer herunter", "w. sich gegen Saul zu erheben\n℘ Mt 5,44"] },
      { number: 9, text: "Danach machte David sich auf, ging aus der Höhle hinaus und rief hinter Saul her: Mein Herr und König! Und Saul sah sich um, und David neigte sein Gesicht zur Erde* und warf sich nieder*.", footnotes: ["d. i. auf die Knie fallen, so dass man mit dem Gesicht die Erde berühren kann", "℘ Kap. 20,41"] },
      { number: 10, text: "Da sagte David zu Saul: Warum hörst du auf die Worte von Menschen, die sagen: Siehe, David sucht dein Unglück*?", footnotes: ["℘ 3Mo 19,16; Hes 22,9"] },
      { number: 11, text: "Siehe, an diesem Tag haben deine Augen gesehen, dass der HERR dich heute in meine Hand gegeben hat in der Höhle. Und man drängte mich*, dich umzubringen. Aber ich habe dich verschont* und dachte: Ich will meine Hand nicht an meinen Herrn legen, denn er ist der Gesalbte des HERRN*!", footnotes: ["w. sagte, o. dachte", "so mit LXX, aram. und syr. Üs.; Mas. T. und lat. Üs.: mein Auge ist deinetwegen geflossen; d. h. hat deinetwegen geweint\n℘ Ps 7,5", "℘ Kap. 12,3; 26,23; 2Sam 1,14"] },
      { number: 12, text: "Sieh, mein Vater, ja, sieh den Zipfel deines Oberkleides in meiner Hand! Denn dass ich einen Zipfel deines Oberkleides abgeschnitten und dich nicht umgebracht habe, daran erkenne und sieh, dass meine Hand rein ist von Bosheit und Aufruhr*! Ich habe mich nicht an dir versündigt. Du aber stellst meinem Leben nach, um es mir zu nehmen*.", footnotes: ["w. in meiner Hand nicht Böses und Treuebruch sind", "℘ Kap. 20,1"] },
      { number: 13, text: "Der HERR richte zwischen mir und dir*, und möge der HERR mich an dir rächen! Aber meine Hand soll nicht gegen dich sein*.", footnotes: ["℘ 1Mo 16,5; Ri 11,27; 1Chr 12,18", "℘ Röm 12,19"] },
      { number: 14, text: "Wie das alte Sprichwort sagt: Von den Gottlosen kommt Gottlosigkeit*; aber meine Hand soll nicht gegen dich sein.", footnotes: ["℘ Hos 10,13; 1Jo 3,4"] },
      { number: 15, text: "Hinter wem zieht der König von Israel her? Wem jagst du nach? Einem toten Hund*, einem einzelnen Floh*!", footnotes: ["℘ Kap. 17,43", "℘ Kap. 26,20"] },
      { number: 16, text: "So sei denn der HERR Richter und richte zwischen mir und dir*! Er sehe darein und führe meine Rechtssache* und verschaffe mir Recht gegen dich*!", footnotes: ["℘ 1Mo 16,5; Ri 11,27; 1Chr 12,18", "w. streite meinen Rechtsstreit\n℘ Ps 119,154; 1Petr 2,23", "w. aus deiner Hand\n℘ Kap. 26,24"] },
      { number: 17, text: "Und es geschah, als David diese Worte an Saul beendet hatte, sagte Saul: Ist das nicht deine Stimme, mein Sohn David*? Und Saul erhob seine Stimme und weinte.", footnotes: ["℘ Kap. 26,17"] },
      { number: 18, text: "Dann sagte er zu David: Du bist gerechter als ich*. Denn du hast mir Gutes erwiesen, ich aber habe dir Böses erwiesen.", footnotes: ["℘ 1Mo 38,26"] },
      { number: 19, text: "Du hast heute bewiesen, wie du Gutes an mir getan hast, als der HERR mich in deine Hand ausgeliefert hatte und du mich nicht umgebracht hast." },
      { number: 20, text: "Denn wenn jemand seinen Feind findet, lässt er ihn dann im Guten seinen Weg gehen? So möge der HERR dir Gutes vergelten für das, was du heute an mir getan hast*!", footnotes: ["℘ Kap. 26,25; Rt 2,12; Ps 7,5; Spr 25,21.22"] },
      { number: 21, text: "Und nun siehe, ich habe erkannt, dass du König, ja, König werden wirst und dass in deiner Hand das Königtum Israels Bestand haben wird*.", footnotes: ["℘ Kap. 23,17; 25,28.30"] },
      { number: 22, text: "So schwöre mir nun bei dem HERRN*, dass du meine Nachkommen* nicht ausrotten und meinen Namen nicht austilgen wirst aus dem Haus meines Vaters*!", footnotes: ["℘ 1Mo 21,23", "w. meinen Samen nach mir", "℘ 2Sam 21,6-8"] },
      { number: 23, text: "Und David schwor es Saul*. Und Saul ging in sein Haus zurück. David aber und seine Männer stiegen auf die Bergfeste hinauf*.", footnotes: ["℘ Kap. 20,14-17.42", "℘ Kap. 22,4; 26,25"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Und Samuel starb*. Und ganz Israel versammelte sich und hielt ihm die Totenklage*, und sie begruben ihn in seiner Heimat* in Rama*. Da machte sich David auf und zog hinab in die Wüste Paran*.", heading: "Samuels Tod — Nabals Torheit und Abigajils Klugheit", footnotes: ["℘ Sach 1,5", "℘ 1Mo 23,2; 5Mo 34,8", "w. in seinem Haus; d. h. auf seinem Besitz", "℘ Kap. 1,19; 28,3", "mit verschiedenen LXX-Handschr.: Maon\n℘ 1Mo 21,21"] },
      { number: 2, text: "Nun war da ein Mann in Maon*, der seine Tätigkeit in Karmel* hatte. Und der Mann war sehr vermögend und hatte dreitausend Schafe* und tausend Ziegen. Der hielt sich gerade in Karmel auf, um seine Schafe zu scheren.", footnotes: ["℘ Kap. 23,24", "d. i. Karmel in Juda; vgl. Jos 15,55\n℘ Kap. 15,12", "℘ 1Mo 31,19"] },
      { number: 3, text: "Der Name des Mannes aber war Nabal* und der Name seiner Frau Abigajil. Sie war eine Frau von klarem Verstand* und von schöner Gestalt*. Der Mann aber war roh und boshaft in seinem Tun, und er war ein Kalebiter*.", footnotes: ["℘ V. 25", "℘ Spr 19,14", "℘ 1Mo 12,11", "℘ Kap. 30,14; Spr 30,22"] },
      { number: 4, text: "Und David hörte in der Wüste, dass Nabal seine Schafe schor." },
      { number: 5, text: "Da sandte David zehn junge Männer aus und sagte zu den jungen Männern: Geht nach Karmel hinauf! Und wenn ihr zu Nabal kommt, fragt ihn in meinem Namen nach seinem Wohlergehen*", footnotes: ["℘ Kap. 17,18"] },
      { number: 6, text: "und sagt so: Lebe lange*! Friede sei mit dir und Friede mit deinem Haus und Friede mit allem, was dein ist*!", footnotes: ["w. Zum Leben. — Mit Einfügung eines Buchstabens üs. andere: und sagt zu meinem Bruder", "℘ 1Mo 43,23; Lk 10,5"] },
      { number: 7, text: "Ich habe gerade gehört, dass du Schafscherer bei dir hast. Nun, deine Hirten sind mit uns zusammengewesen, wir haben ihnen nichts zuleide getan, und nicht das Geringste ist von ihnen vermisst worden all die Tage, die sie in Karmel gewesen sind." },
      { number: 8, text: "Frag deine Leute*, sie werden es dir bestätigen! Lass die Leute* in deinen Augen Gunst finden, denn wir sind an einem Festtag gekommen! Gib nun deinen Knechten und deinem Sohn David, was deine Hand findet*!", footnotes: ["w. Knechte, o. Knaben, o. jungen Männer", "w. Knechte, o. Knaben, o. jungen Männer", "d. h. wozu du in der Lage bist\n℘ Pred 11,2"] },
      { number: 9, text: "Als die Männer* Davids hinkamen, redeten sie mit Nabal all diese Worte im Namen Davids und warteten dann ab.", footnotes: ["w. Knechte, o. Knaben, o. jungen Männer"] },
      { number: 10, text: "Aber Nabal antwortete den Knechten Davids und sagte: Wer ist David, und wer ist der Sohn Isais*? Heutzutage gibt es viele Knechte, die alle ihren Herren davonlaufen, ein jeder seinem Herrn.", footnotes: ["℘ 2Mo 5,2; Ri 9,28"] },
      { number: 11, text: "Und ich sollte mein Brot und mein Wasser nehmen, mein Geschlachtetes, das ich für meine Scherer geschlachtet habe, und es Männern geben, von denen ich nicht weiß, woher sie sind*?", footnotes: ["℘ Ri 8,6"] },
      { number: 12, text: "Und die Leute* Davids machten sich wieder auf ihren Weg und kehrten zurück. Und als sie ankamen, berichteten sie ihm, was alles geschehen war*.", footnotes: ["w. Knechte, o. Knaben, o. jungen Männer", "w. entsprechend allen diesen Ereignissen o. Worten"] },
      { number: 13, text: "Da sagte David zu seinen Männern: Es gürte sich jeder sein Schwert um*! Und jeder gürtete sich sein Schwert um, und auch David gürtete sich sein Schwert um. Und sie zogen hinauf, hinter David her, etwa vierhundert Mann, während zweihundert bei dem Tross blieben*.", footnotes: ["℘ Spr 20,22; Mt 5,39", "℘ Kap. 22,2; 27,2"] },
      { number: 14, text: "Aber einer von den Leuten* berichtete der Abigajil, der Frau Nabals: Siehe, David hat Boten aus der Wüste gesandt, um unseren Herrn zu grüßen*; aber er hat sie angeschrien*.", footnotes: ["w. ein Knecht von den Knechten, o. ein junger Mann von den jungen Männern", "w. segnen", "o. ist schreiend auf sie losgestürzt"] },
      { number: 15, text: "Und doch sind die Männer sehr gut zu uns gewesen. Wir sind nicht belästigt worden, und wir haben nicht das Geringste vermisst alle Tage, die wir mit ihnen umhergezogen sind, wenn wir auf dem Feld waren." },
      { number: 16, text: "Sie sind eine Mauer um uns her gewesen bei Nacht und bei Tag, alle die Tage, die wir in ihrer Nähe waren und die Schafe weideten." },
      { number: 17, text: "Und nun erkenne und sieh zu, was du tun kannst*! Denn das Unglück ist gewiss über unsern Herrn und über sein ganzes Haus beschlossen. Und er ist ein so bösartiger Mensch*, dass man nicht mit ihm reden kann*.", footnotes: ["℘ 2Sam 24,13", "w. ein Sohn der Bosheit", "℘ 2Sam 23,6.7"] },
      { number: 18, text: "Da eilte Abigajil und nahm zweihundert Brote, zwei Schläuche Wein, fünf zubereitete Schafe, fünf Maß Röstkorn, hundert Rosinenkuchen und zweihundert Feigenkuchen* und lud sie auf Esel.", footnotes: ["℘ 2Sam 16,1; 1Chr 12,41"] },
      { number: 19, text: "Und sie sagte zu ihren Knechten: Geht* vor mir her! Siehe, ich komme hinter euch her*. Aber ihrem Mann Nabal sagte sie nichts davon*.", footnotes: ["o. Zieht", "℘ 1Mo 32,19.21", "℘ Kap. 14,1"] },
      { number: 20, text: "Und es geschah, als sie auf dem Esel ritt und im Schutz des Berges hinabritt, siehe, da kamen David und seine Männer ihr entgegen, so dass sie auf sie stieß." },
      { number: 21, text: "David aber hatte gedacht: Fürwahr, umsonst habe ich alles behütet, was diesem Menschen in der Wüste gehört, so dass nicht das Geringste vermisst wurde von allem, was er hatte. Und er hat mir Gutes mit Bösem vergolten*.", footnotes: ["℘ Ps 35,12"] },
      { number: 22, text: "So tue Gott den Feinden Davids, und so füge er hinzu*, wenn ich von allem, was ihm gehört, bis zum Morgen einen übrig lasse, der männlich ist*!", footnotes: ["℘ Kap. 3,17", "w. der an die Wand pisst"] },
      { number: 23, text: "Als Abigajil David sah, stieg sie eilends vom Esel herab*, fiel vor David auf ihr Angesicht und beugte sich zur Erde nieder*.", footnotes: ["℘ Jos 15,18", "℘ V. 41; Rt 2,10; 1Chr 21,21"] },
      { number: 24, text: "Sie fiel ihm zu Füßen und sagte: Auf mich allein, mein Herr, falle die Schuld! Lass doch deine Magd reden vor deinen Ohren und höre die Worte deiner Magd!" },
      { number: 25, text: "Mein Herr ärgere sich doch nicht über* diesen boshaften Menschen*, über Nabal! Denn wie sein Name so ist er: Nabal ist sein Name, und Torheit* ist bei ihm*. Ich aber, deine Magd, habe die Leute* meines Herrn nicht gesehen, die du gesandt hast.", footnotes: ["w. richte nicht sein Herz auf", "o. gemeinen Menschen; w. diesen Mann der Bosheit", "o. Gemeinheit; o. Nichtsnutzigkeit", "℘ Spr 29,7", "w. Knechte, o. Knaben, o. jungen Männer"] },
      { number: 26, text: "Nun aber, mein Herr, so wahr der HERR lebt und du selbst lebst*, der HERR hat dich davor bewahrt*, in Blutschuld zu geraten* und dir mit eigener Hand zu helfen*! So sollen nun deine Feinde und alle, die meinem Herrn übelwollen*, wie Nabal werden*!", footnotes: ["℘ Kap. 1,26", "w. davon abgehalten, o. gehemmt", "℘ 1Mo 20,6", "℘ Kap. 2,9", "w. die Böses für meinen Herrn zu erreichen suchen", "℘ Kap. 20,16; 2Sam 18,32"] },
      { number: 27, text: "Hier nun ist das Segensgeschenk*, das deine Magd meinem Herrn gebracht hat*, das den Leuten* gegeben werde, die im Gefolge meines Herrn ziehen.", footnotes: ["w. dieser Segen; vgl. 1Mo 33,11", "℘ 1Mo 33,11", "w. Knechten; o. Knaben, o. jungen Männern"] },
      { number: 28, text: "Vergib doch deiner Magd die Anmaßung*! Denn sicher wird der HERR meinem Herrn ein beständiges Haus bauen*, weil mein Herr die Kämpfe des HERRN kämpft*. Und möge dein Leben lang nichts Böses an dir gefunden werden*!*", footnotes: ["o. das Vergehen; w. den Treuebruch", "℘ Kap. 24,21; 2Sam 7,11.26.27", "℘ Kap. 18,17", "℘ Kap. 29,3; 4Mo 23,21; 1Kö 15,5", "o. Und dein Leben lang wird nichts Böses an dir gefunden werden."] },
      { number: 29, text: "Und ist ein Mensch aufgestanden, dich zu verfolgen und dir nach dem Leben zu trachten, so möge das Leben meines Herrn eingebunden sein in das Bündel der Lebendigen bei dem HERRN, deinem Gott! Aber das Leben deiner Feinde soll er fortschleudern mit der Schleuderpfanne*!", footnotes: ["℘ Hi 27,22"] },
      { number: 30, text: "Und es wird geschehen, wenn der HERR meinem Herrn all das Gute tun wird, das er dir zugesagt hat, und dich zum Fürsten über Israel bestellt*,", footnotes: ["℘ Kap. 15,28; 23,17; 24,21"] },
      { number: 31, text: "so wird dir, meinem Herrn, das kein Anstoß* und kein Vorwurf des Herzens sein, dass du ohne Ursache Blut vergossen habest und dass mein Herr sich mit eigener Hand geholfen habe*. Und wenn der HERR meinem Herrn wohltun wird, so denke an deine Magd*!", footnotes: ["o. Hindernis; d. i. etwas, worüber man strauchelt und fällt", "℘ Röm 12,19", "℘ 1Mo 40,14"] },
      { number: 32, text: "Und David sagte zu Abigajil: Gepriesen* sei der HERR, der Gott Israels*, der dich an diesem Tag mir entgegengesandt hat!", footnotes: ["o. gesegnet; d. i. eine Dankformel", "℘ Jos 22,33; 1Kö 8,15; Ps 31,22; 41,14"] },
      { number: 33, text: "Und gepriesen* sei deine Klugheit*, und gepriesen* seist du, dass du mich heute davon zurückgehalten hast, in Blutschuld zu geraten und mir mit meiner eigenen Hand zu helfen*!", footnotes: ["o. gesegnet; d. i. eine Dankformel", "o. dein Empfinden; o. dein Feingefühl", "o. dein Empfinden; o. dein Feingefühl", "℘ Spr 13,14"] },
      { number: 34, text: "Aber, so wahr der HERR, der Gott Israels, lebt, der mich bewahrt* hat, dir Böses zu tun: Wenn du mir nicht eilends entgegengekommen wärest, so wäre dem Nabal bis zum Morgenlicht nicht einer, der männlich ist*, übrig geblieben!", footnotes: ["w. davon abgehalten, o. gehemmt", "w. der an die Wand pisst"] },
      { number: 35, text: "Und David nahm aus ihrer Hand, was sie ihm mitgebracht hatte, und sagte zu ihr: Zieh in Frieden hinauf in dein Haus*! Siehe, ich habe auf deine Stimme gehört* und dein Angesicht wieder aufgerichtet.", footnotes: ["℘ Kap. 1,17", "℘ Spr 25,11"] },
      { number: 36, text: "Und als Abigajil zu Nabal kam, siehe, da hatte er ein Mahl in seinem Haus wie das Mahl eines Königs zubereitet*. Und sein Herz war guter Dinge*, und er war über die Maßen betrunken*. Und sie berichtete ihm nichts, weder wenig noch viel, bis der Morgen hell wurde.", footnotes: ["℘ 2Sam 3,20", "w. Und das Herz Nabals war fröhlich in ihm", "℘ Spr 20,1; 23,34; Lk 21,34"] },
      { number: 37, text: "Und es geschah am Morgen, als der Rausch von Nabal gewichen war, berichtete ihm seine Frau alles*. Da erstarb sein Herz in seiner Brust*, und er wurde wie ein Stein.", footnotes: ["w. diese Dinge", "w. in seinem Innern"] },
      { number: 38, text: "Und es geschah nach ungefähr zehn Tagen, da schlug der HERR den Nabal, so dass er starb*.", footnotes: ["℘ 2Chr 13,20; Ps 73,19; Apg 12,23"] },
      { number: 39, text: "Und als David hörte, dass Nabal gestorben sei, sagte er: Gepriesen* sei der HERR, der meine Schmach an Nabal gerächt* und seinen Knecht von einer bösen Tat abgehalten hat*! Die böse Tat Nabals hat der HERR auf seinen eigenen Kopf zurückfallen lassen*. Und David sandte hin und warb um Abigajil*, um sie sich zur Frau zu nehmen.", footnotes: ["o. gesegnet; d. i. eine Dankformel", "w. der den Rechtsstreit meiner Schmach vonseiten Nabals geführt\n℘ Ps 9,5; Spr 22,23; Kla 3,58; Mi 7,9", "℘ Kap. 26,10", "℘ 2Sam 1,16; Est 9,25", "w. redete Abigajil an"] },
      { number: 40, text: "Und die Knechte Davids kamen zu Abigajil nach Karmel und redeten mit ihr: David hat uns zu dir gesandt, um dich zu seiner Frau zu nehmen*.", footnotes: ["℘ Spr 11,16"] },
      { number: 41, text: "Da stand sie auf, beugte sich nieder, das Gesicht zur Erde, und sagte: Siehe, deine Magd ist bereit, den Knechten meines Herrn zu dienen und ihnen die Füße zu waschen.*", footnotes: ["w. Siehe, deine Magd zur Sklavin, den Dienern meines Herrn die Füße zu waschen!\n℘ Rt 2,13"] },
      { number: 42, text: "Und Abigajil machte sich eilends auf und setzte sich auf einen Esel, und ihre fünf Mägde folgten ihr. Und sie zog den Boten Davids nach und wurde seine Frau." },
      { number: 43, text: "Und David hatte auch Ahinoam von Jesreel* zur Frau genommen; so wurden alle beide seine Frauen*.", footnotes: ["℘ Kap. 29,11; Jos 15,56", "℘ Kap. 27,3; 30,5; 2Sam 2,2"] },
      { number: 44, text: "Saul aber hatte seine Tochter Michal, die Frau Davids, Palti, dem Sohne des Lajisch*, aus Gallim* gegeben.", footnotes: ["℘ 2Sam 3,14.15", "℘ Jes 10,30"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Und die Sifiter kamen zu Saul nach Gibea und sagten: Hält sich David nicht auf dem Hügel Hachila*, der Jeschimon* gegenüberliegt, verborgen?", heading: "Davids erneute Treue zu Saul", footnotes: ["℘ Kap. 23,19.24", "d. i. ein Wüstenstreifen"] },
      { number: 2, text: "Da machte Saul sich auf und zog in die Wüste Sif hinab und mit ihm dreitausend auserlesene Männer aus Israel, um David in der Wüste Sif zu suchen*.", footnotes: ["℘ Kap. 24,3"] },
      { number: 3, text: "Und Saul lagerte sich auf dem Hügel Hachila*, der Jeschimon* gegenüber am Weg liegt. David aber hielt sich in der Wüste auf*. Und als er merkte, dass Saul ihm in die Wüste nachgekommen war,", footnotes: ["℘ Kap. 23,19.24", "d. i. ein Wüstenstreifen", "℘ Ps 63,1"] },
      { number: 4, text: "sandte David Kundschafter aus und erfuhr mit Gewissheit, dass Saul gekommen war." },
      { number: 5, text: "Und David machte sich auf und kam an den Ort, wo Saul ein Lager aufgeschlagen hatte. Und David sah den Platz, wo Saul sich zum Schlafen niedergelegt hatte mit Abner, dem Sohn des Ner, seinem Heerobersten*. Saul lag im innersten Lagerring, und das Volk lagerte sich um ihn her.", footnotes: ["℘ Kap. 14,50"] },
      { number: 6, text: "Und David hob an und sagte zu Ahimelech, dem Hetiter*, und zu Abischai, dem Sohn der Zeruja, dem Bruder Joabs*: Wer will mit mir zu Saul ins Lager hinabgehen? Und Abischai antwortete: Ich gehe mit dir hinab.", footnotes: ["℘ 1Mo 10,15; 2Sam 23,39", "℘ 2Sam 2,13.18; 1Chr 2,16"] },
      { number: 7, text: "Und David und Abischai kamen zu den Leuten* in der Nacht. Und siehe, Saul lag schlafend im innersten Lagerring, und sein Speer war an seinem Kopfende in die Erde gesteckt. Und Abner und das Volk lagen um ihn her.", footnotes: ["w. zum Volk"] },
      { number: 8, text: "Und Abischai sagte zu David: Heute hat Gott deinen Feind in deine Hand ausgeliefert*. Nun lass mich ihn doch mit dem Speer an den Boden spießen, einmal nur! Ein zweites Mal werde ich es ihm nicht antun müssen*.", footnotes: ["℘ Kap. 24,5", "℘ 2Sam 16,9; Jer 40,15; Lk 9,54"] },
      { number: 9, text: "Aber David entgegnete Abischai: Bring ihn nicht um*! Denn wer könnte seine Hand gegen den Gesalbten des HERRN ausstrecken und ungestraft bleiben*?", footnotes: ["℘ 2Sam 1,14; Ps 57,1", "℘ Kap. 12,3; 2Sam 19,22; Ps 17,4"] },
      { number: 10, text: "Und David sagte weiter: So wahr der HERR lebt, sicher wird ihn der HERR schlagen*, wenn seine Zeit* kommt, dass er sterbe*, oder er wird in den Krieg ziehen und umkommen*!", footnotes: ["℘ Kap. 25,38.39", "w. sein Tag", "℘ Hi 14,5", "o. er wird in der Schlacht zu Boden sinken und hinweggerafft werden\n℘ Kap. 31,4"] },
      { number: 11, text: "Der HERR lasse es fern von mir sein, dass ich meine Hand an den Gesalbten des HERRN legen sollte*! Und nun, nimm jetzt den Speer, der an seinem Kopfende steckt, und den Wasserkrug und lass uns gehen!", footnotes: ["℘ Kap. 12,3; 2Sam 19,22; Ps 17,4"] },
      { number: 12, text: "Und David nahm den Speer und den Wasserkrug von seinem Kopfende weg, und sie gingen fort. Niemand sah es, und niemand merkte* es, und niemand wachte auf. Denn sie schliefen alle, weil ein tiefer Schlaf von dem HERRN auf sie gefallen war*.", footnotes: ["o. erkannte", "℘ 1Mo 2,21"] },
      { number: 13, text: "Und David ging hinüber auf die andere Seite und stellte sich auf den Gipfel des Berges von ferne, so dass ein weiter Raum zwischen ihnen war." },
      { number: 14, text: "Und David rief dem Kriegsvolk und Abner, dem Sohn des Ner, zu: Antwortest du nicht, Abner? Abner antwortete und fragte: Wer bist du, der du so zum König hin schreist?" },
      { number: 15, text: "Und David sagte zu Abner: Bist du nicht ein Mann? Wer ist wie du in Israel*? Warum hast du nicht deinen Herrn, den König, bewacht? Denn es ist einer vom Volk eingedrungen, um den König, deinen Herrn, umzubringen.", footnotes: ["℘ 2Sam 3,38"] },
      { number: 16, text: "Das war nicht gut, was du getan hast! So wahr der HERR lebt, ihr seid Söhne des Todes, weil ihr nicht über euren Herrn, über den Gesalbten des HERRN gewacht habt! Und nun sieh doch nach, wo der Speer des Königs ist und der Wasserkrug, die an seinem Kopfende waren." },
      { number: 17, text: "Und Saul erkannte die Stimme Davids* und sagte: Ist das deine Stimme, mein Sohn David? David antwortete: Es ist meine Stimme, mein Herr und König.", footnotes: ["℘ Kap. 24,17"] },
      { number: 18, text: "Und er sprach weiter: Warum jagt denn mein Herr seinem Knecht nach? Ja, was habe ich getan, und was ist Böses in meiner Hand*?", footnotes: ["℘ Kap. 20,1.32; Joh 18,23"] },
      { number: 19, text: "Und nun, höre doch mein Herr, der König, auf die Worte seines Knechtes: Wenn der HERR dich gegen mich aufgebracht hat*, so lasse man ihn ein Speisopfer* riechen*. Wenn es aber Menschensöhne sind, so seien sie verflucht vor dem HERRN, weil sie mich heute vertrieben haben und mich nicht an dem Erbteil des HERRN teilhaben lassen* und sagen: Geh hin, diene andern Göttern*!", footnotes: ["℘ 2Sam 16,10", "o. eine Opfergabe", "℘ 1Mo 8,21; Ps 20,4", "w. dass sie mich heute vertreiben vom Anschluss an das Erbteil des HERRN\n℘ 4Mo 36,7.9", "℘ 5Mo 13,3"] },
      { number: 20, text: "So möge nun mein Blut nicht auf die Erde fließen fern von dem Angesicht des HERRN. Denn der König von Israel ist ausgezogen, einen einzelnen Floh zu suchen, wie man einem Rebhuhn nachjagt auf den Bergen*.", footnotes: ["℘ Kap. 24,15"] },
      { number: 21, text: "Und Saul entgegnete: Ich habe gesündigt! Komm zurück, mein Sohn David! Ich will dir nicht noch länger etwas Böses antun, weil mein Leben heute in deinen Augen teuer gewesen ist*. Siehe, ich habe töricht gehandelt* und mich sehr schwer vergangen*!", footnotes: ["℘ 2Kö 1,13.14", "℘ Kap. 13,13", "℘ Kap. 15,24"] },
      { number: 22, text: "Und David antwortete und sagte: Siehe, hier ist der Speer des Königs! Es komme einer von den Leuten* herüber und hole ihn!", footnotes: ["w. Knechten; o. Knaben, o. jungen Männern"] },
      { number: 23, text: "Und der HERR wird jedem seine Gerechtigkeit und seine Treue vergelten*. Denn der HERR hat dich heute in meine Hand gegeben, ich aber wollte meine Hand nicht an den Gesalbten des HERRN legen*.", footnotes: ["℘ 2Sam 22,21.25; Hi 34,11; Ps 62,13", "℘ Kap. 24,11"] },
      { number: 24, text: "Siehe, wie dein Leben heute in meinen Augen hoch geachtet gewesen ist, so möge mein Leben hoch geachtet werden in den Augen des HERRN, und er möge mich retten aus aller Bedrängnis*.", footnotes: ["℘ Kap. 24,16; 2Sam 4,9; Ps 34,20; 2Tim 4,18"] },
      { number: 25, text: "Und Saul sagte zu David: Gesegnet seist du, mein Sohn David! Du wirst es sicher ausrichten und zustande bringen*. Und David ging seines Weges. Saul aber kehrte an seinen Ort zurück*.", footnotes: ["o. Du wirst es sowohl unternehmen als auch ausführen\n℘ Kap. 24,20", "℘ Kap. 24,23"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und David dachte in seinem Herzen*: Nun werde ich doch eines Tages durch die Hand Sauls umkommen*! Es gibt nichts Besseres für mich, als eiligst in das Land der Philister zu entrinnen. Dann wird Saul von mir ablassen, mich weiter im ganzen Gebiet Israels zu suchen. Und ich werde seiner Hand entrinnen.", heading: "David wird Gefolgsmann bei Achisch von Gat", footnotes: ["℘ 1Kö 12,26.28; 2Chr 25,17", "℘ Kap. 20,3; 1Kö 19,3; Jes 40,27"] },
      { number: 2, text: "So machte sich David auf und ging mit sechshundert Mann, die bei ihm waren*, zu Achisch, dem Sohn des Maoch, dem König von Gat, über*.", footnotes: ["℘ Kap. 25,13", "℘ Kap. 21,11; 1Kö 2,39"] },
      { number: 3, text: "Und David blieb bei Achisch in Gat, er selbst und seine Männer, jeder mit seinem Haus, David und seine beiden Frauen, Ahinoam, die Jesreeliterin, und Abigajil, die Frau Nabals*, die Karmeliterin.", footnotes: ["℘ Kap. 25,42.43"] },
      { number: 4, text: "Und als Saul berichtet wurde, dass David nach Gat* geflohen sei, suchte er ihn nicht mehr länger.", footnotes: ["℘ 2Sam 15,18"] },
      { number: 5, text: "Und David sagte zu Achisch: Wenn ich denn Gunst in deinen Augen gefunden habe, dann gebe man mir einen Platz in einer der Städte auf dem Lande, damit ich dort wohne! Denn wozu soll dein Knecht bei dir in der Königsstadt wohnen?" },
      { number: 6, text: "Und Achisch gab ihm an diesem Tag Ziklag*. Darum hat Ziklag den Königen von Juda gehört bis zum heutigen Tag.", footnotes: ["℘ Kap. 30,1; Jos 15,31; 1Chr 12,1"] },
      { number: 7, text: "Die Zeit aber, die* David im Gebiet der Philister wohnte, war ein Jahr und vier Monate*.", footnotes: ["w. Und die Zahl der Tage, die", "℘ Kap. 29,3"] },
      { number: 8, text: "Und David zog mit seinen Männern hinauf, und sie fielen ein bei den Geschuritern* und den Girsitern und den Amalekitern*. Denn diese waren von alters her die Bewohner des Landes bis nach Schur* hin und bis zum Land Ägypten.", footnotes: ["℘ 4Mo 13,29; 14,45; Jos 13,2", "℘ 2Sam 22,21.25; Hi 34,11; Ps 62,13", "℘ Kap. 15,7"] },
      { number: 9, text: "Und sooft David das Land verwüstete, ließ er weder Mann noch Frau am Leben. Und er nahm Schafe, Rinder, Esel, Kamele und Kleider mit und kehrte wieder zurück und kam zu Achisch." },
      { number: 10, text: "Und wenn Achisch fragte: Wohin habt ihr heute einen Einfall gemacht*? — dann antwortete David: In den Süden von Juda! — oder: In das Südland der Jerachmeeliter*! — oder: In das Südland der Keniter*!", footnotes: ["so mit einigen hebr. Handschr., LXX und der aram. Üs.; Mas. T.: Habt ihr heute keinen Einfall gemacht", "℘ 1Chr 2,9", "℘ Kap. 15,6; 30,29"] },
      { number: 11, text: "Und David ließ weder Mann noch Frau am Leben, um sie nach Gat zu bringen, denn er dachte: Damit sie nicht gegen uns aussagen und berichten: So hat David gehandelt! Und so hielt er es die ganze Zeit*, die er im Gebiet der Philister wohnte.", footnotes: ["w. so war seine Weise all die Tage"] },
      { number: 12, text: "Und Achisch glaubte David und dachte: Er hat sich bei seinem Volk, bei Israel, ganz stinkend gemacht*, darum wird er für immer mein Knecht sein.", footnotes: ["℘ Kap. 13,4"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Und es geschah in jenen Tagen, da versammelten die Philister ihre Heere zum Krieg, um gegen Israel in den Kampf zu ziehen*. Und Achisch sagte zu David: Du erkennst sehr wohl, dass du und deine Männer mit mir im Heer ausziehen müssen*.", heading: "Saul bei der Totenbeschwörerin — Samuels Weissagung des Unheils", footnotes: ["℘ Kap. 31,1", "℘ Kap. 29,1.2"] },
      { number: 2, text: "David entgegnete Achisch: Gut*, auch du wirst erkennen, was dein Knecht tun wird. Und Achisch sagte zu David: Gut, ich will dich zu meinem Leibwächter für die ganze Zeit machen*.", footnotes: ["w. Darum", "w. Darum will ich dich für mein Haupt zum Wächter einsetzen alle Tage"] },
      { number: 3, text: "Samuel aber war gestorben, und ganz Israel hatte ihm die Totenklage gehalten und ihn in seiner Stadt Rama begraben*. Und Saul hatte die Totenbeschwörer und Wahrsager* aus dem Land vertrieben*.", footnotes: ["℘ Kap. 25,1", "w. die Wissenden", "℘ 2Mo 22,17; 3Mo 19,31"] },
      { number: 4, text: "Und die Philister versammelten sich, kamen und lagerten bei Schunem*. Und Saul versammelte ganz Israel, und sie lagerten auf dem Gebirge Gilboa*.", footnotes: ["℘ Jos 19,18", "℘ Kap. 31,1"] },
      { number: 5, text: "Und als Saul das Heer der Philister sah, fürchtete er sich, und sein Herz verzagte* sehr*.", footnotes: ["o. zitterte; o. bebte", "℘ Hi 18,11"] },
      { number: 6, text: "Und Saul befragte den HERRN; aber der HERR antwortete ihm nicht*, weder durch Träume* noch durch die Urim*, noch durch Propheten*.", footnotes: ["℘ Kap. 14,37", "℘ 4Mo 12,6", "d. i. eine Befragung Gottes durch das Los\n℘ 2Mo 28,30", "℘ Kla 2,9"] },
      { number: 7, text: "Da sagte Saul zu seinen Knechten: Sucht mir eine Frau, die Tote beschwören kann*, damit ich zu ihr gehe und sie befrage*! Und seine Knechte sagten zu ihm: Siehe, in En-Dor* ist eine Frau, die Tote beschwören kann*.", footnotes: ["w. eine Besitzerin eines Totengeistes", "℘ Jes 8,19.20", "℘ 3Mo 19,31; Jos 17,11", "w. eine Besitzerin eines Totengeistes"] },
      { number: 8, text: "Und Saul machte sich unkenntlich, zog andere Kleider an und ging hin, er und zwei Männer mit ihm, und sie kamen zu der Frau bei Nacht. Und Saul sagte: Wahrsage mir doch durch Totenbeschwörung* und bringe mir herauf, wen ich dir nennen werde*!", footnotes: ["w. durch Totengeist", "℘ 1Chr 10,13"] },
      { number: 9, text: "Aber die Frau antwortete ihm: Siehe, du kennst ja das, was Saul getan hat, wie er die Totenbeschwörer und die Wahrsager* aus dem Land ausgerottet hat. Und warum stellst du mir* eine Falle, um mich zu töten?", footnotes: ["w. die Wissenden", "w. meinem Leben, o. meiner Seele"] },
      { number: 10, text: "Und Saul schwor ihr bei dem HERRN: So wahr der HERR lebt, es soll dich in dieser Sache keine Schuld* treffen*!", footnotes: ["o. Strafe", "w. wenn dich eine Schuld treffen soll wegen dieser Sache"] },
      { number: 11, text: "Da sagte die Frau: Wen soll ich dir heraufholen? Und er erwiderte: Hole mir Samuel herauf!" },
      { number: 12, text: "Als aber die Frau Samuel sah, schrie sie laut auf und sagte* zu Saul: Warum hast du mich betrogen? Du bist ja Saul!", footnotes: ["w. Als die Frau Samuel sah, schrie sie mit lauter Stimme. Und die Frau sagte. — LXX und einige hebr. Handschr.: Als die Frau Saul sah, schrie sie"] },
      { number: 13, text: "Und der König sagte zu ihr: Fürchte dich nicht! Nun, was siehst du? Die Frau antwortete Saul: Ich sehe einen Geist* aus der Erde heraufsteigen.", footnotes: ["w. einen Gott, o. ein Götterwesen"] },
      { number: 14, text: "Er sagte zu ihr: Wie sieht er aus*? Und sie antwortete: Ein alter Mann steigt herauf. Er ist in ein Oberkleid gehüllt*. Da erkannte Saul, dass es Samuel war, und er neigte sich mit seinem Gesicht zur Erde und fiel nieder.", footnotes: ["w. Wie ist seine Gestalt", "℘ Kap. 15,27; 2Kö 2,8.13"] },
      { number: 15, text: "Und Samuel sprach zu Saul: Warum hast du meine Ruhe gestört, dass du mich heraufkommen lässt? Und Saul antwortete: Ich bin in großer Bedrängnis*! Denn die Philister kämpfen gegen mich, und Gott ist von mir gewichen* und antwortet mir nicht mehr, weder durch Propheten noch durch Träume. Da ließ ich dich rufen, damit du mir zu erkennen gibst, was ich tun soll.", footnotes: ["℘ Kap. 30,6", "℘ Kap. 16,14"] },
      { number: 16, text: "Und Samuel sprach: Warum fragst du mich, da doch der HERR von dir gewichen und dein Feind geworden ist*?", footnotes: ["℘ Kla 2,5"] },
      { number: 17, text: "Der HERR hat dir* getan, wie er durch mich geredet hat. Und der HERR hat das Königtum aus deiner Hand gerissen und es David, deinem Nächsten, gegeben*.", footnotes: ["so mit 5 hebr. Handschr., LXX und lat. Üs.; Mas. T.: ihm; d. h. David", "℘ Kap. 15,28"] },
      { number: 18, text: "Weil du der Stimme des HERRN nicht gehorcht und seinen flammenden Zorn nicht an Amalek ausgeführt hast*, darum hat dir der HERR das heute angetan.", footnotes: ["℘ Kap. 15,9.18.19"] },
      { number: 19, text: "Und der HERR wird auch Israel mit dir in die Hand der Philister geben. Morgen wirst du mit deinen Söhnen bei mir sein*. Auch das Heerlager Israels wird der HERR in die Hand der Philister geben*.", footnotes: ["℘ Kap. 31,1-6", "℘ 2Sam 22,21.25; Hi 34,11; Ps 62,13"] },
      { number: 20, text: "Da fiel Saul plötzlich seiner Länge nach zur Erde, und er geriet in große Furcht über die Worte Samuels. Auch war keine Kraft mehr in ihm, denn er hatte den ganzen Tag und die ganze Nacht nichts gegessen." },
      { number: 21, text: "Und die Frau trat zu Saul und sah, dass er sehr bestürzt war. Da sagte sie zu ihm: Siehe, deine Magd hat auf deine Stimme gehört, und ich habe mein Leben aufs Spiel gesetzt und deinen Worten gehorcht, die du mir gesagt hast." },
      { number: 22, text: "Und nun höre doch auch du auf die Stimme deiner Magd! Ich will dir einen Bissen Brot vorsetzen. Iss, damit du wieder zu Kräften kommst*, wenn du deinen Weg gehen musst!", footnotes: ["w. und Kraft wird in dir sein, o. und Kraft wird in dir werden"] },
      { number: 23, text: "Aber er weigerte sich und sagte: Ich will nicht essen. Da drängten ihn seine Knechte und auch die Frau. Und er hörte auf ihre Stimme und stand von der Erde auf und setzte sich auf das Bett*.", footnotes: ["o. Polster"] },
      { number: 24, text: "Und die Frau hatte ein gemästetes Kalb im Haus. Und sie beeilte sich, es zu schlachten, und nahm Mehl, knetete es und backte daraus ungesäuerte Brote*.", footnotes: ["℘ 1Mo 18,6"] },
      { number: 25, text: "Und sie setzte es Saul und seinen Knechten vor, und sie aßen. Und sie machten sich auf und gingen noch in derselben Nacht fort." },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Und die Philister versammelten all ihre Heere bei Afek*, Israel aber lagerte sich an der Quelle, die bei Jesreel ist*.", heading: "Misstrauen der Philisterkönige gegen David", footnotes: ["℘ Kap. 4,1", "℘ Ri 7,1"] },
      { number: 2, text: "Und die Fürsten der Philister zogen vorüber nach Hundertschaften und Tausendschaften, und David und seine Männer* zogen zuletzt mit Achisch vorüber.", footnotes: ["℘ Kap. 28,1"] },
      { number: 3, text: "Da sagten die Obersten der Philister: Was sollen diese Hebräer*? Achisch antwortete den Obersten der Philister: Das ist doch David, der Knecht Sauls, des Königs von Israel, der schon seit Jahr und Tag bei mir gewesen ist*. Ich habe nicht das Geringste an ihm gefunden von dem Tag an, da er abgefallen ist, bis heute.", footnotes: ["℘ Kap. 4,6; 14,11; 1Mo 14,13", "℘ Kap. 27,7.12; Kap. 25,28"] },
      { number: 4, text: "Aber die Obersten der Philister wurden zornig über ihn, und die Obersten der Philister sagten zu ihm: Schick den Mann zurück, damit er an seinen Ort zurückkehrt, den du ihm angewiesen hast*, und damit er nicht mit uns in den Kampf hinabzieht und uns nicht zum Widersacher* im Kampf wird! Denn womit könnte er seinem Herrn* einen besseren Gefallen tun als mit den Köpfen dieser Männer*?", footnotes: ["w. den du ihm zur Aufsicht übergeben hast; d. h. den Achisch als Herr an David (als einen Verwalter) übergab", "hebr. satan", "d. i. Saul", "℘ Kap. 14,21; 2Mo 1,10; 1Chr 12,20"] },
      { number: 5, text: "Ist das nicht derselbe David, von dem sie bei den Reigentänzen sangen: Saul hat seine Tausend erschlagen und David seine Zehntausend?*", footnotes: ["℘ Kap. 18,7"] },
      { number: 6, text: "Und Achisch rief David und sagte zu ihm: So wahr der HERR lebt, ja, du bist redlich! Es wäre mir lieb gewesen, wenn du mit mir im Heer aus- und eingezogen wärest*. Denn ich habe nichts Böses an dir gefunden von dem Tag an, da du zu mir gekommen bist, bis zum heutigen Tag; aber den Fürsten gefällst du nicht*.", footnotes: ["w. Gut in meinen Augen ist dein Ausziehen und dein Kommen mit mir in der Schlachtreihe", "w. in den Augen der Fürsten bist du nicht gut"] },
      { number: 7, text: "Und nun kehre zurück und geh hin in Frieden*, damit du nichts tust, was den Fürsten der Philister nicht gefällt*!", footnotes: ["℘ Kap. 1,17", "w. nichts, was in den Augen der Fürsten . . . Böses ist, tust"] },
      { number: 8, text: "Und David sagte zu Achisch: Was habe ich denn getan, und was hast du an deinem Knecht gefunden seit der Zeit*, da ich dir gedient habe*, bis heute, dass ich nicht herkommen und gegen die Feinde meines Herrn, des Königs, kämpfen soll?", footnotes: ["w. von dem Tag an", "w. vor dir gewesen bin"] },
      { number: 9, text: "Und Achisch antwortete und sagte zu David: Ich weiß es*, denn in meinen Augen bist du so gut wie ein Engel Gottes*. Doch die Obersten der Philister haben gesagt: Er soll nicht mit uns in den Kampf hinaufziehen!", footnotes: ["o. habe es erkannt", "℘ 2Sam 14,17.20; Gal 4,14"] },
      { number: 10, text: "So mach dich nun früh am Morgen auf mit den Knechten deines Herrn, die mit dir gekommen sind! Und macht euch früh am Morgen auf! Sobald es hell wird*, zieht fort!", footnotes: ["w. Sobald es euch hell wird"] },
      { number: 11, text: "Und David machte sich früh auf, er und seine Männer, um noch am Morgen fortzuziehen und in das Land der Philister zurückzukehren. Die Philister aber zogen nach Jesreel hinauf*.", footnotes: ["℘ Kap. 25,43"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Und es geschah, als David und seine Männer am dritten Tag nach Ziklag kamen*, waren die Amalekiter in das Südland und in Ziklag* eingefallen. Und sie hatten Ziklag geschlagen und mit Feuer verbrannt.", heading: "Davids Sieg über die Amalekiter", footnotes: ["℘ 1Chr 12,21.22", "℘ Kap. 27,6"] },
      { number: 2, text: "Und sie hatten die Frauen und was sonst in der Stadt war, gefangen weggetrieben, vom Kleinsten bis zum Größten*. Sie hatten aber niemand getötet, sondern sie weggetrieben und waren abgezogen*.", footnotes: ["w. von Klein bis Groß", "w. ihres Weges gezogen"] },
      { number: 3, text: "David und seine Männer kamen zur Stadt. Und siehe, sie war mit Feuer verbrannt, und ihre Frauen, Söhne und Töchter waren gefangen weggeführt." },
      { number: 4, text: "Da erhoben David und das Volk, das bei ihm war, ihre Stimme und weinten, bis sie nicht mehr weinen konnten*.", footnotes: ["w. bis keine Kraft zu weinen mehr in ihnen war\n℘ Kap. 11,4; Ri 21,2"] },
      { number: 5, text: "Und die beiden Frauen Davids waren gefangen weggeführt worden, Ahinoam, die Jesreeliterin, und Abigajil, die Frau Nabals, des Karmeliters*.", footnotes: ["℘ Kap. 25,42.43"] },
      { number: 6, text: "Und David war in großer Bedrängnis*, denn das Volk sprach davon, ihn zu steinigen*. Denn die Seele des ganzen Volkes war erbittert, jeder war erbittert wegen seiner Söhne und wegen seiner Töchter. Aber David stärkte sich in dem HERRN, seinem Gott*.", footnotes: ["℘ Kap. 28,15", "℘ 2Mo 17,4", "℘ Kap. 23,16; Ps 56,4; 138,3"] },
      { number: 7, text: "Und David sagte zu dem Priester Abjatar*, dem Sohn des Ahimelech: Bring mir doch das Efod* her! Und Abjatar brachte das Efod zu David.", footnotes: ["℘ Kap. 14,19", "d. i. ein Priesterschurz"] },
      { number: 8, text: "Und David befragte den HERRN*: Soll ich dieser Schar nachjagen? Werde ich sie einholen*? Und er sprach zu ihm: Jage ihr nach, ja, du wirst sie gewiss einholen und die Gefangenen ganz gewiss befreien*!", footnotes: ["℘ Kap. 10,22; 2Sam 5,19.23", "℘ Kap. 14,37", "℘ Kap. 23,4"] },
      { number: 9, text: "Da zog David hin, er und die sechshundert Mann, die bei ihm waren. Und sie kamen an den Bach Besor, wo einige zurückblieben und haltmachten*.", footnotes: ["w. und die Zurückbleibenden machten halt"] },
      { number: 10, text: "Und David jagte ihnen mit vierhundert Mann nach. Denn zweihundert Mann, die zu erschöpft waren, um über den Bach Besor zu gehen*, blieben zurück.", footnotes: ["℘ Ri 8,4; Jes 40,30"] },
      { number: 11, text: "Und sie fanden einen Ägypter auf dem Feld und brachten ihn zu David und gaben ihm Brot zu essen und Wasser zu trinken*.", footnotes: ["℘ 5Mo 23,8"] },
      { number: 12, text: "Sie reichten ihm auch ein Stück Feigenkuchen und zwei Rosinenkuchen. Und als er gegessen hatte, kam er wieder zu sich*, denn er hatte drei Tage und drei Nächte kein Brot gegessen und kein Wasser getrunken.", footnotes: ["w. und er aß, und sein Geist kehrte zu ihm zurück\n℘ Ri 15,19"] },
      { number: 13, text: "Und David sagte zu ihm: Zu wem gehörst du*? Und woher bist du? Er antwortete: Ich bin ein junger Ägypter, der Knecht eines Amalekiters. Mein Herr hat mich zurückgelassen, denn ich wurde heute vor drei Tagen krank.", footnotes: ["℘ 2Sam 1,3.8"] },
      { number: 14, text: "Wir sind eingefallen in das Südland der Kreter* und in das Gebiet von Juda und in das Südland von Kaleb* und haben Ziklag mit Feuer verbrannt.", footnotes: ["℘ Hes 25,16; Zef 2,5", "℘ Kap. 25,3"] },
      { number: 15, text: "Und David sagte zu ihm: Willst du mich zu dieser Schar hinabführen? Und er antwortete: Schwöre mir bei Gott*, dass du mich nicht töten und mich nicht in die Hand meines Herrn ausliefern wirst! Und ich will dich zu dieser Schar hinabführen.", footnotes: ["℘ 1Mo 24,3; Ri 1,24"] },
      { number: 16, text: "Als er ihn hinabführte, siehe, da hatten sie sich über die ganze Gegend hin ausgebreitet*. Sie aßen und tranken* und feierten ein Freudenfest wegen all der großen Beute, die sie aus dem Land der Philister und aus dem Land Juda mitgenommen hatten.", footnotes: ["w. sie waren über die Fläche des ganzen Landes zerstreut", "℘ Ri 8,11"] },
      { number: 17, text: "Und David schlug sie von der Morgendämmerung an bis zum Abend des folgenden Tages, so dass keiner von ihnen entrann außer vierhundert jungen Männern, die auf Kamele stiegen und entflohen*.", footnotes: ["℘ 1Chr 4,43"] },
      { number: 18, text: "Und David befreite alles, was die Amalekiter genommen hatten; auch seine beiden Frauen befreite David." },
      { number: 19, text: "Und es fehlte ihnen nichts, vom Kleinsten bis zum Größten, weder Söhne noch Töchter, weder Beute noch alles, was sie ihnen weggenommen hatten; alles brachte David zurück*.", footnotes: ["℘ 1Mo 14,14-16; 4Mo 31,49"] },
      { number: 20, text: "Und David nahm alle Schafe und Rinder. Sie trieben sie vor dem anderen Vieh her und sagten: Dies ist die Beute Davids!" },
      { number: 21, text: "Und David kam zu den zweihundert Männern, die zu erschöpft gewesen waren, um David zu folgen, und die man am Bach Besor zurückgelassen hatte. Sie gingen David und dem Kriegsvolk entgegen, das bei ihm war. Und David trat zu dem Volk und fragte sie nach ihrem Wohlergehen*.", footnotes: ["℘ Kap. 17,22"] },
      { number: 22, text: "Und allerlei Böse und Nichtswürdige von den Männern*, die mit David gezogen waren, sagten: Weil sie nicht mit uns* gezogen sind, wollen wir ihnen von der Beute, die wir den Feinden entrissen haben, nichts geben, sondern jeder nehme seine Frau und seine Kinder; die können sie mitnehmen und gehen.", footnotes: ["w. jeder Mann des Bösen und der Nichtsnutzigkeit von den Männern", "so mit einigen hebr. Handschr. und LXX; Mas. T.: mit mir"] },
      { number: 23, text: "Aber David sagte: Macht es nicht so, meine Brüder, mit dem, was der HERR uns gegeben hat! Er hat uns bewahrt und diese Schar, die über uns gekommen war, in unsere Hand gegeben*.", footnotes: ["℘ 5Mo 8,17"] },
      { number: 24, text: "Und wer sollte in dieser Sache auf euch hören? Denn wie der Anteil dessen, der in den Kampf hinabzieht, so soll auch der Anteil dessen sein, der bei dem Tross bleibt*. Miteinander sollen sie teilen*.", footnotes: ["℘ Kap. 22,2", "℘ 4Mo 31,27"] },
      { number: 25, text: "Und so geschah es von diesem Tag an und darüber hinaus. Und David* machte es zu Ordnung und Recht für Israel bis auf diesen Tag.", footnotes: ["o. man"] },
      { number: 26, text: "Und David kam nach Ziklag*. Und er sandte von der Beute den Ältesten in Juda, seinen Freunden*, und ließ ihnen sagen: Siehe, da habt ihr ein Segensgeschenk* von der Beute der Feinde des HERRN*;", footnotes: ["℘ 2Sam 1,1", "o. seinen Nächsten", "w. einen Segen", "℘ Lk 16,9"] },
      { number: 27, text: "denen in Bethel* und denen in Ramot* im Südland* und denen in Jattir*", footnotes: ["Vielleicht ist mit 1Chr 4,30 und Jos 19,4 Betul bzw. Betuël zu lesen.", "Nach anderen ist »Rama« zu lesen.", "℘ Jos 19,8", "℘ Jos 15,48"] },
      { number: 28, text: "und denen in Aroër* und denen in Sifmot* und denen in Eschtemoa*", footnotes: ["℘ 1Chr 11,44", "℘ 1Chr 27,27", "℘ Jos 15,50"] },
      { number: 29, text: "und denen in Rakal und denen in den Städten der Jerachmeeliter* und denen in den Städten der Keniter*", footnotes: ["℘ Kap. 27,10", "℘ 2Sam 1,1"] },
      { number: 30, text: "und denen in Horma* und denen in Bor-Aschan* und denen in Atach", footnotes: ["℘ Jos 15,30", "℘ Jos 15,42"] },
      { number: 31, text: "und denen in Hebron* und nach allen Orten, wo David mit seinen Männern umhergezogen war.", footnotes: ["℘ Jos 15,13"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "*Die Philister aber kämpften gegen Israel*. Und die Männer von Israel flohen vor den Philistern, und vom Schwert Durchbohrte fielen auf dem Gebirge Gilboa*.", heading: "Israels Niederlage am Gilboa — Beisetzung Sauls und seiner Söhne in Jabesch", footnotes: ["℘ 1Chr 10,1-12", "℘ Kap. 28,1", "℘ Kap. 28,4; 2Sam 1,21"] },
      { number: 2, text: "Und die Philister holten Saul und seine Söhne ein*. Und sie* erschlugen Jonatan, Abinadab und Malkischua, die Söhne Sauls*.", footnotes: ["o. bekamen Saul . . . zu fassen", "w. die Philister", "℘ Kap. 14,49"] },
      { number: 3, text: "Und der Kampf tobte heftig gegen Saul, und die Bogenschützen* erreichten* ihn. Und er zitterte sehr vor den Schützen*.", footnotes: ["w. die Schützen, die Männer mit dem Bogen", "o. fanden", "LXX: Und er wurde an den Eingeweiden verwundet\n℘ 2Sam 1,6"] },
      { number: 4, text: "Da sagte Saul zu seinem Waffenträger: Zieh dein Schwert und durchbohre mich damit, damit diese Unbeschnittenen nicht kommen und mich durchbohren und ihren Mutwillen mit mir treiben*! Sein Waffenträger aber wollte nicht, denn er fürchtete sich sehr. Da nahm Saul das Schwert und stürzte sich hinein*.", footnotes: ["℘ Ri 9,54", "℘ Kap. 26,10; 2Sam 1,1"] },
      { number: 5, text: "Und als sein Waffenträger sah, dass Saul tot war, stürzte auch er sich in sein Schwert und starb mit ihm." },
      { number: 6, text: "So starben Saul und seine drei Söhne* und sein Waffenträger, auch alle seine Männer zugleich an diesem Tag.", footnotes: ["℘ Kap. 28,19; 2Sam 1,12"] },
      { number: 7, text: "Als aber die Männer von Israel, die jenseits der Ebene* und jenseits des Jordan wohnten, sahen, dass die Männer von Israel geflohen* und dass Saul und seine Söhne tot waren, da verließen sie die Städte und flohen. Und die Philister kamen und wohnten darin.", footnotes: ["d. h. jenseits der Talebene von Jesreel", "℘ Kap. 13,6.7"] },
      { number: 8, text: "Und es geschah am folgenden Tag, da kamen die Philister, um die Erschlagenen auszuplündern. Und sie fanden Saul und seine drei Söhne, wie sie gefallen auf dem Gebirge Gilboa* lagen.", footnotes: ["℘ Kap. 28,4; 2Sam 1,21"] },
      { number: 9, text: "Und sie hieben ihm den Kopf ab* und nahmen ihm seine Waffen ab. Und sie sandten im Land der Philister umher, um die Freudenbotschaft in den Häusern ihrer Götzen und unter dem Volk zu verkünden*.", footnotes: ["℘ Kap. 17,51", "℘ 2Sam 1,20"] },
      { number: 10, text: "Und sie legten seine Waffen in das Haus der Astarot, und seine Leiche nagelten sie an die Mauer von Bet-Schean*.", footnotes: ["℘ Jos 17,11; Ri 1,27"] },
      { number: 11, text: "Als aber die Bewohner von Jabesch-Gilead* über ihn hörten und was die Philister Saul angetan hatten,", footnotes: ["℘ Kap. 11,1-11"] },
      { number: 12, text: "machten sich alle tüchtigen Männer* auf und gingen die ganze Nacht hindurch und nahmen die Leiche Sauls und die Leichen seiner Söhne von der Mauer von Bet-Schean herab. Und sie kamen* nach Jabesch zurück und verbrannten sie dort*.", footnotes: ["w. Männer der Kraft", "LXX, lat. und syr. Üs.: brachten sie", "℘ Jer 34,5"] },
      { number: 13, text: "Und sie nahmen ihre Gebeine und begruben sie unter der Tamariske in Jabesch* und fasteten sieben Tage*.", footnotes: ["℘ 2Sam 21,12", "℘ 1Mo 50,10; 2Sam 1,12"] },
    ]},
  ]
};
